// =====================================================================
// Deuteronômio — tradução dos originais (versificação: Nova Vulgata)
// Formato: {s:"subtítulo"} abre trecho; {v,t,n} prosa; {v,l:[...]} verso;
// np:1 marca início de parágrafo.
// =====================================================================


window.TEXTOS_SEED["deuteronomio"][1] = [
{s:"As palavras que Moisés falou"},
{v:1,t:"Estas são as palavras que Moisés falou a todo o Israel, do outro lado do Jordão, no deserto, na Arabá defronte de Suf, entre Farã, Tofel, Labã, Haserot e Di-Zaab.",n:"O título hebraico do livro é Debarim, palavras, tomado desta primeira frase, como Bemidbar em Números; Deuteronômio vem do grego e traduz a expressão de 17, 18, cópia desta lei, que ali se leu como segunda lei."},
{v:2,t:"Onze dias de caminho há do Horeb, pela estrada da montanha de Seir, até Cades-Barne.",n:"Onze dias, e o povo levou trinta e oito anos. O versículo não comenta nada: põe lado a lado a distância e o tempo, e deixa o leitor tirar a conta."},
{v:3,t:"No quadragésimo ano, no undécimo mês, no primeiro dia do mês, Moisés falou aos filhos de Israel tudo o que o Senhor lhe ordenara que lhes dissesse,"},
{v:4,t:"depois de haver derrotado Seon, rei dos amorreus, que habitava em Hesbon, e Og, rei de Basã, que habitava em Astarot e em Edrai."},
{v:5,t:"Do outro lado do Jordão, na terra de Moab, Moisés começou a explicar esta lei, dizendo:",n:"O verbo hebraico significa gravar com clareza, tornar legível; daí explicar. É a palavra que define o livro inteiro, que não promulga lei nova, mas expõe a do Sinai a quem vai entrar na terra."},
{s:"A ordem de partir do Horeb"},
{v:6,t:"O Senhor nosso Deus falou-nos no Horeb, dizendo: Basta-vos ter ficado neste monte."},
{v:7,t:"Voltai-vos, parti e ide à montanha dos amorreus e a todos os seus vizinhos, na Arabá, na montanha, na Sefelá, no Negueb e na costa do mar, à terra dos cananeus e ao Líbano, até ao grande rio, o rio Eufrates."},
{v:8,t:"Eis que vos entreguei a terra: entrai e tomai posse da terra que o Senhor jurou dar a vossos pais, Abraão, Isaac e Jacó, e à sua descendência depois deles."},
{s:"Os juízes constituídos"},
{v:9,t:"Naquele tempo eu vos disse: Não posso sozinho suportar-vos."},
{v:10,t:"O Senhor vosso Deus vos multiplicou, e hoje sois numerosos como as estrelas do céu."},
{v:11,t:"O Senhor, Deus de vossos pais, acrescente a este número mil vezes mais e vos abençoe, como vos prometeu."},
{v:12,t:"Como poderei eu sozinho carregar o vosso peso, a vossa carga e as vossas contendas?"},
{v:13,t:"Escolhei dentre vós homens sábios, entendidos e experimentados, segundo as vossas tribos, e eu os porei à vossa frente."},
{v:14,t:"Vós me respondestes: Boa é a coisa que queres fazer."},
{v:15,t:"Tomei então os chefes das vossas tribos, homens sábios e experimentados, e os constituí vossos chefes: chefes de mil, chefes de cem, chefes de cinquenta, chefes de dez, e oficiais para as vossas tribos."},
{v:16,t:"Naquele tempo ordenei aos vossos juízes: Ouvi as causas entre os vossos irmãos e julgai com justiça entre um homem e o seu irmão, ou o estrangeiro que está com ele."},
{v:17,t:"Não fareis acepção de pessoas no julgamento: ouvireis tanto o pequeno como o grande, e não temereis ninguém, porque o julgamento é de Deus. A causa que vos for difícil demais, trazei-a a mim, e eu a ouvirei.",n:"O juiz não julga em nome próprio nem em nome do rei: o julgamento é de Deus, e por isso a parcialidade não é apenas injusta, é usurpação. Josafat havia de repetir a frase aos juízes que instituiu."},
{v:18,t:"Naquele tempo vos ordenei tudo o que devíeis fazer."},
{s:"Os exploradores enviados"},
{v:19,t:"Partimos do Horeb e atravessamos todo aquele deserto grande e terrível que vistes, pelo caminho da montanha dos amorreus, como o Senhor nosso Deus nos ordenara; e chegamos a Cades-Barne."},
{v:20,t:"Então eu vos disse: Chegastes à montanha dos amorreus, que o Senhor nosso Deus nos dá."},
{v:21,t:"Vê, o Senhor teu Deus pôs diante de ti a terra: sobe e toma posse dela, como te disse o Senhor, Deus de teus pais; não temas nem te assustes."},
{v:22,t:"Então todos vós vos aproximastes de mim e dissestes: Enviemos homens adiante de nós, para explorarem a terra e nos trazerem notícia do caminho por onde devemos subir e das cidades a que havemos de chegar."},
{v:23,t:"A proposta me pareceu boa, e tomei dentre vós doze homens, um por tribo."},
{v:24,t:"Eles se puseram a caminho, subiram à montanha, chegaram até ao vale de Escol e exploraram a terra."},
{v:25,t:"Tomaram nas mãos dos frutos da terra, trouxeram-nos a nós e nos deram notícia, dizendo: Boa é a terra que o Senhor nosso Deus nos dá.",n:"Em Números são dez os exploradores que desanimam o povo e dois os que confiam; aqui os doze dizem a mesma coisa, e a culpa recai inteira sobre o povo, que ouviu a boa notícia e não quis subir."},
{s:"A recusa do povo"},
{v:26,t:"Vós, porém, não quisestes subir, mas fostes rebeldes à ordem do Senhor vosso Deus."},
{v:27,t:"Murmurastes nas vossas tendas e dissestes: O Senhor nos odeia; por isso nos tirou da terra do Egito, para nos entregar nas mãos dos amorreus e nos destruir.",n:"A acusação vira o êxodo do avesso: a libertação passa a ser armadilha, e o amor que tirou o povo do Egito passa a ser ódio. É a forma acabada da incredulidade."},
{v:28,t:"Para onde havemos de subir? Os nossos irmãos fizeram desfalecer o nosso coração, dizendo: É um povo maior e mais alto do que nós; as cidades são grandes e fortificadas até ao céu; e ainda vimos ali os filhos de Enac."},
{v:29,t:"Eu vos disse: Não vos espanteis nem os temais."},
{v:30,t:"O Senhor vosso Deus, que vai à vossa frente, ele mesmo pelejará por vós, conforme tudo o que fez convosco no Egito diante dos vossos olhos,"},
{v:31,t:"e no deserto, onde viste como o Senhor teu Deus te levou, como um homem leva o seu filho, por todo o caminho que andastes até chegardes a este lugar.",n:"A imagem do pai que carrega o filho cansado é a mais doméstica que o livro usa para Deus; Oseias havia de retomá-la, dizendo que o Senhor ensinou Efraim a andar e o tomou nos braços."},
{v:32,t:"Nem assim crestes no Senhor vosso Deus,"},
{v:33,t:"que ia adiante de vós no caminho, para vos procurar lugar onde armásseis as tendas, de noite no fogo, para vos mostrar o caminho por onde devíeis ir, e de dia na nuvem."},
{s:"O juramento do Senhor"},
{v:34,t:"O Senhor ouviu a voz das vossas palavras e, irado, jurou, dizendo:"},
{v:35,t:"Nenhum destes homens, desta geração má, verá a boa terra que jurei dar a vossos pais,"},
{v:36,t:"exceto Caleb, filho de Jefoné: ele a verá, e a ele e a seus filhos darei a terra que pisou, porque seguiu plenamente o Senhor."},
{v:37,t:"Também contra mim se irou o Senhor por vossa causa, e disse: Nem tu entrarás lá;",n:"Números atribui a exclusão de Moisés à sua própria falta junto às águas de Meribá; o Deuteronômio põe-na três vezes por conta do povo. As duas explicações ficam lado a lado na Escritura, sem que nenhuma apague a outra."},
{v:38,t:"Josué, filho de Nun, que está ao teu serviço, esse entrará lá. Anima-o, porque ele porá Israel na posse da terra."},
{v:39,t:"E os vossos pequeninos, dos quais dissestes que seriam levados cativos, e os vossos filhos, que hoje não sabem distinguir entre o bem e o mal, esses entrarão lá; a eles a darei, e eles a possuirão."},
{v:40,t:"Quanto a vós, voltai e parti para o deserto, pelo caminho do mar Vermelho."},
{s:"A derrota em Horma"},
{v:41,t:"Vós me respondestes: Pecamos contra o Senhor; nós subiremos e pelejaremos, conforme tudo o que o Senhor nosso Deus nos ordenou. E cingistes cada um as suas armas, e vos parecia fácil subir à montanha."},
{v:42,t:"O Senhor me disse: Dize a eles: Não subais nem pelejeis, porque não estou no meio de vós, para que não sejais derrotados diante dos vossos inimigos."},
{v:43,t:"Eu vos falei, e não ouvistes; fostes rebeldes à ordem do Senhor e, cheios de soberba, subistes à montanha."},
{v:44,t:"Então os amorreus, que habitavam naquela montanha, saíram ao vosso encontro, perseguiram-vos como fazem as abelhas e vos esmagaram em Seir, até Horma.",n:"O povo que se recusou a subir quando era mandado sobe quando é proibido; a obediência atrasada é outra forma da mesma desobediência."},
{v:45,t:"Voltastes e chorastes diante do Senhor, mas o Senhor não ouviu a vossa voz nem vos deu ouvidos."},
{v:46,t:"Assim ficastes em Cades muitos dias, todo o tempo que ali permanecestes.",n:"Em meia linha cabem trinta e oito anos. O livro não narra a geração que morreu no deserto: passa por cima dela como quem vira uma página em branco."}
];

window.TEXTOS_SEED["deuteronomio"][2] = [
{s:"A passagem por Edom"},
{v:1,t:"Voltamos e partimos para o deserto, pelo caminho do mar Vermelho, como o Senhor me dissera, e rodeamos a montanha de Seir por muitos dias."},
{v:2,t:"O Senhor me disse:"},
{v:3,t:"Basta de rodeardes esta montanha; voltai-vos para o norte."},
{v:4,t:"E ordena ao povo: Ides passar pelo território de vossos irmãos, os filhos de Esaú, que habitam em Seir, e eles terão medo de vós. Guardai-vos, pois, com muito cuidado:"},
{v:5,t:"não os provoqueis, porque não vos darei da terra deles nem o espaço da planta de um pé, pois dei a Esaú a montanha de Seir em possessão.",n:"Ao povo a quem se promete uma terra inteira nega-se, da terra do irmão, o tamanho de uma pegada. O mesmo Deus que dá também limita, e a herança de Israel não é licença sobre a dos outros."},
{v:6,t:"Comprareis deles por dinheiro os alimentos que comerdes, e também a água que beberdes comprareis deles por dinheiro."},
{v:7,t:"Porque o Senhor teu Deus te abençoou em toda a obra das tuas mãos e conhece a tua caminhada por este grande deserto. Há quarenta anos o Senhor teu Deus está contigo, e nada te faltou."},
{v:8,t:"Passamos, pois, ao largo de nossos irmãos, os filhos de Esaú, que habitam em Seir, deixando o caminho da Arabá, que vem de Elat e de Asiongaber; e, voltando-nos, tomamos o caminho do deserto de Moab."},
{s:"Moab e os filhos de Amon"},
{v:9,t:"O Senhor me disse: Não hostilizes Moab nem entres em guerra contra ele, porque não te darei nada da sua terra em possessão: dei Ar aos filhos de Lot em possessão."},
{v:10,t:"Os emim habitaram nela primeiro, povo grande, numeroso e alto como os enacim;"},
{v:11,t:"também eles passavam por refaim, como os enacim, mas os moabitas os chamam emim."},
{v:12,t:"Em Seir habitaram antes os horreus, que os filhos de Esaú expulsaram; destruíram-nos de diante de si e habitaram em seu lugar, como fez Israel na terra da sua possessão, que o Senhor lhe deu.",n:"Os três parênteses eruditos deste capítulo, sobre os emim, os zomzomim e os caftorim, dizem todos a mesma coisa: também Edom, Moab e Amon entraram em terra de outros, e por dom do mesmo Senhor. A conquista de Israel não é privilégio sem paralelo."},
{v:13,t:"Agora levantai-vos e passai a torrente de Zared. E passamos a torrente de Zared."},
{v:14,t:"O tempo que caminhamos de Cades-Barne até passarmos a torrente de Zared foi de trinta e oito anos, até que se acabou do acampamento toda aquela geração de homens de guerra, como o Senhor lhes jurara."},
{v:15,t:"A mão do Senhor esteve contra eles, para os eliminar do meio do acampamento, até se acabarem."},
{v:16,t:"Quando todos os homens de guerra acabaram de morrer no meio do povo,",np:1},
{v:17,t:"o Senhor falou-me, dizendo:"},
{v:18,t:"Hoje passarás o território de Moab, isto é, Ar,"},
{v:19,t:"e chegarás defronte dos filhos de Amon; não os hostilizes nem os provoques, porque não te darei possessão da terra dos filhos de Amon: dei-a aos filhos de Lot em possessão."},
{v:20,t:"Também ela passava por terra de refaim: nela habitaram outrora os refaim, a quem os amonitas chamam zomzomim,"},
{v:21,t:"povo grande, numeroso e alto como os enacim. O Senhor os destruiu de diante dos amonitas, que os expulsaram e habitaram em seu lugar,"},
{v:22,t:"como fizera pelos filhos de Esaú, que habitam em Seir, quando destruiu os horreus de diante deles: eles os expulsaram e habitaram em seu lugar até ao dia de hoje."},
{v:23,t:"E os heveus, que habitavam em aldeias até Gaza, foram destruídos pelos caftorim, saídos de Caftor, que habitaram em seu lugar.",n:"Caftor é Creta, donde vieram os filisteus; Amós havia de lembrar, na mesma linha, que o Senhor fez sair os filisteus de Caftor como fez sair Israel do Egito."},
{s:"A vitória sobre Seon"},
{v:24,t:"Levantai-vos, parti e passai a torrente do Arnon. Eis que entreguei na tua mão Seon, o amorreu, rei de Hesbon, e a sua terra: começa a tomar posse dela e trava batalha contra ele."},
{v:25,t:"Hoje começarei a lançar o pavor e o temor de ti sobre os povos que estão debaixo de todo o céu, de modo que, ouvindo a tua fama, tremam e se angustiem diante de ti."},
{v:26,t:"Do deserto de Cademot enviei mensageiros a Seon, rei de Hesbon, com palavras de paz, dizendo:"},
{v:27,t:"Deixa-me passar pela tua terra; irei pela estrada, sem me desviar nem para a direita nem para a esquerda."},
{v:28,t:"Vende-me por dinheiro os alimentos que eu comer e dá-me por dinheiro a água que eu beber; deixa-me somente passar a pé,"},
{v:29,t:"como me fizeram os filhos de Esaú, que habitam em Seir, e os moabitas, que habitam em Ar, até que eu passe o Jordão para a terra que o Senhor nosso Deus nos dá."},
{v:30,t:"Mas Seon, rei de Hesbon, não quis deixar-nos passar, porque o Senhor teu Deus lhe endurecera o espírito e lhe obstinara o coração, para o entregar nas tuas mãos, como hoje se vê.",n:"O mesmo que se disse do faraó. A Escritura não separa o endurecimento de quem recusa do desígnio de quem permite: São Paulo havia de retomar o caso na Carta aos Romanos, sem o resolver."},
{v:31,t:"O Senhor me disse: Eis que comecei a entregar-te Seon e a sua terra: começa a tomar posse, para possuíres a sua terra."},
{v:32,t:"Seon saiu ao nosso encontro com todo o seu povo, para pelejar em Jasa,"},
{v:33,t:"e o Senhor nosso Deus o entregou a nós; e o derrotamos, a ele, a seus filhos e a todo o seu povo."},
{v:34,t:"Naquele tempo tomamos todas as suas cidades e votamos ao anátema cada uma delas, homens, mulheres e crianças; não deixamos ninguém com vida,",n:"O anátema é a guerra sagrada, em que nada do vencido se aproveita porque tudo é entregue a Deus. A Escritura o narra sem o atenuar, e a tradição cristã o leu desde cedo como figura da luta contra o pecado, que não admite trégua nem despojo — não como norma de conduta entre povos."},
{v:35,t:"exceto os animais, que tomamos para nós, e os despojos das cidades que havíamos tomado."},
{v:36,t:"Desde Aroer, que está à beira da torrente do Arnon, e a cidade que está no vale, até Galaad, não houve cidade que nos fosse inexpugnável: o Senhor nosso Deus entregou-nos todas."},
{v:37,t:"Somente da terra dos filhos de Amon não te aproximaste, nem de tudo o que está ao longo da torrente do Jaboc, nem das cidades da montanha, nem de nenhum lugar que o Senhor nosso Deus nos proibiu."}
];

window.TEXTOS_SEED["deuteronomio"][3] = [
{s:"A vitória sobre Og de Basã"},
{v:1,t:"Voltamo-nos e subimos pelo caminho de Basã; e Og, rei de Basã, saiu ao nosso encontro com todo o seu povo, para pelejar em Edrai."},
{v:2,t:"O Senhor me disse: Não o temas, porque o entreguei na tua mão, com todo o seu povo e a sua terra; farás com ele como fizeste com Seon, rei dos amorreus, que habitava em Hesbon."},
{v:3,t:"O Senhor nosso Deus entregou nas nossas mãos também Og, rei de Basã, e todo o seu povo; e o derrotamos, até não lhe restar nenhum sobrevivente."},
{v:4,t:"Naquele tempo tomamos todas as suas cidades; não houve cidade que não lhes tomássemos: sessenta cidades, toda a região de Argob, o reino de Og em Basã."},
{v:5,t:"Todas essas cidades eram fortificadas com muros altos, portas e trancas, sem contar as inúmeras aldeias sem muros."},
{v:6,t:"Votamo-las ao anátema, como tínhamos feito a Seon, rei de Hesbon, destruindo cada cidade, com os homens, as mulheres e as crianças;"},
{v:7,t:"mas tomamos para nós os animais e os despojos das cidades."},
{v:8,t:"Naquele tempo tomamos das mãos dos dois reis dos amorreus a terra que está do outro lado do Jordão, desde a torrente do Arnon até ao monte Hermon"},
{v:9,t:"— os sidônios chamam ao Hermon Sarion, e os amorreus chamam-lhe Sanir —"},
{v:10,t:"todas as cidades do planalto, toda a Galaad e toda a Basã, até Salca e Edrai, cidades do reino de Og em Basã."},
{v:11,t:"Só Og, rei de Basã, tinha restado dos refaim. Eis que o seu leito, leito de ferro, está em Rabá dos filhos de Amon: tem nove côvados de comprimento e quatro de largura, pelo côvado comum.",n:"Nove côvados são perto de quatro metros. A nota do escriba tem ar de guia de viagem: quem duvidar que vá a Rabá e meça. Alguns entendem que se trate antes de um sarcófago de basalto, a pedra negra da região, que passasse por ferro aos olhos de quem a via."},
{s:"A terra do outro lado do Jordão"},
{v:12,t:"Naquele tempo tomamos posse desta terra, desde Aroer, que está à beira da torrente do Arnon, e dei a Rúben e a Gad metade da montanha de Galaad com as suas cidades."},
{v:13,t:"O resto de Galaad e toda a Basã, o reino de Og, dei à meia tribo de Manassés: toda a região de Argob. A Basã inteira chamava-se terra dos refaim."},
{v:14,t:"Jair, filho de Manassés, tomou toda a região de Argob, até à fronteira dos gessuritas e dos macatitas, e chamou-a, do seu próprio nome, Havot-Jair, isto é, aldeias de Jair, como se chama até ao dia de hoje."},
{v:15,t:"A Maquir dei Galaad."},
{v:16,t:"Às tribos de Rúben e de Gad dei desde Galaad até à torrente do Arnon, ficando o meio da torrente por limite, e até à torrente do Jaboc, que é a fronteira dos filhos de Amon;"},
{v:17,t:"e ainda a Arabá, tendo o Jordão por limite, desde Ceneret até ao mar da Arabá, que é o mar Salgado, ao pé das encostas do Fasga, ao oriente."},
{v:18,t:"Naquele tempo vos ordenei: O Senhor vosso Deus vos deu esta terra em herança; ide armados à frente de vossos irmãos, os filhos de Israel, todos os homens válidos."},
{v:19,t:"Somente as vossas mulheres, os vossos pequeninos e o vosso gado — sei que tendes muito gado — ficarão nas cidades que vos dei,"},
{v:20,t:"até que o Senhor dê descanso a vossos irmãos, como deu a vós, e também eles possuam a terra que o Senhor vosso Deus lhes dá do outro lado do Jordão; então voltareis cada um à possessão que vos dei."},
{s:"Josué animado"},
{v:21,t:"Naquele tempo ordenei também a Josué: Os teus olhos viram tudo o que o Senhor vosso Deus fez a estes dois reis; assim fará a todos os reinos por onde hás de passar."},
{v:22,t:"Não os temais, porque o Senhor vosso Deus é quem peleja por vós."},
{s:"A oração de Moisés não atendida"},
{v:23,t:"Naquele tempo supliquei ao Senhor, dizendo:"},
{v:24,t:"Senhor Deus, tu começaste a mostrar ao teu servo a tua grandeza e a tua mão forte; que Deus há no céu ou na terra que faça segundo as tuas obras e segundo os teus feitos poderosos?"},
{v:25,t:"Deixa-me, pois, passar e ver a boa terra que está do outro lado do Jordão, aquela excelente montanha e o Líbano."},
{v:26,t:"Mas o Senhor irou-se contra mim por vossa causa e não me ouviu; e disse-me: Basta! Não me fales mais neste assunto.",n:"A única oração de Moisés que a Escritura registra como recusada, e é a que ele faz por si. Intercedeu pelo povo e foi atendido tantas vezes; pede uma coisa para si e ouve: basta."},
{v:27,t:"Sobe ao cume do Fasga, levanta os olhos para o poente, o norte, o sul e o oriente, e olha com os teus olhos, porque não passarás este Jordão."},
{v:28,t:"Dá ordens a Josué, anima-o e fortalece-o, porque ele irá à frente deste povo e lhe repartirá a terra que verás."},
{v:29,t:"E ficamos no vale, defronte de Bet-Fogor."}
];

window.TEXTOS_SEED["deuteronomio"][4] = [
{s:"Exortação a guardar a lei"},
{v:1,t:"Agora, Israel, ouve os estatutos e as normas de direito que eu vos ensino, para que, pondo-os por obra, vivais e entreis a possuir a terra que o Senhor, Deus de vossos pais, vos dá."},
{v:2,t:"Não acrescentareis nada à palavra que vos digo, nem tirareis nada dela; guardai os mandamentos do Senhor vosso Deus, que eu vos ordeno.",n:"A fórmula é das cláusulas de guarda dos tratados antigos, postas para que ninguém mexesse no texto jurado; a Escritura a retoma em 13, 1 e o Apocalipse a põe na sua última página. É o primeiro enunciado do que depois se chamaria cânon."},
{v:3,t:"Os vossos olhos viram o que o Senhor fez por causa de Baal-Fogor: a todo homem que seguiu Baal-Fogor o Senhor teu Deus destruiu do meio de ti;"},
{v:4,t:"mas vós, que estais unidos ao Senhor vosso Deus, estais todos vivos hoje."},
{v:5,t:"Eis que vos ensinei estatutos e normas de direito, como o Senhor meu Deus me ordenou, para que assim procedais na terra em que ides entrar para a possuir."},
{v:6,t:"Guardai-os e ponde-os por obra, porque nisto está a vossa sabedoria e o vosso entendimento aos olhos dos povos, que, ouvindo todos estes estatutos, dirão: Este grande povo é de fato uma nação sábia e inteligente."},
{v:7,t:"Pois que grande nação há que tenha deuses tão próximos dela como o Senhor nosso Deus está de nós sempre que o invocamos?"},
{v:8,t:"E que grande nação há que tenha estatutos e normas de direito tão justos como toda esta lei que hoje ponho diante de vós?",n:"O argumento é insólito na Escritura: a lei é dada como razão para que os de fora admirem. A grandeza de Israel não está no tamanho nem nas armas, mas em ter perto de si o seu Deus e um direito que se sustente diante de quem o examine."},
{s:"O Horeb e a proibição das imagens"},
{v:9,t:"Somente guarda-te e guarda bem a tua alma, para que não te esqueças das coisas que os teus olhos viram, nem elas te saiam do coração em todos os dias da tua vida; e ensina-as a teus filhos e aos filhos de teus filhos."},
{v:10,t:"Lembra-te do dia em que estiveste diante do Senhor teu Deus no Horeb, quando o Senhor me disse: Reúne o povo diante de mim, para que eu lhe faça ouvir as minhas palavras e aprendam a temer-me todos os dias que viverem sobre a terra, e as ensinem a seus filhos."},
{v:11,t:"Vós vos aproximastes e ficastes ao pé do monte, e o monte ardia em fogo até ao coração do céu, com trevas, nuvem e escuridão."},
{v:12,t:"O Senhor vos falou do meio do fogo: ouvistes a voz das palavras, mas figura nenhuma vistes; havia somente uma voz.",n:"Aqui está a razão de toda a proibição das imagens: no Sinai houve palavra e não houve forma. Quem faz de Deus uma figura põe no lugar do que ouviu algo que não viu."},
{v:13,t:"E vos anunciou a sua aliança, que vos mandou cumprir, as dez palavras, e as escreveu em duas tábuas de pedra.",n:"Dez palavras: é a expressão hebraica que o grego verteu por decálogo. A Escritura não as chama mandamentos aqui, mas palavras."},
{v:14,t:"E a mim, naquele tempo, o Senhor ordenou que vos ensinasse os estatutos e as normas de direito, para que os cumprísseis na terra em que ides entrar para a possuir."},
{v:15,t:"Guardai, pois, com muito cuidado as vossas almas, porque nenhuma figura vistes no dia em que o Senhor vos falou no Horeb, do meio do fogo,"},
{v:16,t:"para que não vos corrompais e façais para vós alguma imagem esculpida, figura de macho ou de fêmea,"},
{v:17,t:"figura de algum animal que há na terra, figura de alguma ave que voa pelo céu,"},
{v:18,t:"figura de algum réptil que rasteja pelo chão, figura de algum peixe que há nas águas debaixo da terra."},
{v:19,t:"E para que, levantando os olhos ao céu e vendo o sol, a lua e as estrelas, todo o exército do céu, não sejas arrastado a prostrar-te diante deles e a servi-los: o Senhor teu Deus os repartiu a todos os povos debaixo de todo o céu.",n:"Verso difícil: os astros foram dados aos povos, e a Israel foi dado o Senhor. Os antigos leram nele uma condescendência provisória; o Cântico de Moisés, no capítulo 32, volta ao mesmo repartir das nações."},
{v:20,t:"Mas a vós o Senhor vos tomou e vos tirou da fornalha de ferro do Egito, para serdes o povo da sua herança, como hoje se vê.",n:"A fornalha de ferro não é a que fabrica ferro, mas a de fundir, cujas paredes eram de ferro: imagem do calor que separa o metal da escória. Jeremias e o primeiro livro dos Reis repetem a expressão."},
{v:21,t:"O Senhor irou-se contra mim por causa das vossas palavras e jurou que eu não passaria o Jordão nem entraria na boa terra que o Senhor teu Deus te dá em herança."},
{v:22,t:"Eu morrerei nesta terra e não passarei o Jordão; vós o passareis e possuireis esta boa terra."},
{v:23,t:"Guardai-vos de esquecer a aliança que o Senhor vosso Deus fez convosco, e de fazer para vós alguma imagem esculpida, figura de qualquer coisa que o Senhor teu Deus te proibiu;"},
{v:24,t:"porque o Senhor teu Deus é fogo devorador, Deus zeloso.",n:"A Carta aos Hebreus fecha com esta mesma frase a sua última advertência: o nosso Deus é fogo devorador. O zelo de que se fala é o do esposo, não o do tirano."},
{s:"O exílio anunciado e a volta"},
{v:25,t:"Quando gerardes filhos e netos e tiverdes envelhecido na terra, se vos corromperdes e fizerdes alguma imagem esculpida, fazendo o mal aos olhos do Senhor teu Deus, para o provocar à ira,"},
{v:26,t:"tomo hoje por testemunhas contra vós o céu e a terra: depressa perecereis de todo na terra que ides possuir, passado o Jordão; não durareis muito tempo nela, mas sereis destruídos."},
{v:27,t:"O Senhor vos dispersará entre os povos, e restareis poucos no meio das nações aonde o Senhor vos levar."},
{v:28,t:"E ali servireis a deuses feitos por mãos de homens, de madeira e de pedra, que não veem, nem ouvem, nem comem, nem cheiram.",n:"A ironia é a de sempre contra os ídolos: têm os órgãos todos e não lhes servem de nada. Quem os faz recebe em castigo aquilo mesmo que escolheu."},
{v:29,t:"Mas dali buscarás o Senhor teu Deus, e o acharás, se o buscares de todo o teu coração e de toda a tua alma.",n:"Jeremias escreveria aos desterrados da Babilônia quase com estas palavras: vós me buscareis e me achareis, quando me buscardes de todo o vosso coração. O exílio não é o fim da aliança, é o lugar onde ela se busca outra vez."},
{v:30,t:"Quando estiveres em angústia e todas estas coisas te sobrevierem, nos últimos dias voltarás ao Senhor teu Deus e ouvirás a sua voz;"},
{v:31,t:"porque o Senhor teu Deus é Deus misericordioso: não te desamparará nem te destruirá, nem se esquecerá da aliança que jurou a teus pais."},
{s:"O Senhor é Deus, e não há outro"},
{v:32,t:"Pergunta aos tempos antigos, que foram antes de ti, desde o dia em que Deus criou o homem sobre a terra, e de um extremo do céu ao outro: aconteceu jamais coisa tão grande, ou ouviu-se alguma vez outra igual?"},
{v:33,t:"Algum povo ouviu a voz de Deus falando do meio do fogo, como tu a ouviste, e ficou vivo?"},
{v:34,t:"Ou tentou algum deus vir tomar para si uma nação do meio de outra nação, com provas, sinais e prodígios, com guerra, mão forte e braço estendido, e com grandes terrores, conforme tudo o que o Senhor vosso Deus fez por vós no Egito, diante dos teus olhos?"},
{v:35,t:"A ti te foi mostrado, para que soubesses que o Senhor é Deus, e não há outro além dele."},
{v:36,t:"Do céu te fez ouvir a sua voz, para te instruir; na terra te mostrou o seu grande fogo, e ouviste as suas palavras do meio do fogo."},
{v:37,t:"Porque amou teus pais e escolheu a descendência deles depois deles, ele mesmo te tirou do Egito com a sua presença e com a sua grande força,"},
{v:38,t:"para expulsar diante de ti nações maiores e mais fortes do que tu, para te introduzir e te dar a terra delas em herança, como hoje se vê."},
{v:39,t:"Sabe, pois, hoje, e medita no teu coração que o Senhor é Deus em cima no céu e embaixo na terra, e não há outro."},
{v:40,t:"Guarda os seus estatutos e os seus mandamentos, que hoje te ordeno, para que te vá bem, a ti e a teus filhos depois de ti, e para que prolongues os teus dias na terra que o Senhor teu Deus te dá para sempre."},
{s:"As cidades de refúgio do outro lado do Jordão"},
{v:41,t:"Então Moisés separou três cidades do outro lado do Jordão, ao oriente,"},
{v:42,t:"para que nelas se refugiasse o homicida que matasse o seu próximo sem querer, sem lhe ter tido ódio de antes, e que, fugindo para uma dessas cidades, salvasse a vida:"},
{v:43,t:"Bosor, no deserto, na terra do planalto, para os rubenitas; Ramot, em Galaad, para os gaditas; e Golã, em Basã, para os de Manassés."},
{s:"O segundo discurso: a lei proposta"},
{v:44,t:"Esta é a lei que Moisés pôs diante dos filhos de Israel;"},
{v:45,t:"estes são os testemunhos, os estatutos e as normas de direito que Moisés falou aos filhos de Israel, depois que saíram do Egito,"},
{v:46,t:"do outro lado do Jordão, no vale defronte de Bet-Fogor, na terra de Seon, rei dos amorreus, que habitava em Hesbon, a quem Moisés e os filhos de Israel derrotaram depois de saírem do Egito."},
{v:47,t:"Tomaram posse da terra dele e da terra de Og, rei de Basã, os dois reis dos amorreus que estavam do outro lado do Jordão, ao oriente,"},
{v:48,t:"desde Aroer, que está à beira da torrente do Arnon, até ao monte Sion, que é o Hermon,"},
{v:49,t:"com toda a Arabá do outro lado do Jordão, ao oriente, até ao mar da Arabá, ao pé das encostas do Fasga."}
];

window.TEXTOS_SEED["deuteronomio"][5] = [
{s:"A aliança do Horeb"},
{v:1,t:"Moisés convocou todo o Israel e disse a eles: Ouve, Israel, os estatutos e as normas de direito que hoje falo aos vossos ouvidos; aprendei-os e ponde-os por obra."},
{v:2,t:"O Senhor nosso Deus fez conosco aliança no Horeb."},
{v:3,t:"Não foi com nossos pais que o Senhor fez esta aliança, mas conosco, que estamos aqui hoje, todos nós vivos.",n:"A frase é a chave do livro: cada geração que ouve a lei está no Horeb pela primeira vez. A Hagadá da Páscoa dirá o mesmo, mandando que cada um se tenha por saído do Egito em pessoa."},
{v:4,t:"Face a face o Senhor vos falou no monte, do meio do fogo."},
{v:5,t:"Eu estava naquele tempo entre o Senhor e vós, para vos anunciar a palavra dele, porque temestes o fogo e não subistes ao monte. E ele disse:"},
{s:"As dez palavras"},
{v:6,t:"Eu sou o Senhor teu Deus, que te tirei da terra do Egito, da casa da servidão.",n:"A lei começa por uma notícia, não por uma ordem: antes de mandar seja o que for, Deus diz quem é e o que fez. Tudo o que vem depois é a forma de viver de um povo que foi tirado do cativeiro."},
{v:7,t:"Não terás outros deuses diante de mim."},
{v:8,t:"Não farás para ti imagem esculpida, nem figura alguma do que há em cima no céu, nem embaixo na terra, nem nas águas debaixo da terra."},
{v:9,t:"Não te prostrarás diante delas nem as servirás, porque eu, o Senhor teu Deus, sou Deus zeloso, que castigo a iniquidade dos pais nos filhos até à terceira e quarta geração daqueles que me odeiam,"},
{v:10,t:"e uso de misericórdia até mil gerações com os que me amam e guardam os meus mandamentos.",n:"Quatro gerações de castigo, mil de misericórdia: a desproporção é o próprio argumento. Ezequiel e Jeremias haviam de recusar depois a máxima de que os filhos paguem pelos pais."},
{v:11,t:"Não tomarás em vão o nome do Senhor teu Deus, porque o Senhor não terá por inocente aquele que tomar o seu nome em vão."},
{v:12,t:"Guarda o dia de sábado, para o santificar, como o Senhor teu Deus te ordenou.",n:"O Êxodo diz lembra-te; aqui diz guarda. A tradição judaica ensina que as duas palavras foram ditas de um só fôlego, e o canto com que se recebe o sábado na sexta-feira à tarde começa justamente por elas."},
{v:13,t:"Seis dias trabalharás e farás toda a tua obra;"},
{v:14,t:"mas o sétimo dia é sábado do Senhor teu Deus: não farás nele obra alguma, nem tu, nem teu filho, nem tua filha, nem o teu servo, nem a tua serva, nem o teu boi, nem o teu jumento, nem animal algum teu, nem o estrangeiro que está dentro das tuas portas, para que o teu servo e a tua serva descansem como tu."},
{v:15,t:"Lembra-te de que foste servo na terra do Egito, e que o Senhor teu Deus te tirou dali com mão forte e braço estendido; por isso o Senhor teu Deus te ordenou que guardasses o dia de sábado.",n:"No Êxodo o sábado se funda no descanso da criação; aqui, na libertação do Egito. Daí o acréscimo próprio deste texto, que o dia é para que o servo descanse como tu: quem foi escravo não pode transformar o seu descanso em serviço alheio."},
{v:16,t:"Honra teu pai e tua mãe, como o Senhor teu Deus te ordenou, para que se prolonguem os teus dias e para que te vá bem na terra que o Senhor teu Deus te dá."},
{v:17,t:"Não matarás."},
{v:18,t:"Não cometerás adultério."},
{v:19,t:"Não furtarás."},
{v:20,t:"Não dirás falso testemunho contra o teu próximo."},
{v:21,t:"Não cobiçarás a mulher do teu próximo; não desejarás a casa do teu próximo, nem o seu campo, nem o seu servo, nem a sua serva, nem o seu boi, nem o seu jumento, nem coisa alguma que seja do teu próximo.",n:"O Êxodo põe a casa em primeiro lugar e a mulher entre os bens dela; aqui a mulher vem à frente, separada por verbo próprio, e a casa abre a lista das posses. É a diferença mais clara entre as duas redações do decálogo."},
{s:"O temor do povo"},
{v:22,t:"Estas palavras o Senhor falou a toda a vossa assembleia, no monte, do meio do fogo, da nuvem e da escuridão, com voz forte, e nada acrescentou; escreveu-as em duas tábuas de pedra e as deu a mim.",n:"E nada acrescentou. O decálogo fica por si, fechado; o resto do livro é explicação dele, dada por meio de Moisés, não outra revelação."},
{v:23,t:"Ouvindo vós a voz do meio das trevas, enquanto o monte ardia em fogo, aproximastes-vos de mim, todos os chefes das vossas tribos e os vossos anciãos,"},
{v:24,t:"e dissestes: Eis que o Senhor nosso Deus nos mostrou a sua glória e a sua grandeza, e ouvimos a sua voz do meio do fogo; hoje vimos que Deus fala com o homem e este continua vivo."},
{v:25,t:"Mas agora, por que havemos de morrer? Este grande fogo nos consumirá. Se continuarmos a ouvir a voz do Senhor nosso Deus, morreremos."},
{v:26,t:"Pois que é todo o mortal, para ouvir a voz do Deus vivo falando do meio do fogo, como nós a ouvimos, e continuar vivo?"},
{v:27,t:"Aproxima-te tu e ouve tudo o que disser o Senhor nosso Deus; e tu nos dirás tudo o que o Senhor nosso Deus te disser, e nós o ouviremos e o cumpriremos.",n:"Daqui nasce o ofício do mediador, e com ele o do profeta, que o capítulo 18 há de prometer. O povo pede um intermediário porque a voz direta o mata, e o pedido é aprovado."},
{v:28,t:"O Senhor ouviu a voz das vossas palavras quando me faláveis, e me disse: Ouvi a voz das palavras deste povo, o que te disseram: é bom tudo o que disseram."},
{v:29,t:"Quem dera que tivessem tal coração, para me temerem e guardarem sempre todos os meus mandamentos, para que lhes fosse bem, a eles e a seus filhos, para sempre!",n:"Um dos raros lugares em que a Escritura põe em Deus o desejo do impossível. O capítulo 30 responderá a este suspiro, prometendo que o próprio Senhor circuncidará o coração do povo."},
{v:30,t:"Vai e dize a eles: Voltai às vossas tendas."},
{v:31,t:"Tu, porém, fica aqui comigo, e eu te direi todos os mandamentos, os estatutos e as normas de direito que lhes hás de ensinar, para que os cumpram na terra que lhes dou em possessão."},
{v:32,t:"Cuidai, pois, de fazer como o Senhor vosso Deus vos ordenou; não vos desvieis nem para a direita nem para a esquerda."},
{v:33,t:"Andareis por todo o caminho que o Senhor vosso Deus vos ordenou, para que vivais, e vos vá bem, e prolongueis os vossos dias na terra que haveis de possuir."}
];

window.TEXTOS_SEED["deuteronomio"][6] = [
{s:"O fim da lei"},
{v:1,t:"Estes são os mandamentos, os estatutos e as normas de direito que o Senhor vosso Deus mandou que eu vos ensinasse, para que os cumprais na terra a que passais para a possuir;"},
{v:2,t:"para que temas o Senhor teu Deus e guardes, todos os dias da tua vida, tu, teu filho e o filho de teu filho, todos os seus estatutos e mandamentos que eu te ordeno, e para que se prolonguem os teus dias."},
{v:3,t:"Ouve, pois, Israel, e cuida de os cumprir, para que te vá bem e te multipliques muito na terra que mana leite e mel, como te prometeu o Senhor, Deus de teus pais."},
{s:"Ouve, Israel"},
{v:4,t:"Ouve, Israel: o Senhor nosso Deus é o único Senhor.",n:"A frase hebraica tem quatro palavras e admite mais de uma construção: o Senhor nosso Deus, o Senhor é um; ou o Senhor é nosso Deus, o Senhor é um só. Sigo a Nova Vulgata. É a confissão que o judeu recita de manhã e de noite e procura dizer ao morrer, e que o Senhor Jesus citou como o primeiro de todos os mandamentos."},
{v:5,t:"Amarás o Senhor teu Deus de todo o teu coração, de toda a tua alma e de todas as tuas forças.",n:"Único lugar do Pentateuco em que se manda amar a Deus. O grego dos Setenta desdobrou a terceira expressão, e daí vem o entendimento que os evangelhos citam, com quatro termos: coração, alma, mente e forças."},
{v:6,t:"Estas palavras que hoje te ordeno estarão no teu coração;"},
{v:7,t:"tu as inculcarás a teus filhos e delas falarás sentado em tua casa e andando pelo caminho, ao deitar-te e ao levantar-te;"},
{v:8,t:"tu as atarás como sinal na tua mão, e serão como faixa entre os teus olhos;"},
{v:9,t:"e as escreverás nos umbrais da tua casa e nas tuas portas.",n:"Israel tomou estas duas ordens à letra: dos versos 8 e 9 vêm os filactérios, que se atam ao braço e à testa para a oração, e a mezuzá, o estojo com o texto pregado à ombreira da porta, que se toca ao entrar e ao sair."},
{s:"Guarda-te de esquecer"},
{v:10,t:"Quando o Senhor teu Deus te introduzir na terra que jurou a teus pais, Abraão, Isaac e Jacó, dar-te cidades grandes e boas, que não edificaste,"},
{v:11,t:"casas cheias de todo bem, que não encheste, cisternas cavadas, que não cavaste, vinhas e olivais, que não plantaste; e quando comeres e te fartares,"},
{v:12,t:"guarda-te de esqueceres o Senhor, que te tirou da terra do Egito, da casa da servidão.",n:"O perigo não é a fome, é a fartura. Todo o livro volta a este ponto: a terra é o lugar onde se esquece quem a deu, porque nela tudo parece vir de si mesmo."},
{v:13,t:"Ao Senhor teu Deus temerás, a ele servirás e pelo seu nome jurarás.",n:"Palavra com que o Senhor Jesus responde à última tentação no deserto, e a seguinte, do verso 16, com que responde à segunda: as três respostas vêm todas deste livro, e todas deste trecho."},
{v:14,t:"Não seguireis outros deuses, dentre os deuses dos povos que estão ao vosso redor,"},
{v:15,t:"porque o Senhor teu Deus, no meio de ti, é Deus zeloso; para que a ira do Senhor teu Deus não se acenda contra ti e te destrua da face da terra."},
{v:16,t:"Não tentareis o Senhor vosso Deus, como o tentastes em Massá.",n:"Massá quer dizer prova; é o lugar onde o povo pediu água perguntando se o Senhor estava ou não no meio dele. Tentar a Deus é exigir-lhe sinais para crer no que já se viu."},
{v:17,t:"Guardai cuidadosamente os mandamentos do Senhor vosso Deus, os seus testemunhos e os estatutos que te ordenou;"},
{v:18,t:"faze o que é reto e bom aos olhos do Senhor, para que te vá bem, e entres e possuas a boa terra que o Senhor jurou a teus pais,"},
{v:19,t:"expulsando todos os teus inimigos de diante de ti, como o Senhor disse."},
{s:"Quando teu filho te perguntar"},
{v:20,t:"Quando amanhã teu filho te perguntar: Que significam os testemunhos, os estatutos e as normas de direito que o Senhor nosso Deus vos ordenou?"},
{v:21,t:"responderás a teu filho: Éramos escravos do faraó no Egito, e o Senhor nos tirou do Egito com mão forte;",n:"À pergunta pelo sentido da lei a resposta não é uma doutrina, é uma história. A liturgia da Páscoa judaica armou sobre estes versos o seu diálogo entre o pai e o filho."},
{v:22,t:"o Senhor fez diante dos nossos olhos sinais e prodígios grandes e terríveis contra o Egito, contra o faraó e contra toda a sua casa;"},
{v:23,t:"e a nós nos tirou dali, para nos introduzir e nos dar a terra que jurara a nossos pais."},
{v:24,t:"O Senhor nos ordenou que cumpríssemos todos estes estatutos e temêssemos o Senhor nosso Deus, para que nos fosse bem todos os dias e nos conservasse em vida, como hoje se vê."},
{v:25,t:"E será a nossa justiça se cuidarmos de cumprir todos estes mandamentos diante do Senhor nosso Deus, como ele nos ordenou."}
];

window.TEXTOS_SEED["deuteronomio"][7] = [
{s:"Nenhum pacto com as nações"},
{v:1,t:"Quando o Senhor teu Deus te introduzir na terra a que vais para a possuir, e expulsar de diante de ti muitas nações — os heteus, os gergeseus, os amorreus, os cananeus, os ferezeus, os heveus e os jebuseus, sete nações mais numerosas e mais fortes do que tu —,",n:"A lista dos sete povos é fórmula fixa, repetida com variantes por todo o Pentateuco. A arqueologia mostra que vários deles já não existiam quando o livro tomou a forma que tem: a lista é menos um censo do que o nome do que Israel devia recusar."},
{v:2,t:"e o Senhor teu Deus os entregar a ti e os derrotares, tu os votarás ao anátema: não farás com eles aliança nem lhes terás piedade."},
{v:3,t:"Não contrairás com eles matrimônios: não darás tua filha a filho deles, nem tomarás a filha deles para teu filho,"},
{v:4,t:"porque ela desviaria teu filho de me seguir, e ele serviria a outros deuses; então a ira do Senhor se acenderia contra vós e depressa te destruiria.",n:"Aqui se vê o que a lei de fato teme. A proibição não se funda em raça, mas em culto: o que se recusa é o deus que vem junto com o casamento. Rute, moabita, será bisavó de Davi."},
{v:5,t:"Assim, porém, fareis com eles: derrubareis os seus altares, quebrareis as suas estelas, cortareis os seus postes sagrados e queimareis no fogo as suas imagens esculpidas;"},
{s:"O povo escolhido"},
{v:6,t:"porque tu és um povo santo para o Senhor teu Deus. O Senhor teu Deus te escolheu para seres o seu povo, a sua propriedade particular, dentre todos os povos que há sobre a face da terra."},
{v:7,t:"Não foi por serdes mais numerosos que todos os povos que o Senhor se afeiçoou a vós e vos escolheu, pois éreis o menor de todos os povos;"},
{v:8,t:"mas porque o Senhor vos amou e guardou o juramento que fez a vossos pais, por isso vos tirou com mão forte e te resgatou da casa da servidão, da mão do faraó, rei do Egito.",n:"A razão da escolha é o amor, e a razão do amor é o amor: o argumento anda em círculo de propósito, porque não há causa anterior a que apelar. Israel é escolhido por ser pequeno, não apesar de o ser."},
{v:9,t:"Sabe, pois, que o Senhor teu Deus é Deus, o Deus fiel, que guarda a aliança e a misericórdia até mil gerações aos que o amam e guardam os seus mandamentos,"},
{v:10,t:"e que retribui na própria pessoa àquele que o odeia, destruindo-o; não tardará com aquele que o odeia: na própria pessoa lhe dará o pago."},
{v:11,t:"Guarda, pois, os mandamentos, os estatutos e as normas de direito que hoje te ordeno cumprir."},
{s:"A bênção da fidelidade"},
{v:12,t:"Se ouvirdes estas normas de direito, as guardardes e as cumprirdes, o Senhor teu Deus guardará contigo a aliança e a misericórdia que jurou a teus pais."},
{v:13,t:"Ele te amará, te abençoará e te multiplicará; abençoará o fruto do teu ventre e o fruto da tua terra, o teu trigo, o teu vinho e o teu azeite, as crias das tuas vacas e dos teus rebanhos, na terra que jurou a teus pais dar-te."},
{v:14,t:"Serás abençoado mais que todos os povos: não haverá em ti estéril, nem homem nem mulher, nem entre os teus animais."},
{v:15,t:"O Senhor apartará de ti toda enfermidade, e nenhuma das péssimas doenças do Egito, que conheceste, porá sobre ti; mas as porá sobre todos os que te odeiam."},
{v:16,t:"Devorarás todos os povos que o Senhor teu Deus te entregar; o teu olho não terá piedade deles, e não servirás aos seus deuses, porque isso seria um laço para ti."},
{s:"Não temas"},
{v:17,t:"Se disseres no teu coração: Estas nações são mais numerosas do que eu; como poderei expulsá-las?"},
{v:18,t:"não as temas; lembra-te bem do que o Senhor teu Deus fez ao faraó e a todo o Egito:"},
{v:19,t:"das grandes provações que os teus olhos viram, dos sinais e prodígios, da mão forte e do braço estendido com que o Senhor teu Deus te tirou. Assim fará o Senhor teu Deus a todos os povos que temes."},
{v:20,t:"E ainda enviará o Senhor teu Deus vespas contra eles, até que pereçam os que restarem e os que se esconderem de ti.",n:"A palavra hebraica ocorre três vezes na Escritura e ninguém sabe ao certo o que seja; uns entendem vespas, outros o pânico, outros a peste, e alguns o próprio exército do Egito, cujo emblema era a abelha."},
{v:21,t:"Não te assustes diante deles, porque o Senhor teu Deus está no meio de ti, Deus grande e terrível."},
{v:22,t:"O Senhor teu Deus expulsará essas nações de diante de ti pouco a pouco; não poderás destruí-las depressa, para que as feras do campo não se multipliquem contra ti.",n:"Uma terra esvaziada de uma vez volta ao mato. A ressalva é de bom senso agrário, e serve de correção ao ímpeto das linhas anteriores."},
{v:23,t:"O Senhor teu Deus os entregará diante de ti e os lançará em grande confusão, até serem destruídos."},
{v:24,t:"Entregará os seus reis nas tuas mãos, e farás perecer os nomes deles debaixo do céu; ninguém te poderá resistir, até que os destruas."},
{v:25,t:"Queimarás no fogo as imagens esculpidas dos seus deuses; não cobiçarás a prata nem o ouro que as revestem, nem os tomarás para ti, para que não caias por causa deles, porque é abominação para o Senhor teu Deus."},
{v:26,t:"Não meterás em tua casa essa abominação, para não seres anátema como ela; hás de tê-la por coisa abominável e detestável, porque é anátema.",n:"O caso de Acã, que escondeu na tenda o ouro de Jericó e arrastou consigo a casa toda, é a ilustração narrativa deste verso no livro de Josué."}
];

window.TEXTOS_SEED["deuteronomio"][8] = [
{s:"A lembrança do deserto"},
{v:1,t:"Cuidai de cumprir todos os mandamentos que hoje te ordeno, para que vivais, vos multipliqueis, entreis e possuais a terra que o Senhor jurou a vossos pais."},
{v:2,t:"Lembra-te de todo o caminho por onde o Senhor teu Deus te conduziu nestes quarenta anos pelo deserto, para te humilhar e te provar, para saber o que havia no teu coração, se havias de guardar os seus mandamentos ou não."},
{v:3,t:"Ele te humilhou, te deixou passar fome e te sustentou com o maná, que nem tu nem teus pais conhecíeis, para te ensinar que não só de pão vive o homem, mas de tudo o que sai da boca do Senhor.",n:"A primeira resposta do Senhor Jesus ao tentador. O verso não despreza o pão: diz que também o pão do deserto foi palavra, coisa dada, e que quem come sem reconhecer a mão que dá ainda não sabe do que vive."},
{v:4,t:"A tua roupa não se gastou sobre ti, nem se inchou o teu pé, nestes quarenta anos."},
{v:5,t:"Reconhece, pois, no teu coração que, como um homem corrige o seu filho, assim o Senhor teu Deus te corrige;"},
{v:6,t:"guarda os mandamentos do Senhor teu Deus, andando nos seus caminhos e temendo-o."},
{s:"A terra boa"},
{v:7,t:"Porque o Senhor teu Deus te introduz numa terra boa, terra de torrentes de águas, de fontes e de mananciais que brotam nos vales e nas montanhas;"},
{v:8,t:"terra de trigo e de cevada, de vinhas, figueiras e romãzeiras; terra de oliveiras, de azeite e de mel;"},
{v:9,t:"terra em que comerás o pão sem escassez e nada te faltará; terra cujas pedras são ferro e de cujos montes cavarás o cobre.",n:"As sete espécies destes dois versos — trigo, cevada, uva, figo, romã, azeitona e mel de tâmara — ficaram sendo na tradição judaica os frutos próprios da terra, pelos quais se diz bênção à parte."},
{v:10,t:"Comerás e te fartarás, e bendirás o Senhor teu Deus pela boa terra que te deu.",n:"Deste verso tirou Israel a obrigação de dar graças depois da refeição, e não apenas antes: a bênção vem quando já se está farto, que é justamente quando se esquece."},
{s:"Guarda-te, na fartura, de esquecer"},
{v:11,t:"Guarda-te de esqueceres o Senhor teu Deus, deixando de observar os seus mandamentos, as suas normas de direito e os seus estatutos, que hoje te ordeno;"},
{v:12,t:"para que, depois de teres comido e te teres fartado, de teres edificado boas casas e nelas habitado,"},
{v:13,t:"de se terem multiplicado as tuas vacas e as tuas ovelhas, de teres em abundância prata, ouro e todas as coisas,"},
{v:14,t:"não se levante o teu coração e te esqueças do Senhor teu Deus, que te tirou da terra do Egito, da casa da servidão;"},
{v:15,t:"que te conduziu por aquele deserto grande e terrível, de serpentes abrasadoras e escorpiões, terra seca e sem água; que te fez sair água da rocha duríssima;"},
{v:16,t:"que te sustentou no deserto com o maná, que teus pais não conheceram, para te humilhar e te provar, e para no fim te fazer bem;"},
{v:17,t:"para que não digas no teu coração: A minha força e o poder da minha mão me adquiriram esta riqueza.",n:"É o esquecimento na sua forma mais fina: não negar Deus, mas atribuir a si o que dele se recebeu. A fartura não produz ateus, produz proprietários."},
{v:18,t:"Antes, lembra-te do Senhor teu Deus, porque é ele quem te dá força para adquirires riqueza, para confirmar a aliança que jurou a teus pais, como hoje se vê."},
{v:19,t:"Se te esqueceres do Senhor teu Deus, seguires outros deuses, os servires e te prostrares diante deles, eu protesto hoje contra vós que perecereis de todo:"},
{v:20,t:"como as nações que o Senhor destrói diante de vós, assim perecereis, por não terdes obedecido à voz do Senhor vosso Deus."}
];

window.TEXTOS_SEED["deuteronomio"][9] = [
{s:"Não por tua justiça"},
{v:1,t:"Ouve, Israel: hoje passarás o Jordão para desapossar nações maiores e mais fortes do que tu, cidades grandes e fortificadas até ao céu,"},
{v:2,t:"um povo grande e alto, os filhos de Enac, que tu conheces e de que ouviste dizer: Quem poderá resistir aos filhos de Enac?"},
{v:3,t:"Sabe, pois, hoje que o Senhor teu Deus é quem passa adiante de ti como fogo devorador: ele os destruirá e os humilhará diante de ti, e tu os expulsarás e os farás perecer depressa, como o Senhor te disse."},
{v:4,t:"Quando o Senhor teu Deus os houver lançado fora de diante de ti, não digas no teu coração: Foi por causa da minha justiça que o Senhor me introduziu para possuir esta terra. É pela impiedade destas nações que o Senhor as expulsa de diante de ti."},
{v:5,t:"Não é pela tua justiça nem pela retidão do teu coração que entras a possuir a terra delas, mas pela impiedade destas nações o Senhor teu Deus as expulsa de diante de ti, e para cumprir a palavra que o Senhor jurou a teus pais, Abraão, Isaac e Jacó.",n:"Duas razões, e nenhuma delas é o mérito de Israel: a maldade dos que saem e a promessa feita aos pais. O livro corta pela raiz a conclusão que o vencedor sempre tira da vitória."},
{v:6,t:"Sabe, pois, que não é pela tua justiça que o Senhor teu Deus te dá esta boa terra em possessão, porque és um povo de dura cerviz."},
{s:"O bezerro de metal fundido"},
{v:7,t:"Lembra-te, e não te esqueças, de como provocaste à ira o Senhor teu Deus no deserto: desde o dia em que saíste da terra do Egito até chegardes a este lugar, fostes rebeldes contra o Senhor."},
{v:8,t:"Já no Horeb provocastes o Senhor, e ele se irou contra vós a ponto de vos querer destruir,"},
{v:9,t:"quando subi ao monte para receber as tábuas de pedra, as tábuas da aliança que o Senhor fez convosco, e fiquei no monte quarenta dias e quarenta noites, sem comer pão nem beber água."},
{v:10,t:"O Senhor me deu as duas tábuas de pedra, escritas pelo dedo de Deus, com todas as palavras que ele vos falara no monte, do meio do fogo, no dia da assembleia.",n:"Dedo de Deus: a mesma expressão com que os magos do Egito reconhecem a praga que não sabem imitar, e a que o Senhor Jesus usa ao expulsar demônios, segundo São Lucas."},
{v:11,t:"Ao cabo dos quarenta dias e das quarenta noites, o Senhor me deu as duas tábuas de pedra, as tábuas da aliança,"},
{v:12,t:"e me disse: Levanta-te e desce depressa daqui, porque o teu povo, que tiraste do Egito, se corrompeu; depressa se desviaram do caminho que eu lhes ordenei e fizeram para si um ídolo de metal fundido.",n:"O teu povo, que tiraste do Egito. No momento do pecado a paternidade é devolvida a Moisés; ele havia de devolvê-la ao Senhor no verso 26, chamando-lhes o teu povo e a tua herança."},
{v:13,t:"E o Senhor me disse ainda: Vejo que este povo é de dura cerviz."},
{v:14,t:"Deixa-me, para que eu os destrua e apague o seu nome de debaixo do céu, e farei de ti uma nação mais forte e mais numerosa do que esta.",n:"Deixa-me: como se a oração de Moisés fosse capaz de segurar a mão de Deus. A própria ameaça é já um convite a interceder, e Moisés o entende assim."},
{v:15,t:"Voltei-me e desci do monte, que ardia em fogo, com as duas tábuas da aliança nas minhas duas mãos."},
{v:16,t:"Olhei, e eis que havíeis pecado contra o Senhor vosso Deus: tínheis feito para vós um bezerro de metal fundido; depressa vos desviastes do caminho que o Senhor vos ordenara."},
{v:17,t:"Peguei então nas duas tábuas, lancei-as das minhas mãos e as quebrei diante dos vossos olhos."},
{v:18,t:"E prostrei-me diante do Senhor, como da primeira vez, quarenta dias e quarenta noites, sem comer pão nem beber água, por causa de todo o vosso pecado, que cometestes fazendo o mal aos olhos do Senhor, para o provocar à ira;"},
{v:19,t:"porque temi a indignação e o furor com que o Senhor se irara contra vós, a ponto de vos querer destruir. E ainda desta vez o Senhor me ouviu."},
{v:20,t:"Também contra Aarão se irou grandemente o Senhor, a ponto de o querer destruir; e naquele tempo orei também por Aarão."},
{v:21,t:"E o vosso pecado, o bezerro que tínheis feito, eu o tomei e o queimei no fogo, o triturei e o moí bem, até ficar reduzido a pó, e lancei o pó na torrente que desce do monte."},
{s:"As outras rebeliões"},
{v:22,t:"Também em Tabera, em Massá e em Quibrot-Hataavá provocastes o Senhor à ira;"},
{v:23,t:"e quando o Senhor vos enviou de Cades-Barne, dizendo: Subi e possuí a terra que vos dei, fostes rebeldes à ordem do Senhor vosso Deus: não crestes nele nem quisestes ouvir a sua voz."},
{v:24,t:"Fostes rebeldes contra o Senhor desde o dia em que vos conheci."},
{s:"A intercessão de Moisés"},
{v:25,t:"Prostrei-me, pois, diante do Senhor aqueles quarenta dias e quarenta noites, porque o Senhor dissera que vos havia de destruir."},
{v:26,t:"E orei ao Senhor, dizendo: Senhor Deus, não destruas o teu povo e a tua herança, que resgataste com a tua grandeza e que tiraste do Egito com mão forte."},
{v:27,t:"Lembra-te de teus servos Abraão, Isaac e Jacó; não olhes para a dureza deste povo, nem para a sua impiedade, nem para o seu pecado,"},
{v:28,t:"a fim de que os habitantes da terra donde nos tiraste não digam: Porque o Senhor não podia introduzi-los na terra que lhes prometera, e porque os odiava, por isso os tirou, para os matar no deserto.",n:"O argumento decisivo da oração não é a inocência do povo, que não há, nem a piedade de Deus, que se não invoca: é a honra do nome de Deus diante das nações. Moisés já tinha usado o mesmo em Números, e Ezequiel havia de o repetir."},
{v:29,t:"Eles, porém, são o teu povo e a tua herança, que tiraste com a tua grande força e com o teu braço estendido."}
];

window.TEXTOS_SEED["deuteronomio"][10] = [
{s:"As segundas tábuas"},
{v:1,t:"Naquele tempo o Senhor me disse: Talha duas tábuas de pedra como as primeiras e sobe a mim ao monte; faze também uma arca de madeira."},
{v:2,t:"Eu escreverei nas tábuas as palavras que estavam nas primeiras, que quebraste, e as porás na arca."},
{v:3,t:"Fiz, pois, uma arca de madeira de acácia, talhei duas tábuas de pedra como as primeiras e subi ao monte com as duas tábuas na mão."},
{v:4,t:"E o Senhor escreveu nas tábuas o que escrevera da primeira vez, as dez palavras que vos falara no monte, do meio do fogo, no dia da assembleia; e o Senhor mas deu."},
{v:5,t:"Voltei-me, desci do monte e pus as tábuas na arca que eu fizera; e ali estão, como o Senhor me ordenou."},
{s:"A morte de Aarão; a tribo de Levi"},
{v:6,t:"Os filhos de Israel partiram de Beerot-Bene-Jaacan para Moserá, onde Aarão morreu e foi sepultado; e Eleazar, seu filho, exerceu o sacerdócio em seu lugar."},
{v:7,t:"Dali partiram para Gudgoda; de Gudgoda, para Jotbatá, terra de torrentes de águas."},
{v:8,t:"Naquele tempo o Senhor separou a tribo de Levi para levar a arca da aliança do Senhor, para estar diante do Senhor, servindo-o, e para abençoar em seu nome, como até hoje faz."},
{v:9,t:"Por isso Levi não teve parte nem herança com seus irmãos: o Senhor é a sua herança, como o Senhor teu Deus lhe prometeu.",n:"O sacerdote não recebe terra. Em um livro inteiramente voltado para a posse da terra, a tribo do altar fica de fora do sorteio, e isso mesmo é chamado a sua herança."},
{v:10,t:"Eu fiquei no monte, como da primeira vez, quarenta dias e quarenta noites; e ainda desta vez o Senhor me ouviu, e não te quis destruir."},
{v:11,t:"O Senhor me disse: Levanta-te, põe-te a caminho à frente do povo, para que entrem e possuam a terra que jurei a seus pais dar-lhes."},
{s:"O que o Senhor pede de ti"},
{v:12,t:"Agora, Israel, que pede de ti o Senhor teu Deus, senão que temas o Senhor teu Deus, que andes em todos os seus caminhos, que o ames e sirvas ao Senhor teu Deus de todo o teu coração e de toda a tua alma,",n:"Miqueias havia de fazer a mesma pergunta e dar resposta parecida: que pratiques a justiça, ames a misericórdia e andes humildemente com o teu Deus. O culto nunca é a resposta; a resposta é o modo de viver."},
{v:13,t:"e que guardes os mandamentos do Senhor e os seus estatutos, que hoje te ordeno para o teu bem?"},
{v:14,t:"Eis que do Senhor teu Deus são o céu e o céu dos céus, a terra e tudo o que nela há;"},
{v:15,t:"contudo o Senhor se afeiçoou a teus pais, e os amou, e escolheu a descendência deles depois deles, isto é, vós, dentre todos os povos, como hoje se vê."},
{v:16,t:"Circuncidai, pois, o prepúcio do vosso coração, e não endureçais mais a vossa cerviz;",n:"O sinal da carne é declarado insuficiente pelo próprio livro que o supõe. Jeremias e São Paulo haviam de seguir esta linha; e no capítulo 30 será o próprio Senhor quem circuncidará o coração."},
{v:17,t:"porque o Senhor vosso Deus é o Deus dos deuses e o Senhor dos senhores, Deus grande, poderoso e terrível, que não faz acepção de pessoas nem aceita subornos;"},
{v:18,t:"que faz justiça ao órfão e à viúva, e ama o estrangeiro, dando-lhe pão e vestido.",n:"Os três protegidos da lei — o órfão, a viúva e o estrangeiro — são os que não têm quem os reclame. A grandeza de Deus, acabada de proclamar nos termos mais altos, prova-se justamente aí."},
{v:19,t:"Amai, pois, o estrangeiro, porque também vós fostes estrangeiros na terra do Egito."},
{v:20,t:"Ao Senhor teu Deus temerás, a ele servirás, a ele te apegarás e pelo seu nome jurarás."},
{v:21,t:"Ele é o teu louvor e o teu Deus, que fez por ti estas coisas grandes e terríveis que os teus olhos viram."},
{v:22,t:"Em número de setenta pessoas desceram teus pais ao Egito, e agora o Senhor teu Deus te fez numeroso como as estrelas do céu."}
];

window.TEXTOS_SEED["deuteronomio"][11] = [
{s:"O que os vossos olhos viram"},
{v:1,t:"Amarás, pois, o Senhor teu Deus e guardarás sempre a sua observância, os seus estatutos, as suas normas de direito e os seus mandamentos."},
{v:2,t:"Reconhecei hoje — porque não falo a vossos filhos, que não conheceram nem viram a correção do Senhor vosso Deus — a sua grandeza, a sua mão forte e o seu braço estendido,"},
{v:3,t:"os seus sinais e as suas obras, que fez no meio do Egito, ao faraó, rei do Egito, e a toda a sua terra;"},
{v:4,t:"o que fez ao exército do Egito, aos seus cavalos e aos seus carros, quando as águas do mar Vermelho os cobriram enquanto vos perseguiam, e o Senhor os destruiu para sempre;"},
{v:5,t:"o que fez por vós no deserto, até chegardes a este lugar;"},
{v:6,t:"e o que fez a Datan e a Abiron, filhos de Eliab, filho de Rúben, quando a terra abriu a boca e os tragou, com as suas casas, as suas tendas e tudo o que lhes pertencia, no meio de todo o Israel."},
{v:7,t:"Os vossos olhos viram todas as grandes obras que o Senhor fez."},
{s:"A terra que bebe a chuva do céu"},
{v:8,t:"Guardai, pois, todos os mandamentos que hoje vos ordeno, para que sejais fortes e entreis a possuir a terra a que passais para a possuir,"},
{v:9,t:"e para que vivais muito tempo na terra que o Senhor jurou dar a vossos pais e à sua descendência, terra que mana leite e mel."},
{v:10,t:"Porque a terra em que vais entrar para a possuir não é como a terra do Egito, donde saístes, em que semeavas a tua semente e a regavas com o pé, como se rega uma horta;",n:"Regar com o pé é acionar com os pés as rodas e comportas que tiravam a água do Nilo. O Egito é a terra onde a água se domina; a de Canaã é a terra onde a água se espera."},
{v:11,t:"mas a terra a que passais para a possuir é terra de montes e de vales, que bebe a chuva do céu;"},
{v:12,t:"terra de que o Senhor teu Deus cuida, e sobre a qual estão continuamente os olhos do Senhor teu Deus, desde o princípio até ao fim do ano."},
{v:13,t:"Se obedecerdes fielmente aos mandamentos que hoje vos ordeno, amando o Senhor vosso Deus e servindo-o de todo o vosso coração e de toda a vossa alma,"},
{v:14,t:"darei à vossa terra a chuva no seu tempo, a temporã e a serôdia, para que recolhas o teu trigo, o teu vinho e o teu azeite;"},
{v:15,t:"e darei erva no teu campo para o teu gado; e comerás e te fartarás."},
{v:16,t:"Guardai-vos de que o vosso coração se deixe seduzir, e vos desvieis, e sirvais a outros deuses e vos prostreis diante deles;"},
{v:17,t:"porque então se acenderia contra vós a ira do Senhor, e ele fecharia o céu, e não haveria chuva, e a terra não daria o seu fruto; e depressa perecereis na boa terra que o Senhor vos dá.",n:"Elias havia de fechar o céu por três anos e meio diante de Acab, em nome deste verso; a seca não é acidente do clima, é linguagem."},
{s:"Ponde estas palavras no coração"},
{v:18,t:"Ponde, pois, estas minhas palavras no vosso coração e na vossa alma; atai-as como sinal na vossa mão, e serão como faixa entre os vossos olhos."},
{v:19,t:"Ensinai-as a vossos filhos, falando delas sentado em tua casa e andando pelo caminho, ao deitar-te e ao levantar-te."},
{v:20,t:"Escreve-as nos umbrais da tua casa e nas tuas portas,"},
{v:21,t:"para que se multipliquem os teus dias e os dias de teus filhos na terra que o Senhor jurou dar a teus pais, tanto quanto durarem os céus sobre a terra."},
{v:22,t:"Porque, se guardardes cuidadosamente todos estes mandamentos que vos ordeno, e os cumprirdes, amando o Senhor vosso Deus, andando em todos os seus caminhos e apegando-vos a ele,"},
{v:23,t:"o Senhor expulsará de diante de vós todas estas nações, e desapossareis nações maiores e mais fortes do que vós."},
{v:24,t:"Todo lugar que a planta do vosso pé pisar será vosso: desde o deserto e o Líbano, desde o rio, o rio Eufrates, até ao mar ocidental serão os vossos limites.",n:"Josué havia de ouvir a mesma promessa ao pôr o pé na terra. A medida dada é a maior de toda a Escritura, e nunca coincidiu com o território efetivamente ocupado."},
{v:25,t:"Ninguém vos poderá resistir: o Senhor vosso Deus porá o terror e o medo de vós sobre toda a terra que pisardes, como vos disse."},
{s:"A bênção e a maldição"},
{v:26,t:"Eis que hoje ponho diante de vós a bênção e a maldição:"},
{v:27,t:"a bênção, se obedecerdes aos mandamentos do Senhor vosso Deus, que hoje vos ordeno;"},
{v:28,t:"e a maldição, se não obedecerdes aos mandamentos do Senhor vosso Deus, mas vos desviardes do caminho que hoje vos ordeno, para seguirdes outros deuses, que não conheceis."},
{v:29,t:"Quando o Senhor teu Deus te introduzir na terra a que vais para a possuir, porás a bênção sobre o monte Garizim e a maldição sobre o monte Ebal.",n:"Os dois montes ficam frente a frente, com Siquém no vale entre eles; quem ali estivesse tinha, à direita e à esquerda, as duas possibilidades da sua vida postas em pedra. O capítulo 27 e o livro de Josué narram a cerimônia."},
{v:30,t:"Esses montes estão do outro lado do Jordão, a ocidente, na terra dos cananeus que habitam na Arabá, defronte de Gálgala, junto aos carvalhos de Moré."},
{v:31,t:"Porque vós ides passar o Jordão para entrardes a possuir a terra que o Senhor vosso Deus vos dá, e a possuireis e nela habitareis."},
{v:32,t:"Cuidai, pois, de cumprir todos os estatutos e as normas de direito que hoje ponho diante de vós."}
];

window.TEXTOS_SEED["deuteronomio"][12] = [
{s:"O lugar único do culto"},
{v:1,t:"Estes são os estatutos e as normas de direito que cuidareis de cumprir na terra que o Senhor, Deus de teus pais, te dá para a possuíres todos os dias que viverdes sobre o solo."},
{v:2,t:"Destruireis inteiramente todos os lugares em que as nações que ides desapossar serviram aos seus deuses, sobre os montes altos, sobre as colinas e debaixo de toda árvore frondosa."},
{v:3,t:"Derrubareis os seus altares, quebrareis as suas estelas, queimareis no fogo os seus postes sagrados, despedaçareis as imagens esculpidas dos seus deuses e apagareis o nome deles daquele lugar."},
{v:4,t:"Não fareis assim com o Senhor vosso Deus;"},
{v:5,t:"mas buscareis o lugar que o Senhor vosso Deus escolher dentre todas as vossas tribos, para ali pôr o seu nome e nele habitar; e para lá ireis.",n:"O lugar não é nomeado nenhuma vez em todo o livro, e a fórmula volta mais de vinte vezes. A reforma de Josias havia de identificá-lo com Jerusalém; os samaritanos leem, no lugar correspondente, o monte Garizim. O texto, deixando o nome em branco, torna o culto dependente da escolha de Deus, e não da conveniência de quem oferece."},
{v:6,t:"Ali levareis os vossos holocaustos e os vossos sacrifícios, os vossos dízimos e as ofertas das vossas mãos, os vossos votos e as vossas ofertas espontâneas, e os primogênitos das vossas vacas e das vossas ovelhas."},
{v:7,t:"Ali comereis diante do Senhor vosso Deus e vos alegrareis, vós e as vossas casas, de tudo o que fizerdes com as vossas mãos, em que o Senhor vosso Deus vos houver abençoado."},
{v:8,t:"Não fareis como fazemos aqui hoje, cada um o que lhe parece reto aos seus olhos,",n:"Frase que o livro dos Juízes há de repetir como epitáfio daquele tempo: não havia rei em Israel, e cada um fazia o que lhe parecia reto aos seus olhos."},
{v:9,t:"porque até agora não chegastes ao descanso e à herança que o Senhor teu Deus te dá."},
{v:10,t:"Mas passareis o Jordão e habitareis na terra que o Senhor vosso Deus vos dá em herança; ele vos dará descanso de todos os vossos inimigos ao redor, e habitareis seguros."},
{v:11,t:"Então, ao lugar que o Senhor vosso Deus escolher para fazer habitar ali o seu nome, levareis tudo o que vos ordeno: os vossos holocaustos e os vossos sacrifícios, os vossos dízimos e as ofertas das vossas mãos, e tudo o que houver de melhor entre os votos que fizerdes ao Senhor."},
{v:12,t:"E vos alegrareis diante do Senhor vosso Deus, vós, vossos filhos e vossas filhas, os vossos servos e as vossas servas, e o levita que mora dentro das vossas portas, porque não tem parte nem herança convosco.",n:"A alegria é mandada. Nenhum outro livro da Lei insiste tanto em que o culto termine em festa, nem em que dela participem os que não têm terra."},
{s:"O sangue e a carne"},
{v:13,t:"Guarda-te de oferecer os teus holocaustos em qualquer lugar que vires;"},
{v:14,t:"mas no lugar que o Senhor escolher numa das tuas tribos, ali oferecerás os teus holocaustos, e ali farás tudo o que te ordeno."},
{v:15,t:"Contudo, sempre que o desejares, poderás matar e comer carne dentro de todas as tuas portas, segundo a bênção que o Senhor teu Deus te houver dado; o impuro e o puro dela comerão, como se come a gazela e o veado.",n:"Consequência do culto num só lugar: se todo animal abatido tivesse de ser levado ao santuário, ninguém comeria carne longe dele. A lei então separa o abate comum do sacrifício, coisa que o Levítico não fazia."},
{v:16,t:"Somente não comereis o sangue; sobre a terra o derramarás como água."},
{v:17,t:"Não poderás comer dentro das tuas portas o dízimo do teu trigo, do teu vinho e do teu azeite, nem os primogênitos das tuas vacas e das tuas ovelhas, nem nenhum dos votos que fizeres, nem as tuas ofertas espontâneas, nem as ofertas das tuas mãos;"},
{v:18,t:"mas os comerás diante do Senhor teu Deus, no lugar que o Senhor teu Deus escolher, tu, teu filho e tua filha, o teu servo e a tua serva, e o levita que mora dentro das tuas portas; e te alegrarás diante do Senhor teu Deus de tudo o que fizeres com as tuas mãos."},
{v:19,t:"Guarda-te de desamparar o levita, todos os dias que viveres na tua terra."},
{v:20,t:"Quando o Senhor teu Deus dilatar o teu território, como te prometeu, e disseres: Quero comer carne, porque a tua alma deseja comer carne, então comerás carne quanto a tua alma desejar."},
{v:21,t:"Se estiver longe de ti o lugar que o Senhor teu Deus escolher para ali pôr o seu nome, matarás das tuas vacas e das tuas ovelhas que o Senhor te deu, como te ordenei, e comerás dentro das tuas portas quanto a tua alma desejar."},
{v:22,t:"Como se come a gazela e o veado, assim as comerás; o impuro e o puro juntamente as comerão."},
{v:23,t:"Somente guarda-te de comer o sangue, porque o sangue é a vida, e não comerás a vida com a carne.",n:"A proibição do sangue atravessa toda a Escritura, do pacto com Noé ao concílio de Jerusalém. A razão dada é sempre a mesma: o sangue não pertence a quem mata, porque a vida não é dele."},
{v:24,t:"Não o comerás; sobre a terra o derramarás como água."},
{v:25,t:"Não o comerás, para que te vá bem, a ti e a teus filhos depois de ti, fazendo o que é reto aos olhos do Senhor."},
{v:26,t:"Somente as coisas santas que tiveres e os teus votos, tu os tomarás e irás ao lugar que o Senhor escolher;"},
{v:27,t:"e oferecerás os teus holocaustos, a carne e o sangue, sobre o altar do Senhor teu Deus; o sangue dos teus sacrifícios será derramado sobre o altar do Senhor teu Deus, e a carne tu a comerás."},
{v:28,t:"Guarda e ouve todas estas palavras que te ordeno, para que te vá bem, a ti e a teus filhos depois de ti, para sempre, fazendo o que é bom e reto aos olhos do Senhor teu Deus."},
{s:"Não imitar as nações"},
{v:29,t:"Quando o Senhor teu Deus houver exterminado de diante de ti as nações que vais desapossar, e as tiveres desapossado e habitares na terra delas,"},
{v:30,t:"guarda-te de te deixares enlaçar, seguindo-as depois de destruídas diante de ti, e de perguntares pelos seus deuses, dizendo: Como serviam estas nações aos seus deuses? Assim farei eu também."},
{v:31,t:"Não farás assim com o Senhor teu Deus, porque tudo o que é abominação ao Senhor, e ele odeia, elas fizeram aos seus deuses: até os seus filhos e as suas filhas queimavam no fogo aos seus deuses.",n:"O sacrifício de crianças está documentado no mundo púnico e cananeu, e a Escritura volta a ele com horror sempre que fala de Moloc. É o argumento último contra a imitação: quem copia o culto acaba por copiar o preço."}
];

window.TEXTOS_SEED["deuteronomio"][13] = [
{s:"Nada acrescentar nem tirar"},
{v:1,t:"Tudo o que vos ordeno, isso cuidareis de cumprir; nada lhe acrescentarás nem dele tirarás.",n:"Segunda vez que a fórmula aparece, depois de 4, 2; ela fecha aqui a lei do santuário e abre a dos sedutores. O que se proíbe acrescentar não são doutrinas, mas deuses."},
{s:"O profeta que seduz"},
{v:2,t:"Se se levantar no meio de ti um profeta ou um sonhador de sonhos, e te der um sinal ou um prodígio,"},
{v:3,t:"e suceder o sinal ou o prodígio de que te falou, e ele disser: Vamos após outros deuses, que não conheces, e sirvamo-los,"},
{v:4,t:"não ouvirás as palavras daquele profeta ou sonhador de sonhos, porque o Senhor vosso Deus vos está provando, para saber se amais o Senhor vosso Deus de todo o vosso coração e de toda a vossa alma.",n:"O caso é o mais duro que a lei propõe: o milagre acontece de fato, e ainda assim a doutrina é falsa. O sinal não autentica a mensagem; é a mensagem que se julga pelo primeiro mandamento. São Paulo dirá o mesmo, mesmo de um anjo do céu."},
{v:5,t:"Seguireis o Senhor vosso Deus, a ele temereis, os seus mandamentos guardareis, a sua voz ouvireis, a ele servireis e a ele vos apegareis."},
{v:6,t:"Aquele profeta ou sonhador de sonhos será morto, porque pregou rebeldia contra o Senhor vosso Deus, que vos tirou da terra do Egito e te resgatou da casa da servidão, para te apartar do caminho que o Senhor teu Deus te mandou seguir. Assim eliminarás o mal do meio de ti.",n:"A fórmula eliminarás o mal do meio de ti fecha sete leis capitais neste livro. São Paulo a cita aos coríntios, mas aplicando-a à exclusão da comunidade, não à morte."},
{s:"O parente que seduz em segredo"},
{v:7,t:"Se teu irmão, filho de tua mãe, ou teu filho, ou tua filha, ou a mulher do teu regaço, ou o amigo que é como a tua alma, te induzir em segredo, dizendo: Vamos e sirvamos a outros deuses, que nem tu nem teus pais conhecestes,",n:"A lista sobe do irmão ao amigo passando pela mulher, e todos são nomeados pela intimidade: o perigo não vem de fora, vem de quem tem acesso ao coração."},
{v:8,t:"dentre os deuses dos povos que vos rodeiam, perto ou longe de ti, de um extremo ao outro da terra,"},
{v:9,t:"não consentirás com ele nem o ouvirás; o teu olho não terá piedade dele, não o pouparás nem o encobrirás;"},
{v:10,t:"mas o matarás. A tua mão será a primeira contra ele, para o matar, e depois a mão de todo o povo.",n:"A regra reaparece em 17, 7 e serve de fundo ao episódio da mulher adúltera: quem acusa deve ser o primeiro a arriscar a mão, e por isso o primeiro a examinar-se."},
{v:11,t:"Tu o apedrejarás até morrer, porque procurou apartar-te do Senhor teu Deus, que te tirou da terra do Egito, da casa da servidão."},
{v:12,t:"Todo o Israel o ouvirá e temerá, e nunca mais se fará semelhante maldade no meio de ti."},
{s:"A cidade apóstata"},
{v:13,t:"Se ouvires dizer de uma das tuas cidades que o Senhor teu Deus te dá para nelas habitares,"},
{v:14,t:"que saíram do meio de ti homens perversos e seduziram os habitantes da sua cidade, dizendo: Vamos e sirvamos a outros deuses, que não conheceis,",n:"Homens perversos traduz filhos de Belial, expressão que significa sem proveito, sem valor; o nome acabou por tornar-se, no judaísmo tardio e no Novo Testamento, um dos nomes do adversário."},
{v:15,t:"então investigarás, indagarás e inquirirás com cuidado; e se for verdade e certo que tal abominação se cometeu no meio de ti,"},
{v:16,t:"passarás ao fio da espada os habitantes daquela cidade, votando-a ao anátema, com tudo o que nela houver, e também o seu gado."},
{v:17,t:"Ajuntarás todo o seu despojo no meio da praça e queimarás a fogo a cidade e todo o seu despojo, como oferta total ao Senhor teu Deus; e ela ficará sendo para sempre um monte de ruínas, e nunca mais será reedificada."},
{v:18,t:"Nada do que foi votado ao anátema se pegará à tua mão, para que o Senhor se aparte do furor da sua ira e use contigo de misericórdia, tenha compaixão de ti e te multiplique, como jurou a teus pais,"},
{v:19,t:"quando ouvires a voz do Senhor teu Deus, guardando todos os seus mandamentos que hoje te ordeno, e fazendo o que é reto aos olhos do Senhor teu Deus.",n:"Não há notícia de que esta lei tenha sido aplicada alguma vez. Os rabinos discutiram-na como caso de escola, e a maioria concluiu que as condições exigidas nunca se poderiam verificar todas: foi escrita, diziam, para ser estudada, não executada."}
];

window.TEXTOS_SEED["deuteronomio"][14] = [
{s:"Filhos do Senhor"},
{v:1,t:"Sois filhos do Senhor vosso Deus: não vos fareis incisões nem rapareis a cabeça entre os olhos por causa de um morto,",n:"A Lei chama o povo, em bloco, filhos do Senhor; e tira daí uma consequência sobre o luto. Os ritos de sangue e de tosquia pertenciam ao culto dos mortos; quem tem Deus por pai não trata a morte como dona da casa."},
{v:2,t:"porque tu és um povo santo para o Senhor teu Deus, e o Senhor te escolheu para seres o seu povo, a sua propriedade particular, dentre todos os povos que há sobre a face da terra."},
{s:"Os animais puros e impuros"},
{v:3,t:"Não comerás coisa alguma abominável."},
{v:4,t:"Estes são os animais que podereis comer: o boi, a ovelha e a cabra,"},
{v:5,t:"o veado, a gazela, o gamo, a cabra montesa, o antílope, o boi selvagem e a ovelha montesa.",n:"Esta lista de animais silvestres não tem paralelo no Levítico, e a identificação de vários deles é conjetural. O que importa à lei é o critério do verso seguinte, não o rol dos nomes."},
{v:6,t:"Todo animal que tem o casco fendido, dividido em duas unhas, e que rumina, esse comereis."},
{v:7,t:"Mas, dentre os que ruminam ou têm o casco fendido, não comereis estes: o camelo, a lebre e o damão, porque ruminam mas não têm o casco fendido: serão impuros para vós;"},
{v:8,t:"nem o porco, porque tem o casco fendido mas não rumina: será impuro para vós. Da sua carne não comereis, nem tocareis os seus cadáveres."},
{v:9,t:"Dentre tudo o que há nas águas, podereis comer isto: tudo o que tem barbatanas e escamas comereis;"},
{v:10,t:"mas tudo o que não tem barbatanas e escamas não comereis: será impuro para vós."},
{v:11,t:"Toda ave pura comereis;"},
{v:12,t:"mas estas não comereis: a águia, o quebrantosso e a águia-marinha,"},
{v:13,t:"o açor, o falcão e o milhafre, segundo a sua espécie,"},
{v:14,t:"todo corvo, segundo a sua espécie,"},
{v:15,t:"o avestruz, a coruja, a gaivota e o gavião, segundo a sua espécie,"},
{v:16,t:"o mocho, a íbis e a coruja-branca,"},
{v:17,t:"o pelicano, o abutre e o corvo-marinho,"},
{v:18,t:"a cegonha e a garça, segundo a sua espécie, a poupa e o morcego."},
{v:19,t:"Todo inseto alado será impuro para vós: não se comerá."},
{v:20,t:"Toda ave pura comereis."},
{v:21,t:"Não comereis animal algum que tenha morrido por si; darás ao estrangeiro que está dentro das tuas portas, para que o coma, ou vende-o a um estranho, porque tu és um povo santo para o Senhor teu Deus. Não cozerás o cabrito no leite de sua mãe.",n:"A proibição do cabrito no leite da mãe aparece três vezes na Lei, e nunca com razão declarada. Da tripla repetição tirou a tradição judaica a separação completa entre carne e leite, que é o que hoje se chama comida casher."},
{s:"O dízimo"},
{v:22,t:"Dizimarás fielmente todo o produto da tua semente, o que o campo render cada ano;"},
{v:23,t:"e comerás diante do Senhor teu Deus, no lugar que ele escolher para ali fazer habitar o seu nome, o dízimo do teu trigo, do teu vinho e do teu azeite, e os primogênitos das tuas vacas e das tuas ovelhas, para que aprendas a temer o Senhor teu Deus todos os dias."},
{v:24,t:"Se o caminho for longo demais para ti, de modo que não possas levar o dízimo, por estar longe de ti o lugar que o Senhor teu Deus escolher para ali pôr o seu nome, quando o Senhor teu Deus te houver abençoado,"},
{v:25,t:"então o trocarás por dinheiro, e, tomando o dinheiro na mão, irás ao lugar que o Senhor teu Deus escolher;"},
{v:26,t:"e com esse dinheiro comprarás tudo o que a tua alma desejar: vacas, ovelhas, vinho e bebida fermentada, tudo o que a tua alma te pedir; e ali comerás diante do Senhor teu Deus e te alegrarás, tu e a tua casa.",n:"O dízimo não se entrega a ninguém: gasta-se numa festa, e a lei autoriza expressamente que se compre com ele o que se quiser beber. A parte de Deus consiste em que se coma diante dele."},
{v:27,t:"E não desampararás o levita que está dentro das tuas portas, porque não tem parte nem herança contigo."},
{v:28,t:"Ao fim de cada três anos separarás todo o dízimo do teu produto daquele ano e o depositarás dentro das tuas portas;"},
{v:29,t:"e virá o levita, que não tem parte nem herança contigo, e o estrangeiro, o órfão e a viúva, que estão dentro das tuas portas, e comerão e se fartarão, para que o Senhor teu Deus te abençoe em toda obra que as tuas mãos fizerem.",n:"De três em três anos o dízimo não sobe ao santuário: fica na cidade e vira comida dos que não têm terra. É a forma mais simples que a lei encontrou de impedir que o culto se pagasse com o que devia sustentar o pobre."}
];

window.TEXTOS_SEED["deuteronomio"][15] = [
{s:"O ano da remissão"},
{v:1,t:"Ao fim de cada sete anos farás remissão.",n:"A palavra hebraica significa deixar cair: o credor abre a mão e deixa cair a dívida. O Levítico dava o sétimo ano à terra, que descansava; aqui o mesmo ano é dado ao devedor."},
{v:2,t:"Esta é a forma da remissão: todo credor que houver emprestado ao seu próximo deixará cair a dívida; não a cobrará do seu próximo ou do seu irmão, porque se proclamou a remissão do Senhor."},
{v:3,t:"Do estrangeiro poderás cobrar; mas o que teu irmão tiver do teu, a tua mão o deixará."},
{v:4,t:"Para que não haja pobre entre ti; porque o Senhor te abençoará abundantemente na terra que o Senhor teu Deus te dá em herança para a possuíres,"},
{v:5,t:"contanto que ouças diligentemente a voz do Senhor teu Deus e cuides de cumprir todos estes mandamentos que hoje te ordeno."},
{v:6,t:"Quando o Senhor teu Deus te abençoar, como te prometeu, emprestarás a muitas nações, mas tu não tomarás emprestado; dominarás muitas nações, mas elas não te dominarão."},
{s:"O irmão pobre"},
{v:7,t:"Se houver no meio de ti algum pobre dentre teus irmãos, em alguma das tuas cidades, na terra que o Senhor teu Deus te dá, não endurecerás o teu coração nem fecharás a mão ao teu irmão pobre;"},
{v:8,t:"antes lhe abrirás de todo a tua mão e lhe emprestarás o que lhe faltar, quanto baste para a sua necessidade."},
{v:9,t:"Guarda-te de que não haja no teu coração pensamento vil, e digas: Está perto o sétimo ano, o ano da remissão; e olhes com maus olhos para o teu irmão pobre e nada lhe dês; ele clamará contra ti ao Senhor, e isso será pecado em ti.",n:"A lei antecipa o cálculo de quem não quer emprestar às vésperas do perdão, e chama-lhe pelo nome: pensamento vil. Não basta a letra da remissão se o coração se fecha antes dela."},
{v:10,t:"De boa vontade lhe darás, e o teu coração não se entristecerá quando lhe deres, pois por isso o Senhor teu Deus te abençoará em toda a tua obra e em tudo o que empreenderes."},
{v:11,t:"Nunca deixará de haver pobres na terra; por isso te ordeno: Abrirás de todo a tua mão ao teu irmão, ao necessitado e ao pobre da tua terra.",n:"O verso 4 dizia que não haveria pobre; este diz que sempre haverá. Não é contradição, é a distância entre a promessa e o que se cumpre: por isso o mandamento. O Senhor Jesus cita a segunda metade, em Betânia, a quem se queixava do perfume derramado."},
{s:"O escravo hebreu"},
{v:12,t:"Se teu irmão hebreu, homem ou mulher, se vender a ti e te servir seis anos, no sétimo ano o deixarás ir livre."},
{v:13,t:"E, quando o deixares ir livre, não o mandarás embora de mãos vazias:"},
{v:14,t:"tu o abastecerás generosamente do teu rebanho, da tua eira e do teu lagar; do que o Senhor teu Deus te houver abençoado lhe darás.",n:"O Êxodo mandava soltar o escravo no sétimo ano; o Deuteronômio acrescenta que não saia com as mãos vazias. A liberdade sem nada com que recomeçar devolveria o liberto à servidão no ano seguinte."},
{v:15,t:"Lembra-te de que foste servo na terra do Egito, e de que o Senhor teu Deus te resgatou; por isso hoje te ordeno isto."},
{v:16,t:"Mas se ele te disser: Não quero sair de tua casa, porque te ama, a ti e à tua casa, e por se achar bem contigo,"},
{v:17,t:"então tomarás uma sovela e lhe furarás a orelha contra a porta, e ele será teu servo para sempre; e do mesmo modo farás com a tua serva.",n:"A orelha é o órgão de ouvir, e por isso de obedecer; furada na porta da casa, fica presa ao lugar por escolha própria. A Escritura admite o caso, mas o narra como quem descreve uma renúncia."},
{v:18,t:"Não te pareça duro deixá-lo ir livre, pois em seis anos te rendeu o dobro do salário de um diarista; e o Senhor teu Deus te abençoará em tudo o que fizeres."},
{s:"Os primogênitos do gado"},
{v:19,t:"Consagrarás ao Senhor teu Deus todo primogênito macho que nascer das tuas vacas e das tuas ovelhas; não trabalharás com o primogênito da tua vaca, nem tosquiarás o primogênito das tuas ovelhas."},
{v:20,t:"Diante do Senhor teu Deus o comerás, ano após ano, tu e a tua casa, no lugar que o Senhor escolher."},
{v:21,t:"Mas se tiver algum defeito, se for coxo ou cego, ou tiver qualquer defeito grave, não o sacrificarás ao Senhor teu Deus;"},
{v:22,t:"dentro das tuas portas o comerás; o impuro e o puro juntamente o comerão, como se come a gazela e o veado."},
{v:23,t:"Somente não lhe comerás o sangue; sobre a terra o derramarás como água."}
];

window.TEXTOS_SEED["deuteronomio"][16] = [
{s:"A Páscoa"},
{v:1,t:"Guarda o mês de Abib e celebra a Páscoa ao Senhor teu Deus, porque no mês de Abib o Senhor teu Deus te tirou do Egito, de noite.",n:"Abib quer dizer espiga verde; é o mês da cevada nova, que depois se chamou Nisan. A festa é fixada pela lavoura e pela história ao mesmo tempo."},
{v:2,t:"Sacrificarás a Páscoa ao Senhor teu Deus, do rebanho e da manada, no lugar que o Senhor escolher para ali fazer habitar o seu nome."},
{v:3,t:"Não comerás com ela pão levedado; sete dias comerás com ela pães ázimos, pão de aflição, porque à pressa saíste da terra do Egito, para que te lembres do dia da tua saída do Egito todos os dias da tua vida.",n:"Pão de aflição: assado sem esperar que a massa cresça. A pressa é a marca da libertação, e o pão sem fermento é a pressa que se pode comer."},
{v:4,t:"Por sete dias não se verá fermento contigo, em todo o teu território; e da carne que sacrificares à tarde, no primeiro dia, nada ficará até de manhã."},
{v:5,t:"Não poderás sacrificar a Páscoa em nenhuma das cidades que o Senhor teu Deus te dá;"},
{v:6,t:"mas no lugar que o Senhor teu Deus escolher para ali fazer habitar o seu nome, ali sacrificarás a Páscoa, à tarde, ao pôr do sol, na hora em que saíste do Egito."},
{v:7,t:"Cozerás e comerás no lugar que o Senhor teu Deus escolher; e de manhã voltarás às tuas tendas."},
{v:8,t:"Seis dias comerás ázimos, e no sétimo dia haverá assembleia solene ao Senhor teu Deus: não farás nele trabalho algum."},
{s:"A festa das Semanas"},
{v:9,t:"Contarás sete semanas; desde o dia em que se começa a meter a foice na seara começarás a contar as sete semanas."},
{v:10,t:"E celebrarás a festa das Semanas ao Senhor teu Deus, com a oferta espontânea da tua mão, que darás conforme o Senhor teu Deus te houver abençoado.",n:"Cinquenta dias depois da Páscoa; daí o nome grego de Pentecostes. É a festa em que desceu o Espírito sobre os apóstolos, e a única cuja data se conta a partir de outra."},
{v:11,t:"E te alegrarás diante do Senhor teu Deus, tu, teu filho e tua filha, o teu servo e a tua serva, o levita que está dentro das tuas portas, o estrangeiro, o órfão e a viúva que estão no meio de ti, no lugar que o Senhor teu Deus escolher para ali fazer habitar o seu nome."},
{v:12,t:"Lembra-te de que foste servo no Egito, e cuida de cumprir estes estatutos."},
{s:"A festa das Tendas"},
{v:13,t:"Celebrarás por sete dias a festa das Tendas, quando tiveres recolhido da tua eira e do teu lagar."},
{v:14,t:"E te alegrarás na tua festa, tu, teu filho e tua filha, o teu servo e a tua serva, o levita, o estrangeiro, o órfão e a viúva que estão dentro das tuas portas."},
{v:15,t:"Sete dias celebrarás a festa ao Senhor teu Deus, no lugar que o Senhor escolher, porque o Senhor teu Deus te abençoará em toda a tua colheita e em toda a obra das tuas mãos; e ficarás cheio de alegria.",n:"A ordem literal é: serás somente alegre. É o mandamento mais desarmado da Lei, e cai justamente sobre a festa da colheita, quando se mora sete dias em cabanas de ramos, para não esquecer o deserto no meio da fartura."},
{v:16,t:"Três vezes no ano todo varão entre vós comparecerá diante do Senhor teu Deus, no lugar que ele escolher: na festa dos Ázimos, na festa das Semanas e na festa das Tendas; e ninguém comparecerá de mãos vazias diante do Senhor:"},
{v:17,t:"cada um dará conforme puder, segundo a bênção que o Senhor teu Deus lhe houver dado."},
{s:"Juízes e justiça"},
{v:18,t:"Constituirás juízes e oficiais em todas as tuas cidades que o Senhor teu Deus te dá, segundo as tuas tribos, e eles julgarão o povo com justo juízo."},
{v:19,t:"Não torcerás o direito; não farás acepção de pessoas nem aceitarás suborno, porque o suborno cega os olhos dos sábios e perverte as palavras dos justos."},
{v:20,t:"A justiça, e só a justiça, seguirás, para que vivas e possuas a terra que o Senhor teu Deus te dá.",n:"O hebraico repete a palavra: justiça, justiça perseguirás. Os antigos discutiram por que a duplicação, e a resposta mais conhecida é que também os meios de buscar a justiça hão de ser justos."},
{v:21,t:"Não plantarás poste sagrado de nenhuma espécie de árvore junto ao altar do Senhor teu Deus, que fizeres para ti;"},
{v:22,t:"nem levantarás estela, coisa que o Senhor teu Deus odeia."}
];

window.TEXTOS_SEED["deuteronomio"][17] = [
{s:"Vítimas sem defeito"},
{v:1,t:"Não sacrificarás ao Senhor teu Deus boi ou ovelha em que haja defeito ou qualquer coisa má, porque é abominação para o Senhor teu Deus.",n:"Malaquias havia de tomar este verso para acusar os sacerdotes do seu tempo: oferecei isso ao vosso governador, e vede se ele fica contente convosco."},
{s:"O idólatra julgado"},
{v:2,t:"Se no meio de ti, numa das tuas cidades que o Senhor teu Deus te dá, se achar homem ou mulher que faça o que é mau aos olhos do Senhor teu Deus, transgredindo a sua aliança,"},
{v:3,t:"e que vá servir a outros deuses e se prostre diante deles, diante do sol, da lua ou de todo o exército do céu, o que eu não ordenei;"},
{v:4,t:"e isso te for denunciado, e tu o ouvires, então investigarás bem; e se for verdade e certo que tal abominação se cometeu em Israel,"},
{v:5,t:"levarás às tuas portas o homem ou a mulher que tiver cometido essa maldade, e os apedrejarás até que morram."},
{v:6,t:"Por declaração de duas ou de três testemunhas será morto aquele que houver de morrer; por declaração de uma só testemunha não será morto.",n:"A regra das duas testemunhas atravessa a Escritura: o Senhor Jesus a aplica à correção fraterna, São Paulo a invoca ao anunciar a sua terceira visita a Corinto, e dela vive todo o direito processual que dali descende."},
{v:7,t:"A mão das testemunhas será a primeira contra ele, para o matar, e depois a mão de todo o povo. Assim eliminarás o mal do meio de ti."},
{s:"O tribunal supremo"},
{v:8,t:"Quando te for difícil demais julgar alguma causa entre sangue e sangue, entre demanda e demanda, entre ferida e ferida, questões de litígio nas tuas portas, então te levantarás e subirás ao lugar que o Senhor teu Deus escolher;"},
{v:9,t:"e irás aos sacerdotes levitas e ao juiz que houver naqueles dias, e os consultarás, e eles te darão a sentença."},
{v:10,t:"Farás conforme a palavra que te anunciarem no lugar que o Senhor escolher, e cuidarás de fazer tudo o que te ensinarem;"},
{v:11,t:"conforme a lei que te ensinarem e conforme o juízo que te disserem, farás; não te desviarás da palavra que te anunciarem, nem para a direita nem para a esquerda."},
{v:12,t:"O homem que, por soberba, não quiser ouvir o sacerdote que ali está para servir ao Senhor teu Deus, ou o juiz, esse homem morrerá; assim eliminarás o mal de Israel."},
{v:13,t:"E todo o povo o ouvirá e temerá, e nunca mais agirá com soberba."},
{s:"A lei do rei"},
{v:14,t:"Quando entrares na terra que o Senhor teu Deus te dá, e a possuíres e nela habitares, e disseres: Constituirei sobre mim um rei, como todas as nações que estão ao meu redor,",n:"A lei não manda ter rei: prevê que o povo o peça, e o motivo do pedido é querer ser como os outros. Samuel havia de ouvir exatamente esta frase, e de a tomar como rejeição."},
{v:15,t:"constituirás sobre ti o rei que o Senhor teu Deus escolher; dentre teus irmãos constituirás rei sobre ti; não poderás pôr sobre ti homem estranho, que não seja teu irmão."},
{v:16,t:"Somente não multiplicará para si cavalos, nem fará o povo voltar ao Egito para multiplicar cavalos, pois o Senhor vos disse: Nunca mais voltareis por esse caminho.",n:"Cavalos querem dizer carros de guerra, e o Egito era o mercado deles. Multiplicar cavalos é desfazer o êxodo pelo avesso, mandando gente de volta para pagar as armas. Salomão havia de fazer as três coisas que este trecho proíbe."},
{v:17,t:"Não multiplicará para si mulheres, para que o seu coração não se desvie; nem multiplicará para si muita prata e ouro."},
{v:18,t:"Quando se assentar no trono do seu reino, escreverá para si, num livro, uma cópia desta lei, tirada do exemplar que está com os sacerdotes levitas;",n:"Cópia desta lei: no hebraico mishné hattorá. Os Setenta verteram por deuteronômio, segunda lei, e dessa leitura veio o nome do livro inteiro. Note-se o que se manda ao rei: nem exército, nem tesouro, nem templo, mas copiar um livro à mão."},
{v:19,t:"e a terá consigo e nela lerá todos os dias da sua vida, para que aprenda a temer o Senhor seu Deus, a guardar todas as palavras desta lei e estes estatutos, e a cumpri-los;"},
{v:20,t:"para que o seu coração não se eleve acima de seus irmãos, e não se desvie do mandamento nem para a direita nem para a esquerda, a fim de que prolongue os seus dias no seu reino, ele e seus filhos, no meio de Israel.",n:"O rei é submetido à lei e chamado irmão dos seus súditos. Em todo o Oriente antigo o rei era a fonte do direito; aqui é o seu primeiro leitor, e não pode mudar uma linha."}
];

window.TEXTOS_SEED["deuteronomio"][18] = [
{s:"A parte dos sacerdotes e dos levitas"},
{v:1,t:"Os sacerdotes levitas, toda a tribo de Levi, não terão parte nem herança com Israel: comerão das ofertas queimadas ao Senhor e da sua herança."},
{v:2,t:"Não terão herança no meio de seus irmãos: o Senhor é a sua herança, como lhes prometeu."},
{v:3,t:"Este será o direito dos sacerdotes sobre o povo, sobre os que oferecerem sacrifício, boi ou ovelha: darão ao sacerdote a espádua, as queixadas e o bucho;"},
{v:4,t:"as primícias do teu trigo, do teu vinho e do teu azeite, e as primícias da tosquia das tuas ovelhas lhe darás;"},
{v:5,t:"porque o Senhor teu Deus o escolheu dentre todas as tuas tribos, para estar e servir em nome do Senhor, ele e seus filhos, para sempre."},
{v:6,t:"Quando um levita, saindo de alguma das tuas cidades de todo o Israel, onde morava, vier, com todo o desejo da sua alma, ao lugar que o Senhor escolher,"},
{v:7,t:"servirá em nome do Senhor seu Deus, como todos os seus irmãos levitas que ali estão diante do Senhor."},
{v:8,t:"Comerá porção igual à deles, além do que receber da venda do seu patrimônio."},
{s:"As abominações das nações"},
{v:9,t:"Quando entrares na terra que o Senhor teu Deus te dá, não aprenderás a fazer conforme as abominações daquelas nações."},
{v:10,t:"Não se achará entre ti quem faça passar pelo fogo o seu filho ou a sua filha, nem quem consulte presságios, nem agoureiro, nem quem faça adivinhações, nem feiticeiro,"},
{v:11,t:"nem encantador, nem quem consulte espíritos, nem mágico, nem quem interrogue os mortos.",n:"Oito nomes para outras tantas artes de arrancar o futuro ao mundo. Todas supõem que se possa obter de Deus, ou dos deuses, aquilo que ele não quis dizer; o verso 15 põe no lugar delas o profeta, que só fala quando é mandado."},
{v:12,t:"Porque todo o que faz tais coisas é abominação ao Senhor, e por causa dessas abominações o Senhor teu Deus as expulsa de diante de ti."},
{v:13,t:"Serás íntegro para com o Senhor teu Deus."},
{v:14,t:"Porque estas nações que vais desapossar ouvem os agoureiros e os adivinhos; a ti, porém, o Senhor teu Deus não permitiu tal coisa."},
{s:"O profeta como Moisés"},
{v:15,t:"O Senhor teu Deus te suscitará do meio de ti, de teus irmãos, um profeta como eu; a ele ouvireis.",n:"O verso funda a instituição profética e, lido ao singular, tornou-se promessa messiânica. São Pedro no pórtico de Salomão e Santo Estêvão diante do sinédrio o aplicam ao Senhor Jesus; era a mesma esperança que fazia perguntar a João Batista se ele era o Profeta."},
{v:16,t:"Conforme tudo o que pediste ao Senhor teu Deus no Horeb, no dia da assembleia, dizendo: Não quero mais ouvir a voz do Senhor meu Deus, nem ver mais este grande fogo, para que não morra."},
{v:17,t:"E o Senhor me disse: É bom o que disseram."},
{v:18,t:"Suscitarei do meio de seus irmãos um profeta como tu; porei as minhas palavras na sua boca, e ele lhes falará tudo o que eu lhe ordenar."},
{v:19,t:"E ao homem que não ouvir as minhas palavras, que ele falar em meu nome, eu lhe pedirei contas."},
{v:20,t:"Mas o profeta que presumir falar em meu nome palavra que eu não lhe tenha mandado falar, ou que falar em nome de outros deuses, esse profeta morrerá."},
{s:"Como reconhecer o profeta"},
{v:21,t:"E se disseres no teu coração: Como conheceremos a palavra que o Senhor não falou?"},
{v:22,t:"Quando o profeta falar em nome do Senhor e a palavra não suceder nem se cumprir, essa é palavra que o Senhor não falou; por presunção a falou o profeta: não o temas.",n:"O critério é simples e é lento: espera-se para ver. Junto com o do capítulo 13, que julga a doutrina, forma a única prova de profecia que a Lei dá — e nenhuma das duas serve para decidir no calor da hora."}
];

window.TEXTOS_SEED["deuteronomio"][19] = [
{s:"As cidades de refúgio"},
{v:1,t:"Quando o Senhor teu Deus houver exterminado as nações cuja terra te dá, e tu as desapossares e habitares nas suas cidades e nas suas casas,"},
{v:2,t:"separarás três cidades no meio da terra que o Senhor teu Deus te dá em possessão."},
{v:3,t:"Prepararás os caminhos e dividirás em três partes o território da terra que o Senhor teu Deus te der em herança, para que todo homicida tenha para onde fugir."},
{v:4,t:"Este é o caso do homicida que para ali fugir e salvar a vida: aquele que ferir o seu próximo sem querer, sem lhe ter tido ódio de antes;"},
{v:5,t:"como o que for com o seu companheiro ao bosque cortar lenha e, ao dar o golpe com o machado para cortar a árvore, o ferro se soltar do cabo e atingir o companheiro, de modo que morra: esse fugirá para uma dessas cidades e viverá;"},
{v:6,t:"para que o vingador do sangue, enquanto o coração lhe arde, não persiga o homicida e, sendo longo o caminho, o alcance e o mate, sem que ele mereça a morte, pois não tinha ódio ao morto de antes.",n:"O vingador do sangue é o parente mais próximo, a quem competia, pelo costume, reparar a morte. A lei não o abole: rouba-lhe o tempo, pondo uma cidade a menos de um dia de distância, e no intervalo faz caber um julgamento."},
{v:7,t:"Por isso te ordeno: Separarás três cidades."},
{v:8,t:"E quando o Senhor teu Deus dilatar o teu território, como jurou a teus pais, e te der toda a terra que prometeu dar a teus pais —"},
{v:9,t:"se guardares todos estes mandamentos que hoje te ordeno cumprir, amando o Senhor teu Deus e andando sempre nos seus caminhos —, acrescentarás outras três cidades a estas três,"},
{v:10,t:"para que não se derrame sangue inocente no meio da terra que o Senhor teu Deus te dá em herança, e o sangue não caia sobre ti."},
{v:11,t:"Mas se alguém tiver ódio ao seu próximo, lhe armar cilada, se levantar contra ele e o ferir de morte, e depois fugir para uma dessas cidades,"},
{v:12,t:"os anciãos da sua cidade mandarão tirá-lo dali e o entregarão na mão do vingador do sangue, e ele morrerá."},
{v:13,t:"O teu olho não terá piedade dele; assim tirarás de Israel o sangue inocente, e te irá bem."},
{s:"O marco do vizinho"},
{v:14,t:"Não mudarás o marco do teu próximo, posto pelos antigos, na herança que receberes na terra que o Senhor teu Deus te dá para a possuíres.",n:"O marco era uma pedra sem vigilância nenhuma; mudá-la de noite é o roubo que não deixa ladrão. Por isso a lei o trata à parte, e o capítulo 27 lhe põe uma maldição própria."},
{s:"As testemunhas"},
{v:15,t:"Uma só testemunha não se levantará contra alguém por qualquer iniquidade ou pecado, seja qual for o pecado cometido; pela declaração de duas ou de três testemunhas se estabelecerá o fato."},
{v:16,t:"Se uma testemunha falsa se levantar contra alguém, para o acusar de transgressão,"},
{v:17,t:"os dois homens que tiverem a demanda se apresentarão diante do Senhor, diante dos sacerdotes e dos juízes que houver naqueles dias."},
{v:18,t:"Os juízes investigarão bem; e se se achar que a testemunha é falsa, que depôs falsamente contra seu irmão,"},
{v:19,t:"fareis com ele o que ele pensava fazer a seu irmão; assim eliminarás o mal do meio de ti."},
{v:20,t:"Os que ficarem ouvirão e temerão, e nunca mais se cometerá tal maldade no meio de ti."},
{v:21,t:"O teu olho não terá piedade: vida por vida, olho por olho, dente por dente, mão por mão, pé por pé.",n:"A lei do talião não é licença de vingança, mas o seu limite: mais que isso não se pode cobrar. Posta aqui, ela cai sobre o falso testemunho — quem quis matar pela língua responde pela mesma medida. O Senhor Jesus, no Sermão da Montanha, cita a fórmula para ir além dela."}
];

window.TEXTOS_SEED["deuteronomio"][20] = [
{s:"Quando saíres à guerra"},
{v:1,t:"Quando saíres à guerra contra os teus inimigos e vires cavalos e carros, e um povo mais numeroso do que tu, não os temas, porque o Senhor teu Deus, que te tirou da terra do Egito, está contigo."},
{v:2,t:"Quando estiverdes para entrar em combate, o sacerdote se adiantará e falará ao povo,"},
{v:3,t:"dizendo: Ouve, Israel: hoje vos aproximais do combate contra os vossos inimigos; não desfaleça o vosso coração; não temais, não vos assusteis nem tremais diante deles,"},
{v:4,t:"porque o Senhor vosso Deus é quem vai convosco, para pelejar por vós contra os vossos inimigos e para vos salvar."},
{s:"Os que voltam para casa"},
{v:5,t:"Os oficiais falarão ao povo, dizendo: Quem é o homem que edificou casa nova e ainda não a estreou? Vá e volte para a sua casa, para que não morra na guerra e outro a estreie."},
{v:6,t:"Quem é o homem que plantou vinha e ainda não colheu dela? Vá e volte para a sua casa, para que não morra na guerra e outro colha dela."},
{v:7,t:"Quem é o homem que ficou noivo de uma mulher e ainda não a recebeu? Vá e volte para a sua casa, para que não morra na guerra e outro a receba.",n:"Casa, vinha e noiva: as três coisas que se começam e ainda não se gozaram. A guerra não pode ter a última palavra sobre uma vida por acabar. O Senhor Jesus havia de pôr estas mesmas três desculpas na boca dos convidados que faltam ao banquete."},
{v:8,t:"Os oficiais falarão ainda ao povo, dizendo: Quem é o homem medroso e de coração tímido? Vá e volte para a sua casa, para que o coração de seus irmãos não desfaleça como o seu.",n:"Gedeão havia de fazer esta pergunta e de ver vinte e dois mil homens irem embora. Um exército obrigado a lutar não é o que se quer, e vale menos do que o que sobra depois de dispensado o medo."},
{v:9,t:"Quando os oficiais acabarem de falar ao povo, designarão os chefes dos exércitos à frente do povo."},
{s:"O cerco das cidades"},
{v:10,t:"Quando te aproximares de uma cidade para a combater, primeiro lhe oferecerás a paz."},
{v:11,t:"Se ela te responder com paz e te abrir as portas, todo o povo que nela se achar te será tributário e te servirá."},
{v:12,t:"Mas se ela não fizer paz contigo e te fizer guerra, então a sitiarás;"},
{v:13,t:"e, quando o Senhor teu Deus a entregar na tua mão, passarás todos os seus varões ao fio da espada;"},
{v:14,t:"somente as mulheres, as crianças, os animais e tudo o que houver na cidade, todo o seu despojo, tomarás para ti; e comerás o despojo dos teus inimigos, que o Senhor teu Deus te deu."},
{v:15,t:"Assim farás a todas as cidades que estiverem muito longe de ti, que não forem das cidades destas nações."},
{v:16,t:"Mas das cidades destes povos, que o Senhor teu Deus te dá em herança, não deixarás com vida nenhuma alma;"},
{v:17,t:"antes as votarás ao anátema: os heteus, os amorreus, os cananeus, os ferezeus, os heveus e os jebuseus, como o Senhor teu Deus te ordenou,"},
{v:18,t:"para que não vos ensinem a fazer conforme todas as abominações que fizeram aos seus deuses, e pequeis contra o Senhor vosso Deus.",n:"A razão dada não é a raça nem a terra, é o contágio do culto; e a lei do anátema fica expressamente limitada aos povos de dentro da terra. Fora dela vale a regra dos versos 10 a 15, que começa por oferecer a paz."},
{s:"As árvores do cerco"},
{v:19,t:"Quando sitiares uma cidade por muito tempo, combatendo contra ela para a tomar, não destruirás o seu arvoredo, metendo nele o machado; comerás dele, mas não o cortarás. Acaso a árvore do campo é homem, para que seja sitiada por ti?",n:"A pergunta é das mais estranhas de toda a Lei, e por isso das mais lembradas. A guerra pode ter o direito de matar homens; não tem o de matar o que continuará a dar fruto a quem vier depois."},
{v:20,t:"Somente as árvores que souberes não serem de comer, essas destruirás e cortarás, e com elas farás obras de cerco contra a cidade que te faz guerra, até que caia."}
];

window.TEXTOS_SEED["deuteronomio"][21] = [
{s:"O morto que se acha no campo"},
{v:1,t:"Se na terra que o Senhor teu Deus te dá para a possuíres se achar um morto caído no campo, e não se souber quem o matou,"},
{v:2,t:"sairão os teus anciãos e os teus juízes e medirão a distância do morto às cidades ao redor;"},
{v:3,t:"e os anciãos da cidade mais próxima do morto tomarão uma novilha que ainda não tenha trabalhado nem puxado o jugo,"},
{v:4,t:"e a levarão a um vale de águas correntes, que não tenha sido lavrado nem semeado, e ali, no vale, quebrarão o pescoço da novilha."},
{v:5,t:"Então se aproximarão os sacerdotes, filhos de Levi, porque o Senhor teu Deus os escolheu para o servirem e para abençoarem em nome do Senhor, e pela palavra deles se decidirá toda demanda e toda agressão."},
{v:6,t:"E todos os anciãos daquela cidade, os mais próximos do morto, lavarão as mãos sobre a novilha a que no vale se quebrou o pescoço,"},
{v:7,t:"e dirão: As nossas mãos não derramaram este sangue, nem os nossos olhos o viram."},
{v:8,t:"Perdoa, Senhor, ao teu povo Israel, que resgataste, e não ponhas sangue inocente no meio do teu povo Israel. E o sangue lhes será perdoado."},
{v:9,t:"Assim tirarás do meio de ti o sangue inocente, fazendo o que é reto aos olhos do Senhor.",n:"Nenhum culpado, e mesmo assim alguém responde. A cidade mais próxima assume o que não fez, porque o sangue derramado não pode ficar sem dono. Pilatos havia de lavar as mãos com este gesto, mas invertendo-lhe o sentido: aqui quem as lava assume o caso; ali, quem as lava procura sair dele."},
{s:"A mulher cativa"},
{v:10,t:"Quando saíres à guerra contra os teus inimigos, e o Senhor teu Deus os entregar na tua mão, e levares deles cativos,"},
{v:11,t:"se vires entre os cativos uma mulher formosa e a desejares, e quiseres tomá-la por mulher,"},
{v:12,t:"tu a levarás para dentro da tua casa; ela rapará a cabeça e cortará as unhas,"},
{v:13,t:"e tirará de si a roupa do cativeiro; ficará em tua casa e chorará seu pai e sua mãe um mês inteiro. Depois disso a tomarás, e tu serás seu marido, e ela será tua mulher."},
{v:14,t:"Se depois não te agradar, deixarás que vá para onde quiser; mas de modo nenhum a venderás por dinheiro, nem a tratarás como escrava, porque a humilhaste.",n:"A lei não proíbe o que o vencedor fazia: impõe-lhe um mês de espera, um luto e o nome de mulher. Ao fim, se a rejeitar, ela sai livre e ele não recebe nada — de todo o direito antigo, é o único lugar em que a cativa deixa de ser objeto."},
{s:"O direito do primogênito"},
{v:15,t:"Se um homem tiver duas mulheres, uma amada e outra desamada, e ambas lhe derem filhos, e o filho primogênito for da desamada,"},
{v:16,t:"no dia em que fizer herdar a seus filhos o que tiver, não poderá dar a primogenitura ao filho da amada, preterindo o filho da desamada, que é o primogênito;"},
{v:17,t:"mas reconhecerá como primogênito o filho da desamada, dando-lhe porção dobrada de tudo o que tiver, porque ele é o princípio do seu vigor: a ele pertence o direito de primogenitura.",n:"Jacó amou Raquel e não amou Lia, e o primogênito foi de Lia. A lei fecha por decreto o que nos livros dos patriarcas se resolvia sempre pelo afeto, e quase sempre mal."},
{s:"O filho rebelde"},
{v:18,t:"Se alguém tiver um filho contumaz e rebelde, que não obedeça à voz de seu pai nem à voz de sua mãe, e que, mesmo castigado, não lhes dê ouvidos,"},
{v:19,t:"seu pai e sua mãe o tomarão e o levarão aos anciãos da sua cidade, à porta do seu lugar,"},
{v:20,t:"e dirão aos anciãos da cidade: Este nosso filho é contumaz e rebelde, não obedece à nossa voz, é glutão e beberrão."},
{v:21,t:"Então todos os homens da sua cidade o apedrejarão até morrer. Assim eliminarás o mal do meio de ti, e todo o Israel o ouvirá e temerá.",n:"Os pais têm de acusar o próprio filho em público, e o tribunal julga por eles: a lei tira ao pai o poder de vida e morte que tinha em todo o mundo antigo. Os rabinos, examinando as condições exigidas, concluíram que o caso nunca houve nem haveria."},
{s:"O corpo pendurado no madeiro"},
{v:22,t:"Se alguém tiver cometido pecado digno de morte, e for morto, e o pendurares num madeiro,"},
{v:23,t:"o seu cadáver não ficará no madeiro; no mesmo dia o sepultarás, porque o que é pendurado é maldição de Deus; e não contaminarás a terra que o Senhor teu Deus te dá em herança.",n:"São Paulo aplica o verso ao Calvário na Carta aos Gálatas: Cristo nos resgatou da maldição da lei, feito por nós maldição, porque está escrito: maldito todo o que é pendurado no madeiro. Da mesma prescrição vem a pressa da sepultura na tarde da Paixão."}
];

window.TEXTOS_SEED["deuteronomio"][22] = [
{s:"O que se perdeu do irmão"},
{v:1,t:"Se vires extraviado o boi ou a ovelha de teu irmão, não te esconderás deles: tu os farás voltar a teu irmão."},
{v:2,t:"Se teu irmão não estiver perto de ti, ou se não o conheceres, recolherás o animal à tua casa, e ficará contigo até que teu irmão o procure, e então o devolverás."},
{v:3,t:"Assim farás com o seu jumento, com a sua roupa e com toda coisa perdida de teu irmão, que se lhe houver perdido e tu achares: não te poderás esconder."},
{v:4,t:"Se vires o jumento de teu irmão, ou o seu boi, caído no caminho, não te esconderás deles: tu o ajudarás a levantá-los.",n:"A palavra que se repete é esconder-se: o pecado próprio destas leis não é fazer, é passar ao largo. O Senhor Jesus havia de contar a parábola do samaritano sobre o sacerdote e o levita que viram e passaram adiante."},
{s:"Preceitos diversos"},
{v:5,t:"A mulher não usará roupa de homem, nem o homem vestirá roupa de mulher, porque todo o que faz tais coisas é abominação ao Senhor teu Deus."},
{v:6,t:"Se encontrares pelo caminho um ninho de ave, numa árvore ou no chão, com filhotes ou ovos, e a mãe pousada sobre os filhotes ou sobre os ovos, não tomarás a mãe com os filhotes;"},
{v:7,t:"deixarás ir a mãe e tomarás para ti os filhotes, para que te vá bem e prolongues os teus dias.",n:"A mesma promessa que acompanha a honra devida aos pais está aqui ligada ao mais miúdo dos preceitos. Os rabinos discutiram muito a coincidência, e tiraram dela que a recompensa não se mede pelo tamanho da ordem."},
{v:8,t:"Quando edificares uma casa nova, farás parapeito no teu terraço, para que não ponhas culpa de sangue sobre a tua casa, se alguém de lá cair."},
{v:9,t:"Não semearás a tua vinha com duas espécies de semente, para que não fique consagrado tudo: a semente que semeaste e o produto da vinha."},
{v:10,t:"Não lavrarás com boi e jumento juntos."},
{v:11,t:"Não vestirás roupa tecida de lã e linho juntamente."},
{v:12,t:"Farás borlas nas quatro pontas do manto com que te cobrires.",n:"São as franjas que o judeu piedoso usa até hoje no xale de oração. A mulher que sofria de hemorragias tocou na borla do manto do Senhor Jesus; e é por causa delas, alargadas para se verem melhor, que ele repreende os que fazem do preceito adorno."},
{s:"A noiva difamada"},
{v:13,t:"Se um homem tomar mulher, e, depois de coabitar com ela, a aborrecer,"},
{v:14,t:"e lhe atribuir atos vergonhosos, difamando-a, e disser: Tomei esta mulher e, chegando-me a ela, não achei nela os sinais da virgindade;"},
{v:15,t:"então o pai e a mãe da moça tomarão os sinais da virgindade dela e os levarão aos anciãos da cidade, à porta;"},
{v:16,t:"e o pai da moça dirá aos anciãos: Dei minha filha por mulher a este homem, e ele a aborreceu;"},
{v:17,t:"e eis que lhe atribuiu atos vergonhosos, dizendo: Não achei na tua filha os sinais da virgindade. Porém eis aqui os sinais da virgindade de minha filha. E estenderão o lençol diante dos anciãos da cidade."},
{v:18,t:"Então os anciãos daquela cidade tomarão o homem e o castigarão,"},
{v:19,t:"e o condenarão a cem siclos de prata, que darão ao pai da moça, porque difamou uma virgem de Israel; e ela ficará sendo sua mulher, e ele não poderá repudiá-la por todos os seus dias.",n:"A pena é o dobro do preço nupcial do capítulo seguinte, e ainda tira ao marido o direito de repudiar: a mulher que ele quis expulsar fica-lhe para sempre. O peso recai sobre a calúnia, que era o modo barato de desfazer um casamento."},
{v:20,t:"Mas se a acusação for verdadeira, e não se acharem na moça os sinais da virgindade,"},
{v:21,t:"levarão a moça à porta da casa de seu pai, e os homens da sua cidade a apedrejarão até que morra, porque fez loucura em Israel, prostituindo-se na casa de seu pai. Assim eliminarás o mal do meio de ti."},
{s:"O adultério"},
{v:22,t:"Se um homem for achado deitado com mulher casada, morrerão ambos, o homem que se deitou com a mulher, e a mulher. Assim eliminarás o mal de Israel."},
{v:23,t:"Se houver moça virgem, prometida a um homem, e outro a achar na cidade e se deitar com ela,"},
{v:24,t:"levareis ambos à porta daquela cidade e os apedrejareis até que morram: a moça, porque não gritou na cidade; e o homem, porque humilhou a mulher do seu próximo. Assim eliminarás o mal do meio de ti."},
{v:25,t:"Mas se for no campo que o homem achar a moça prometida, e a forçar e se deitar com ela, morrerá só o homem que se deitou com ela;"},
{v:26,t:"à moça não farás nada: ela não cometeu pecado digno de morte. Este caso é como o daquele que se levanta contra o seu próximo e o mata:",n:"O direito antigo tratava o caso como dano ao pai ou ao noivo; aqui a violência é equiparada ao homicídio, e a mulher é declarada inocente por lei. A distinção entre a cidade e o campo é uma presunção de socorro: onde ninguém podia ouvir, presume-se que gritou."},
{v:27,t:"porque a achou no campo; a moça prometida gritou, e não houve quem a salvasse."},
{v:28,t:"Se um homem achar uma moça virgem, que não esteja prometida, e a agarrar e se deitar com ela, e forem apanhados,"},
{v:29,t:"o homem que se deitou com ela dará ao pai da moça cinquenta siclos de prata, e ela ficará sendo sua mulher, porque a humilhou; não poderá repudiá-la por todos os seus dias.",n:"A moça assim desonrada não teria mais casamento possível, e sem casamento não teria sustento; a lei obriga o culpado a mantê-la pela vida inteira, sem direito de a despedir. O Êxodo acrescenta o que aqui se cala: que o pai pode recusar, e o homem paga do mesmo modo."}
];

window.TEXTOS_SEED["deuteronomio"][23] = [
{s:"Quem entra na assembleia do Senhor"},
{v:1,t:"Nenhum homem tomará a mulher de seu pai, nem levantará a orla do manto de seu pai.",n:"Levantar a orla do manto é modo velado de dizer tomar por mulher quem pertence ao pai; a mesma imagem serve, em Rute, para o pedido de casamento, e em Ezequiel, para a aliança do Senhor com Jerusalém."},
{v:2,t:"O que tiver os testículos esmagados ou o membro cortado não entrará na assembleia do Senhor.",n:"Isaías havia de revogar expressamente este verso, prometendo ao eunuco que guarda a aliança um nome melhor do que filhos e filhas dentro da casa de Deus; e nos Atos dos Apóstolos é justamente um eunuco o primeiro estrangeiro batizado."},
{v:3,t:"O bastardo não entrará na assembleia do Senhor; nem mesmo os seus descendentes até à décima geração entrarão na assembleia do Senhor."},
{v:4,t:"O amonita e o moabita não entrarão na assembleia do Senhor; nem mesmo na décima geração entrarão na assembleia do Senhor, nunca jamais,"},
{v:5,t:"porque não vos saíram ao encontro com pão e água no caminho, quando saíeis do Egito, e porque assalariaram contra ti Balaão, filho de Beor, de Petor, na Mesopotâmia, para te amaldiçoar."},
{v:6,t:"Mas o Senhor teu Deus não quis ouvir Balaão, e converteu a maldição em bênção para ti, porque o Senhor teu Deus te amava."},
{v:7,t:"Não lhes procurarás a paz nem o bem, todos os teus dias, para sempre.",n:"Rute é moabita e entra na assembleia sem que ninguém lhe oponha esta lei; dela descende Davi, e do sangue de Davi vem o Messias. A Escritura guarda a regra e guarda também o caso que a rompe."},
{v:8,t:"Não abominarás o edomita, porque é teu irmão; nem abominarás o egípcio, porque foste estrangeiro na sua terra.",n:"O Egito da escravidão é lembrado aqui como a terra que deu abrigo. A memória da opressão não autoriza o ódio, e é esse o argumento que a Lei repete sempre que fala do estrangeiro."},
{v:9,t:"Os filhos que lhes nascerem na terceira geração entrarão na assembleia do Senhor."},
{s:"A pureza do acampamento"},
{v:10,t:"Quando saíres em campanha contra os teus inimigos, guarda-te de toda coisa má."},
{v:11,t:"Se houver entre vós algum homem que se tenha tornado impuro por causa do que lhe aconteceu de noite, sairá do acampamento e não tornará a entrar nele;"},
{v:12,t:"ao cair da tarde se lavará com água, e, ao pôr do sol, voltará ao acampamento."},
{v:13,t:"Terás um lugar fora do acampamento, aonde irás por tuas necessidades;"},
{v:14,t:"e entre os teus utensílios levarás uma estaca: quando te sentares lá fora, cavarás com ela e cobrirás os teus excrementos."},
{v:15,t:"Porque o Senhor teu Deus anda no meio do teu acampamento, para te livrar e para te entregar os teus inimigos; por isso o teu acampamento será santo, para que ele não veja em ti coisa indecente e se aparte de ti.",n:"A razão da regra mais prosaica do livro é a mais alta que se podia dar: Deus passeia no acampamento. A santidade aqui não é ritual, é asseio, e vale exatamente porque alguém mora junto."},
{s:"O escravo fugido"},
{v:16,t:"Não entregarás ao seu senhor o escravo que a ti se acolher, fugindo dele."},
{v:17,t:"Habitará contigo, no meio de ti, no lugar que escolher, em alguma das tuas cidades, onde lhe agradar; não o oprimirás.",n:"Todos os códigos do Oriente antigo que chegaram até nós mandam devolver o escravo fugido, e punem quem o esconde. Este é o único que manda o contrário, e ainda lhe deixa escolher a cidade."},
{s:"Prostituição, juros e votos"},
{v:18,t:"Não haverá prostituta sagrada entre as filhas de Israel, nem prostituto sagrado entre os filhos de Israel."},
{v:19,t:"Não trarás à casa do Senhor teu Deus o salário de uma prostituta nem o preço de um cão, por voto nenhum, porque ambos são abominação ao Senhor teu Deus.",n:"Preço de cão é o nome de desprezo dado ao ganho do prostituto do templo. A lei não discute se o dinheiro é bom: recusa que o culto se lave com ele."},
{v:20,t:"A teu irmão não emprestarás com juros: nem juros de dinheiro, nem de comida, nem de coisa alguma que se empreste com juros."},
{v:21,t:"Ao estrangeiro poderás emprestar com juros, mas a teu irmão não emprestarás com juros, para que o Senhor teu Deus te abençoe em toda a obra das tuas mãos, na terra a que vais para a possuíres.",n:"O empréstimo de que se fala é o de socorro, feito a quem passa necessidade, não o de negócio. Sobre estes versos a Igreja construiu, por muitos séculos, a sua condenação da usura."},
{v:22,t:"Quando fizeres voto ao Senhor teu Deus, não tardarás em cumpri-lo, porque o Senhor teu Deus certamente o requererá de ti, e haveria pecado em ti."},
{v:23,t:"Mas, se te abstiveres de fazer voto, não haverá pecado em ti."},
{v:24,t:"O que saiu dos teus lábios, guarda-o e cumpre-o, conforme o voto espontâneo que fizeste ao Senhor teu Deus, o que prometeste com a tua boca.",n:"O Eclesiastes há de repetir o aviso quase nas mesmas palavras: melhor é não fazer voto do que fazê-lo e não cumprir. O Senhor Jesus foi mais longe e mandou não jurar, bastando o sim e o não."},
{s:"A vinha e a seara do próximo"},
{v:25,t:"Quando entrares na vinha do teu próximo, comerás uvas quantas quiseres, até te fartares, mas não as porás no teu cesto."},
{v:26,t:"Quando entrares na seara do teu próximo, arrancarás espigas com a mão, mas não meterás a foice na seara do teu próximo.",n:"É o direito do que passa com fome: come o quanto quiser, ali mesmo, e não leva nada. Por esta lei os discípulos podiam debulhar espigas ao atravessarem os campos, e a objeção dos fariseus não foi ao furto, mas ao sábado."}
];

window.TEXTOS_SEED["deuteronomio"][24] = [
{s:"O repúdio"},
{v:1,t:"Se um homem tomar mulher e se casar com ela, e depois ela não lhe agradar, por ter ele achado nela alguma coisa vergonhosa, escreverá para ela uma carta de repúdio, e lha dará na mão, e a despedirá de sua casa;",n:"A lei não institui o repúdio: encontra-o em uso e o regula, obrigando a pôr por escrito o que antes se fazia expulsando a mulher pela porta. Que coisa vergonhosa fosse essa dividiu as escolas rabínicas, e é justamente o que perguntam ao Senhor Jesus, a quem responde que Moisés o permitiu pela dureza dos corações."},
{v:2,t:"e, saindo da casa dele, se ela for e se casar com outro homem,"},
{v:3,t:"e este último a aborrecer e lhe fizer carta de repúdio, e lha der na mão, e a despedir de sua casa; ou se este último marido, que a tomou por mulher, morrer;"},
{v:4,t:"então o primeiro marido, que a despediu, não poderá tornar a tomá-la por mulher, depois que ela se contaminou, porque é abominação diante do Senhor. Não farás pecar a terra que o Senhor teu Deus te dá em herança."},
{s:"Preceitos de humanidade"},
{v:5,t:"Quando um homem tiver casado há pouco, não sairá à guerra, nem se lhe imporá encargo algum; ficará livre em sua casa por um ano, para alegrar a mulher que tomou."},
{v:6,t:"Ninguém tomará em penhor as duas mós, nem sequer a mó de cima, porque seria tomar em penhor a própria vida.",n:"A mó de mão era o instrumento com que a casa fazia o pão de cada dia. Levar uma das pedras é deixar a outra inútil: o credor não toma um objeto, toma a refeição de amanhã."},
{v:7,t:"Se se achar alguém que tenha raptado um de seus irmãos, dos filhos de Israel, e o tenha tratado como escravo ou o tenha vendido, esse ladrão morrerá. Assim eliminarás o mal do meio de ti."},
{v:8,t:"Quanto à praga da lepra, guarda-te bem e faze tudo o que te ensinarem os sacerdotes levitas; cuidarás de fazer como lhes ordenei."},
{v:9,t:"Lembra-te do que o Senhor teu Deus fez a Maria no caminho, quando saíeis do Egito."},
{s:"O penhor e o salário"},
{v:10,t:"Quando emprestares alguma coisa ao teu próximo, não entrarás na casa dele para lhe tomar o penhor;"},
{v:11,t:"ficarás de fora, e o homem a quem emprestaste te trará o penhor fora."},
{v:12,t:"Se ele for pobre, não te deitarás com o seu penhor;"},
{v:13,t:"ao pôr do sol lho devolverás sem falta, para que ele durma na sua capa e te abençoe; e isso te será justiça diante do Senhor teu Deus.",n:"O credor não entra na casa: espera na rua, para não escolher ele o que levar. E o que levar devolve à noite, porque a capa do pobre é o seu cobertor. A justiça de que se fala não é a do tribunal: é a que Deus conta a favor de quem a pratica."},
{v:14,t:"Não oprimirás o diarista pobre e necessitado, seja ele teu irmão ou um estrangeiro que está na tua terra, dentro das tuas portas."},
{v:15,t:"No mesmo dia lhe darás o seu salário, antes do pôr do sol, porque é pobre e disso depende a sua vida; para que não clame contra ti ao Senhor, e haja pecado em ti.",n:"São Tiago retoma o verso contra os ricos do seu tempo: eis que o salário que retivestes aos trabalhadores clama, e os clamores chegaram aos ouvidos do Senhor dos exércitos."},
{s:"Cada um pelo seu pecado"},
{v:16,t:"Os pais não morrerão pelos filhos, nem os filhos pelos pais: cada um morrerá pelo seu próprio pecado.",n:"Regra de direito penal, não de teologia da história; mas dela partiram Jeremias e Ezequiel para desfazer o provérbio dos pais que comeram uvas verdes e dos filhos que ficaram com os dentes embotados. O livro dos Reis registra o dia em que um rei de Judá a aplicou, e cita o verso."},
{v:17,t:"Não perverterás o direito do estrangeiro nem do órfão, nem tomarás em penhor a roupa da viúva."},
{v:18,t:"Lembra-te de que foste escravo no Egito e de que dali te resgatou o Senhor teu Deus; por isso te ordeno que faças isto."},
{s:"O que fica para o pobre"},
{v:19,t:"Quando fizeres a colheita no teu campo e esqueceres um feixe no campo, não voltarás para o buscar; será para o estrangeiro, para o órfão e para a viúva, a fim de que o Senhor teu Deus te abençoe em toda a obra das tuas mãos.",n:"A lei transforma o esquecimento em instituição: o que a memória deixou cair passa a pertencer a quem não tem campo. Foi respigando atrás dos ceifeiros, por este direito, que Rute encontrou Booz."},
{v:20,t:"Quando sacudires a tua oliveira, não voltarás a rebuscar os ramos; será para o estrangeiro, para o órfão e para a viúva."},
{v:21,t:"Quando vindimares a tua vinha, não voltarás a rebuscá-la; será para o estrangeiro, para o órfão e para a viúva."},
{v:22,t:"Lembra-te de que foste escravo na terra do Egito; por isso te ordeno que faças isto."}
];

window.TEXTOS_SEED["deuteronomio"][25] = [
{s:"A pena de açoites"},
{v:1,t:"Quando houver demanda entre alguns, e vierem a juízo para serem julgados, absolverão o justo e condenarão o culpado."},
{v:2,t:"E se o culpado merecer açoites, o juiz o fará deitar e açoitar na sua presença, com o número de golpes que a sua culpa merecer."},
{v:3,t:"Quarenta golpes lhe poderá dar, não mais; para que, açoitado além disso com muitos golpes, teu irmão não fique aviltado aos teus olhos.",n:"Teu irmão: assim se chama o condenado, no meio da execução da pena. Por medo de passar do número, os judeus davam trinta e nove, e é essa a conta que São Paulo faz ao dizer que cinco vezes recebeu dos judeus quarenta açoites menos um."},
{v:4,t:"Não atarás a boca ao boi quando debulhar.",n:"São Paulo cita o verso duas vezes para defender o sustento dos que pregam o Evangelho, e pergunta se é dos bois que Deus se ocupa. Não nega a letra: mostra que a razão dela vale também para os homens."},
{s:"O dever do cunhado"},
{v:5,t:"Quando irmãos morarem juntos, e um deles morrer sem deixar filho, a mulher do defunto não se casará fora, com homem estranho; seu cunhado a tomará por mulher e cumprirá para com ela o dever de cunhado."},
{v:6,t:"O primogênito que ela der à luz levará o nome do irmão defunto, para que o seu nome não se apague de Israel.",n:"A instituição existe para dar herdeiro e nome a um morto, e não descendência ao vivo. Os saduceus armaram sobre esta lei o caso dos sete irmãos com que quiseram embaraçar o Senhor Jesus a respeito da ressurreição."},
{v:7,t:"Mas, se o homem não quiser tomar a sua cunhada, ela subirá à porta, aos anciãos, e dirá: Meu cunhado recusa suscitar em Israel o nome de seu irmão, e não quer cumprir para comigo o dever de cunhado."},
{v:8,t:"Então os anciãos da cidade o chamarão e falarão com ele. Se ele insistir e disser: Não quero tomá-la,"},
{v:9,t:"sua cunhada se aproximará dele na presença dos anciãos, lhe tirará a sandália do pé, lhe cuspirá no rosto e dirá: Assim se faz ao homem que não edifica a casa de seu irmão."},
{v:10,t:"E o seu nome será chamado em Israel a casa do descalço.",n:"O livro de Rute conta a cena com a sandália, mas sem a afronta: ali o parente mais próximo recusa, tira o sapato e entrega-o em sinal do trato, e a lei já se cumpre pelo costume, que abrandou o rito."},
{s:"Preceitos diversos"},
{v:11,t:"Quando dois homens brigarem, um com o outro, e a mulher de um deles se aproximar para livrar o marido da mão do que o fere, e estender a mão e o agarrar pelas partes vergonhosas,"},
{v:12,t:"cortarás a mão dela; o teu olho não terá piedade.",n:"Único caso de mutilação em toda a Lei de Israel, contra os muitos dos códigos vizinhos. Os rabinos entenderam desde cedo que a pena se resolvia em indenização, e não literalmente."},
{v:13,t:"Não terás na tua bolsa dois pesos, um grande e um pequeno."},
{v:14,t:"Não terás na tua casa duas medidas, uma grande e uma pequena."},
{v:15,t:"Terás peso exato e justo, e medida exata e justa, para que se prolonguem os teus dias na terra que o Senhor teu Deus te dá;"},
{v:16,t:"porque é abominação ao Senhor teu Deus todo o que faz tais coisas, todo o que comete injustiça.",n:"Dois pesos na mesma bolsa: um para comprar e outro para vender. Amós e os Provérbios voltam ao tema; a lei põe a balança falsa entre as abominações, a par da idolatria."},
{s:"Amalec"},
{v:17,t:"Lembra-te do que te fez Amalec no caminho, quando saías do Egito:"},
{v:18,t:"como te saiu ao encontro no caminho e feriu na tua retaguarda todos os fracos que iam atrás, quando estavas cansado e exausto; e não temeu a Deus."},
{v:19,t:"Quando, pois, o Senhor teu Deus te houver dado descanso de todos os teus inimigos ao redor, na terra que o Senhor teu Deus te dá por herança para a possuíres, apagarás a memória de Amalec de debaixo do céu: não te esqueças.",n:"Apaga a memória e não te esqueças, na mesma frase. O crime lembrado não é a guerra, mas o ter escolhido os últimos da fila. Amalec ficou em Israel como o nome do inimigo sem causa, e Aman, no livro de Ester, é chamado agagita, do nome do seu rei."}
];

window.TEXTOS_SEED["deuteronomio"][26] = [
{s:"As primícias"},
{v:1,t:"Quando entrares na terra que o Senhor teu Deus te dá por herança, e a possuíres e nela habitares,"},
{v:2,t:"tomarás das primícias de todos os frutos do solo que colheres da terra que o Senhor teu Deus te dá, e as porás num cesto, e irás ao lugar que o Senhor teu Deus escolher para ali fazer habitar o seu nome."},
{v:3,t:"E, apresentando-te ao sacerdote que houver naqueles dias, lhe dirás: Declaro hoje ao Senhor teu Deus que entrei na terra que o Senhor jurou a nossos pais dar-nos."},
{v:4,t:"O sacerdote tomará o cesto da tua mão e o porá diante do altar do Senhor teu Deus."},
{v:5,t:"Então dirás, diante do Senhor teu Deus: Meu pai era um arameu errante, e desceu ao Egito, e ali morou como estrangeiro com pouca gente; e ali se tornou nação grande, forte e numerosa.",n:"Este trecho é tido por muitos como a mais antiga confissão de fé de Israel: sem doutrina, sem atributos divinos, só uma sequência de fatos. A Hagadá da Páscoa toma-o por texto e comenta-o palavra por palavra."},
{v:6,t:"Os egípcios nos maltrataram, nos afligiram e nos impuseram dura servidão."},
{v:7,t:"Clamamos ao Senhor, Deus de nossos pais, e o Senhor ouviu a nossa voz e viu a nossa aflição, o nosso trabalho e a nossa opressão."},
{v:8,t:"E o Senhor nos tirou do Egito com mão forte e braço estendido, com grande espanto, com sinais e prodígios;"},
{v:9,t:"e nos trouxe a este lugar e nos deu esta terra, terra que mana leite e mel."},
{v:10,t:"E agora, eis que trago as primícias dos frutos da terra que tu, Senhor, me deste. E as porás diante do Senhor teu Deus, e te prostrarás diante do Senhor teu Deus,"},
{v:11,t:"e te alegrarás com todo o bem que o Senhor teu Deus deu a ti e à tua casa, tu, o levita e o estrangeiro que está no meio de ti.",n:"O lavrador que traz o primeiro fruto do seu campo não fala de si: conta a história de um pai sem terra. A posse só se recebe depois de se confessar que houve um tempo em que não havia nada."},
{s:"A declaração do dízimo"},
{v:12,t:"Quando acabares de separar todo o dízimo dos teus frutos, no terceiro ano, o ano do dízimo, e o deres ao levita, ao estrangeiro, ao órfão e à viúva, para que comam dentro das tuas portas e se fartem,"},
{v:13,t:"então dirás diante do Senhor teu Deus: Tirei de minha casa o que era santo e o dei ao levita, ao estrangeiro, ao órfão e à viúva, conforme tudo o que me ordenaste; não transgredi os teus mandamentos nem deles me esqueci."},
{v:14,t:"Não comi dele no meu luto, nem dele separei coisa alguma estando impuro, nem dele dei coisa alguma a um morto; obedeci à voz do Senhor meu Deus e fiz conforme tudo o que me ordenaste.",n:"Dar comida a um morto era prática dos cultos funerários vizinhos. A declaração é uma prestação de contas em voz alta, e a lei não admite que se pague o dízimo em silêncio."},
{v:15,t:"Olha desde a tua santa morada, desde o céu, e abençoa o teu povo Israel e a terra que nos deste, como juraste a nossos pais, terra que mana leite e mel."},
{s:"A aliança concluída"},
{v:16,t:"Hoje o Senhor teu Deus te ordena que cumpras estes estatutos e estas normas de direito; guarda-os, pois, e cumpre-os de todo o teu coração e de toda a tua alma."},
{v:17,t:"Hoje declaraste que o Senhor é o teu Deus, e que andarás nos seus caminhos, guardarás os seus estatutos, os seus mandamentos e as suas normas de direito, e ouvirás a sua voz;"},
{v:18,t:"e hoje o Senhor declarou que tu és o seu povo, a sua propriedade particular, como te prometeu, e que guardarás todos os seus mandamentos,"},
{v:19,t:"para te pôr acima de todas as nações que fez, em louvor, em fama e em glória, e para que sejas um povo santo ao Senhor teu Deus, como ele falou.",n:"Os dois verbos destes versos são raros e simétricos: cada uma das partes faz da outra o que declara. O código legal acaba aqui, e acaba num pacto de mão dupla."}
];

window.TEXTOS_SEED["deuteronomio"][27] = [
{s:"As pedras com a lei escrita"},
{v:1,t:"Moisés e os anciãos de Israel ordenaram ao povo, dizendo: Guardai todos os mandamentos que hoje vos ordeno."},
{v:2,t:"No dia em que passardes o Jordão para a terra que o Senhor teu Deus te dá, levantarás pedras grandes e as caiarás,"},
{v:3,t:"e nelas escreverás todas as palavras desta lei, depois de teres passado o Jordão, para entrares na terra que o Senhor teu Deus te dá, terra que mana leite e mel, como te prometeu o Senhor, Deus de teus pais."},
{v:4,t:"Quando, pois, houverdes passado o Jordão, levantareis estas pedras, como hoje vos ordeno, no monte Ebal, e as caiarás.",n:"O Pentateuco samaritano lê aqui monte Garizim, e alguns manuscritos antigos concordam com ele: é o lugar exato em que as duas tradições se separam, pois de um lado fica o monte da bênção e de outro o da maldição."},
{v:5,t:"E ali edificarás um altar ao Senhor teu Deus, altar de pedras, sobre as quais não passará ferro;"},
{v:6,t:"de pedras inteiras edificarás o altar do Senhor teu Deus, e sobre ele oferecerás holocaustos ao Senhor teu Deus.",n:"O ferro é a ferramenta e é a arma. Sobre a pedra que o homem trabalhou já passou a sua indústria; o altar quer a pedra como a terra a deu."},
{v:7,t:"Oferecerás também sacrifícios de comunhão, e ali comerás e te alegrarás diante do Senhor teu Deus."},
{v:8,t:"E escreverás nas pedras todas as palavras desta lei, com clareza e nitidez.",n:"Uma lei que se escreve à vista de todos, e não se guarda nos arquivos do templo, pode ser cobrada por qualquer um. É a condição de tudo o que este livro manda."},
{s:"Hoje te tornaste povo do Senhor"},
{v:9,t:"Moisés e os sacerdotes levitas falaram a todo o Israel, dizendo: Cala-te e ouve, Israel: hoje te tornaste povo do Senhor teu Deus."},
{v:10,t:"Ouvirás, pois, a voz do Senhor teu Deus e cumprirás os seus mandamentos e os seus estatutos, que hoje te ordeno."},
{s:"As tribos sobre os dois montes"},
{v:11,t:"Naquele mesmo dia Moisés ordenou ao povo, dizendo:"},
{v:12,t:"Quando houverdes passado o Jordão, estes estarão sobre o monte Garizim, para abençoar o povo: Simeão, Levi, Judá, Issacar, José e Benjamim."},
{v:13,t:"E estes estarão sobre o monte Ebal, para a maldição: Rúben, Gad, Aser, Zabulon, Dã e Neftali.",n:"Sobre o monte da bênção ficam as tribos de Lia e de Raquel, as mulheres livres; sobre o da maldição, as das servas, mais Rúben, que perdeu a primogenitura, e Zabulon, o mais novo de Lia. A repartição segue a ordem das casas, não o mérito de cada tribo."},
{s:"As doze maldições"},
{v:14,t:"Os levitas tomarão a palavra e dirão em alta voz a todos os homens de Israel:"},
{v:15,t:"Maldito o homem que fizer imagem esculpida ou de metal fundido, abominação ao Senhor, obra de mãos de artífice, e a puser em lugar oculto. E todo o povo responderá: Amém.",n:"Quase todas as doze maldições ferem faltas que se cometem às escondidas: o ídolo guardado, o marco mudado de noite, o cego desviado, o golpe às ocultas. Onde o tribunal não chega, fica a maldição, e o povo responde amém contra si mesmo."},
{v:16,t:"Maldito o que desprezar seu pai ou sua mãe. E todo o povo dirá: Amém."},
{v:17,t:"Maldito o que mudar o marco do seu próximo. E todo o povo dirá: Amém."},
{v:18,t:"Maldito o que fizer o cego errar o caminho. E todo o povo dirá: Amém."},
{v:19,t:"Maldito o que perverter o direito do estrangeiro, do órfão e da viúva. E todo o povo dirá: Amém."},
{v:20,t:"Maldito o que se deitar com a mulher de seu pai, porque levanta a coberta do leito de seu pai. E todo o povo dirá: Amém."},
{v:21,t:"Maldito o que se deitar com animal algum. E todo o povo dirá: Amém."},
{v:22,t:"Maldito o que se deitar com sua irmã, filha de seu pai ou filha de sua mãe. E todo o povo dirá: Amém."},
{v:23,t:"Maldito o que se deitar com sua sogra. E todo o povo dirá: Amém."},
{v:24,t:"Maldito o que ferir o seu próximo às ocultas. E todo o povo dirá: Amém."},
{v:25,t:"Maldito o que aceitar suborno para matar uma pessoa inocente. E todo o povo dirá: Amém."},
{v:26,t:"Maldito o que não confirmar as palavras desta lei, cumprindo-as. E todo o povo dirá: Amém.",n:"São Paulo cita este verso aos Gálatas para mostrar que quem se põe debaixo da lei se põe também debaixo da maldição dela, pois ninguém a cumpre inteira. O amém final do povo é, lido assim, a sua própria sentença — e é dela que o capítulo 21, verso 23, dirá como se sai."}
];

window.TEXTOS_SEED["deuteronomio"][28] = [
{s:"As bênçãos"},
{v:1,t:"Se ouvires atentamente a voz do Senhor teu Deus, cuidando de cumprir todos os seus mandamentos que hoje te ordeno, o Senhor teu Deus te exaltará acima de todas as nações da terra."},
{v:2,t:"Virão sobre ti todas estas bênçãos e te alcançarão, se ouvires a voz do Senhor teu Deus.",n:"As bênçãos perseguem e alcançam, como no capítulo se dirá das maldições. A imagem é de caça: o bem corre atrás de quem obedece, e o mal atrás de quem não obedece."},
{v:3,t:"Bendito serás na cidade e bendito serás no campo."},
{v:4,t:"Bendito o fruto do teu ventre, o fruto do teu solo e o fruto dos teus animais, as crias das tuas vacas e dos teus rebanhos."},
{v:5,t:"Bendito o teu cesto e a tua amassadeira."},
{v:6,t:"Bendito serás ao entrares e bendito serás ao saíres."},
{s:"A bênção sobre a obra das tuas mãos"},
{v:7,t:"O Senhor fará que sejam derrotados diante de ti os inimigos que se levantarem contra ti: por um caminho sairão contra ti, e por sete caminhos fugirão de diante de ti."},
{v:8,t:"O Senhor mandará a bênção sobre os teus celeiros e sobre tudo o que empreenderes, e te abençoará na terra que o Senhor teu Deus te dá."},
{v:9,t:"O Senhor te confirmará para si como povo santo, como te jurou, se guardares os mandamentos do Senhor teu Deus e andares nos seus caminhos."},
{v:10,t:"Todos os povos da terra verão que o nome do Senhor é invocado sobre ti, e terão medo de ti."},
{v:11,t:"O Senhor te dará abundância de bens, no fruto do teu ventre, no fruto dos teus animais e no fruto do teu solo, na terra que o Senhor jurou a teus pais dar-te."},
{v:12,t:"O Senhor te abrirá o seu bom tesouro, o céu, para dar chuva à tua terra no seu tempo, e para abençoar toda a obra das tuas mãos; emprestarás a muitas nações, mas tu não tomarás emprestado."},
{v:13,t:"O Senhor te porá por cabeça e não por cauda; estarás sempre por cima e nunca por baixo, se obedeceres aos mandamentos do Senhor teu Deus, que hoje te ordeno guardar e cumprir,"},
{v:14,t:"e não te desviares de nenhuma das palavras que hoje te ordeno, nem para a direita nem para a esquerda, para seguires outros deuses e os servires."},
{s:"As maldições"},
{v:15,t:"Mas, se não ouvires a voz do Senhor teu Deus, para cuidares de cumprir todos os seus mandamentos e os seus estatutos que hoje te ordeno, virão sobre ti todas estas maldições e te alcançarão:",n:"Daqui até ao fim do capítulo as maldições ocupam mais de cinquenta versos, contra catorze de bênçãos. A desproporção é a mesma que se encontra nos tratados de vassalagem assírios, de que este trecho toma a forma e boa parte das imagens."},
{v:16,t:"Maldito serás na cidade e maldito serás no campo."},
{v:17,t:"Maldito o teu cesto e a tua amassadeira."},
{v:18,t:"Maldito o fruto do teu ventre e o fruto do teu solo, as crias das tuas vacas e dos teus rebanhos."},
{v:19,t:"Maldito serás ao entrares e maldito serás ao saíres."},
{s:"A praga e a seca"},
{v:20,t:"O Senhor mandará contra ti a maldição, a confusão e a ameaça em tudo o que empreenderes, até que sejas destruído e pereças depressa, por causa da maldade das tuas obras, com que me abandonaste."},
{v:21,t:"O Senhor fará que a peste se te apegue, até te consumir da terra a que vais para a possuíres."},
{v:22,t:"O Senhor te ferirá com tísica, com febre, com inflamação, com ardor, com secura, com crestamento e com ferrugem; e te perseguirão até que pereças."},
{v:23,t:"O céu que está sobre a tua cabeça será de bronze, e a terra que está debaixo de ti será de ferro.",n:"Bronze em cima, que não deixa passar chuva; ferro embaixo, que não deixa entrar raiz. Entre os dois metais não sobra lugar para nada vivo."},
{v:24,t:"O Senhor dará por chuva à tua terra pó e areia: do céu descerá sobre ti, até que sejas destruído."},
{s:"A derrota e a cegueira"},
{v:25,t:"O Senhor fará que sejas derrotado diante dos teus inimigos: por um caminho sairás contra eles, e por sete caminhos fugirás de diante deles; e serás motivo de espanto para todos os reinos da terra.",n:"É o verso 7 dito ao contrário, palavra por palavra. As maldições não são outras coisas: são as mesmas bênçãos viradas do avesso."},
{v:26,t:"O teu cadáver servirá de comida a todas as aves do céu e aos animais da terra, e não haverá quem os espante."},
{v:27,t:"O Senhor te ferirá com as úlceras do Egito, com tumores, com sarna e com prurido, de que não possas curar-te."},
{v:28,t:"O Senhor te ferirá com loucura, com cegueira e com perturbação da mente;"},
{v:29,t:"e andarás apalpando ao meio-dia, como o cego apalpa nas trevas, e não prosperarás nos teus caminhos; serás oprimido e roubado todos os dias, e não haverá quem te salve."},
{s:"O que se planta e não se colhe"},
{v:30,t:"Ficarás noivo de uma mulher, e outro homem se deitará com ela; edificarás casa, e não habitarás nela; plantarás vinha, e não colherás dela.",n:"As três coisas que no capítulo 20 dispensavam o homem da guerra voltam aqui como castigo, e nenhuma delas se conclui. A maldição não é a morte: é a vida toda feita de coisas começadas."},
{v:31,t:"O teu boi será morto diante dos teus olhos, e não comerás dele; o teu jumento será roubado diante de ti e não voltará a ti; as tuas ovelhas serão dadas aos teus inimigos, e não haverá quem te acuda."},
{v:32,t:"Teus filhos e tuas filhas serão dados a outro povo; os teus olhos o verão e desfalecerão por eles todo o dia, e a tua mão nada poderá fazer."},
{v:33,t:"O fruto da tua terra e todo o teu trabalho comerá um povo que não conheces; serás oprimido e esmagado todos os dias;"},
{v:34,t:"e enlouquecerás por causa do que os teus olhos verão."},
{v:35,t:"O Senhor te ferirá com úlceras malignas nos joelhos e nas pernas, de que não possas curar-te, desde a planta do pé até ao alto da cabeça."},
{s:"O exílio"},
{v:36,t:"O Senhor levará a ti e ao rei que tiveres constituído sobre ti para uma nação que nem tu nem teus pais conhecestes; e ali servirás a outros deuses, de madeira e de pedra."},
{v:37,t:"E serás objeto de espanto, de provérbio e de escárnio entre todos os povos aonde o Senhor te levar."},
{v:38,t:"Lançarás muita semente ao campo e recolherás pouco, porque o gafanhoto a consumirá."},
{v:39,t:"Plantarás vinhas e as cultivarás, mas não beberás do vinho nem colherás uvas, porque o verme as comerá."},
{v:40,t:"Terás oliveiras em todo o teu território, mas não te ungirás com azeite, porque a azeitona cairá."},
{v:41,t:"Gerarás filhos e filhas, mas não serão teus, porque irão para o cativeiro."},
{v:42,t:"Todas as tuas árvores e o fruto da tua terra serão devorados pelos insetos."},
{v:43,t:"O estrangeiro que está no meio de ti subirá cada vez mais acima de ti, e tu descerás cada vez mais abaixo."},
{v:44,t:"Ele te emprestará, e tu não lhe emprestarás; ele será a cabeça, e tu serás a cauda."},
{v:45,t:"Todas estas maldições virão sobre ti, te perseguirão e te alcançarão, até que sejas destruído, porque não ouviste a voz do Senhor teu Deus, nem guardaste os mandamentos e os estatutos que te ordenou."},
{v:46,t:"E serão em ti e na tua descendência por sinal e por prodígio, para sempre."},
{s:"A nação que vem de longe"},
{v:47,t:"Por não teres servido ao Senhor teu Deus com alegria e bondade de coração, na abundância de todas as coisas,",n:"A raiz de tudo o que se seguiu não é a incredulidade nem a idolatria: é ter servido sem alegria. O capítulo 16 mandava ser somente alegre; aqui se cobra a falta."},
{v:48,t:"servirás aos teus inimigos, que o Senhor enviará contra ti, com fome, com sede, com nudez e com falta de tudo; e ele porá um jugo de ferro sobre a tua cerviz, até te destruir."},
{v:49,t:"O Senhor trará contra ti, de longe, dos confins da terra, uma nação que voará como a águia, nação cuja língua não entenderás;",n:"Jeremias e Habacuc haviam de retomar a imagem, aplicando-a aos babilônios; a tradição judaica posterior leu no mesmo verso a águia das legiões de Roma. A profecia não nomeia ninguém, e por isso pôde caber em mais de uma ruína."},
{v:50,t:"nação de rosto feroz, que não respeitará o velho nem terá piedade do menino."},
{v:51,t:"Ela comerá o fruto dos teus animais e o fruto do teu solo, até que sejas destruído; não te deixará trigo, vinho, azeite, nem as crias das tuas vacas e dos teus rebanhos, até te fazer perecer."},
{v:52,t:"Ela te sitiará em todas as tuas cidades, até que caiam os teus muros altos e fortificados, em que confiavas, em toda a tua terra; te sitiará dentro de todas as tuas portas, em toda a terra que o Senhor teu Deus te deu."},
{s:"O cerco"},
{v:53,t:"E comerás o fruto do teu ventre, a carne de teus filhos e de tuas filhas, que o Senhor teu Deus te deu, no cerco e na angústia com que o teu inimigo te apertará.",n:"A cena não ficou no papel: o livro dos Reis conta-a no cerco de Samaria, as Lamentações no de Jerusalém, e Flávio Josefo no do ano setenta. É o ponto em que a maldição desfaz o próprio laço que a bênção prometia, o fruto do ventre."},
{v:54,t:"O homem mais delicado e mimado entre os teus olhará com maus olhos para o seu irmão, para a mulher do seu regaço e para os filhos que lhe restarem,"},
{v:55,t:"para não dar a nenhum deles da carne de seus filhos, que estiver comendo, porque nada mais lhe terá restado, no cerco e na angústia com que o teu inimigo te apertará dentro de todas as tuas portas."},
{v:56,t:"A mulher mais delicada e mimada entre os teus, que de tão mimada e delicada nunca tentou pousar no chão a planta do pé, olhará com maus olhos para o marido do seu regaço, para o seu filho e para a sua filha,"},
{v:57,t:"até para as secundinas que lhe saírem de entre os pés, e para os filhos que der à luz; porque, na falta de tudo, ela os comerá às escondidas, no cerco e na angústia com que o teu inimigo te apertará dentro das tuas portas."},
{s:"As pragas do Egito voltadas contra ti"},
{v:58,t:"Se não cuidares de cumprir todas as palavras desta lei, escritas neste livro, temendo este nome glorioso e terrível, o Senhor teu Deus,"},
{v:59,t:"então o Senhor fará espantosas as tuas pragas e as pragas da tua descendência: pragas grandes e duradouras, enfermidades malignas e persistentes."},
{v:60,t:"Fará voltar sobre ti todos os males do Egito, de que tiveste medo, e se apegarão a ti.",n:"As pragas que caíram sobre os opressores caem agora sobre o povo libertado. Nada na aliança garante que o lugar de Israel na história do êxodo seja para sempre o mesmo."},
{v:61,t:"Também todas as enfermidades e todas as pragas que não estão escritas no livro desta lei, o Senhor as levantará contra ti, até que sejas destruído."},
{v:62,t:"E ficareis poucos em número, vós que éreis como as estrelas do céu em multidão, porque não ouviste a voz do Senhor teu Deus."},
{v:63,t:"E assim como o Senhor se alegrava em vos fazer bem e em vos multiplicar, assim o Senhor se alegrará em vos destruir e em vos consumir; e sereis arrancados da terra a que ides para a possuirdes.",n:"Verso duríssimo, que nenhuma versão antiga suavizou. Ezequiel havia de responder-lhe em nome do mesmo Deus: não me alegro com a morte do ímpio, mas com que se converta e viva."},
{s:"A dispersão"},
{v:64,t:"O Senhor te espalhará entre todos os povos, de uma extremidade da terra à outra; e ali servirás a outros deuses, que nem tu nem teus pais conhecestes, de madeira e de pedra."},
{v:65,t:"E entre essas nações não terás sossego, nem haverá repouso para a planta do teu pé; ali o Senhor te dará coração trêmulo, olhos definhados e alma abatida."},
{v:66,t:"A tua vida estará suspensa diante de ti; terás medo de noite e de dia, e não terás segurança da tua vida.",n:"Os antigos cristãos liam neste verso a figura do Senhor Jesus pendurado no madeiro, tomando ao pé da letra a vida que se vê suspensa diante dos olhos. O sentido primeiro é outro: é o desterrado que acorda sem saber se chega ao fim do dia."},
{v:67,t:"De manhã dirás: Quem me dera fosse noite! E de noite dirás: Quem me dera fosse manhã! Por causa do pavor do teu coração e do que os teus olhos verão."},
{v:68,t:"O Senhor te fará voltar ao Egito em navios, pelo caminho de que te disse: Nunca mais o tornarás a ver; e ali vos oferecereis por venda aos vossos inimigos, como escravos e escravas, e não haverá quem vos compre.",n:"O fim é a desfeita completa do êxodo: o povo volta ao lugar donde foi tirado, e ali descobre que já não vale nem como mercadoria. Pior do que ser escravo é não haver quem queira comprar."},
{s:"A aliança em Moab"},
{v:69,t:"Estas são as palavras da aliança que o Senhor ordenou a Moisés fazer com os filhos de Israel na terra de Moab, além da aliança que fizera com eles no Horeb.",n:"Nas Bíblias que seguem a divisão inglesa este versículo é o primeiro do capítulo 29, e a numeração desse capítulo fica com uma unidade a menos do que aqui. A Nova Vulgata, com o hebraico, faz dele o fecho do que veio antes: é subscrição, e não título."}
];

window.TEXTOS_SEED["deuteronomio"][29] = [
{s:"Vistes, e não entendestes"},
{v:1,t:"Moisés convocou todo o Israel e disse a eles: Vós vistes tudo o que o Senhor fez diante dos vossos olhos, na terra do Egito, ao faraó, a todos os seus servos e a toda a sua terra:"},
{v:2,t:"as grandes provações que os teus olhos viram, aqueles sinais e grandes prodígios."},
{v:3,t:"Mas até ao dia de hoje o Senhor não vos deu coração para entender, nem olhos para ver, nem ouvidos para ouvir.",n:"Isaías há de receber esta mesma frase como missão, e São Paulo cita-a na Carta aos Romanos ao falar do endurecimento de Israel. O que aqui se lamenta não é a falta de provas: é que ver não basta para entender."},
{v:4,t:"Quarenta anos vos conduzi pelo deserto: as vossas roupas não se gastaram sobre vós, nem se gastou a sandália no teu pé;"},
{v:5,t:"não comestes pão nem bebestes vinho ou bebida fermentada, para que soubésseis que eu sou o Senhor vosso Deus."},
{v:6,t:"Chegastes a este lugar; e Seon, rei de Hesbon, e Og, rei de Basã, saíram ao nosso encontro para pelejar, e nós os derrotamos."},
{v:7,t:"Tomamos a terra deles e a demos em herança a Rúben, a Gad e à meia tribo de Manassés."},
{v:8,t:"Guardai, pois, as palavras desta aliança e cumpri-as, para que prospereis em tudo o que fizerdes."},
{s:"Hoje estais todos diante do Senhor"},
{v:9,t:"Hoje estais todos diante do Senhor vosso Deus: os vossos chefes, as vossas tribos, os vossos anciãos e os vossos oficiais, todos os homens de Israel,"},
{v:10,t:"os vossos filhos, as vossas mulheres e o estrangeiro que está no meio do teu acampamento, desde o que te racha a lenha até ao que te tira a água;",n:"A lista desce da cabeça à base e acaba no lenhador e no aguadeiro estrangeiros. Ninguém fica de fora da aliança, e por isso ninguém fica de fora da responsabilidade."},
{v:11,t:"para que entres na aliança do Senhor teu Deus e no juramento que o Senhor teu Deus hoje faz contigo;"},
{v:12,t:"a fim de te constituir hoje como seu povo, e de ser ele o teu Deus, como te prometeu e como jurou a teus pais, Abraão, Isaac e Jacó."},
{v:13,t:"E não é somente convosco que faço esta aliança e este juramento,"},
{v:14,t:"mas com todo aquele que hoje está aqui conosco diante do Senhor nosso Deus, e também com os que hoje não estão aqui conosco.",n:"A aliança é feita com os ausentes, isto é, com os que ainda não nasceram. Daqui vem a convicção judaica de que cada geração esteve presente no monte, e de que o texto não se lê como documento de outros, mas como contrato próprio."},
{s:"A raiz que produz veneno"},
{v:15,t:"Vós sabeis como habitamos na terra do Egito e como passamos pelo meio das nações por onde passastes;"},
{v:16,t:"e vistes as suas abominações e os seus ídolos, de madeira e de pedra, de prata e de ouro, que estavam entre elas."},
{v:17,t:"Que não haja entre vós homem ou mulher, família ou tribo, cujo coração hoje se desvie do Senhor nosso Deus, para ir servir aos deuses daquelas nações; que não haja entre vós raiz que produza veneno e amargura;",n:"A Carta aos Hebreus retoma o verso ao avisar contra a raiz de amargura que brota e contamina muitos. O perigo descrito não é o escândalo público, mas a semente escondida, que ninguém vê enquanto não dá fruto."},
{v:18,t:"e que ninguém, ao ouvir as palavras deste juramento, se felicite no seu coração, dizendo: Terei paz, ainda que ande na dureza do meu coração — o que arrastaria consigo tanto a terra regada como a sedenta."},
{v:19,t:"O Senhor não estará disposto a perdoar-lhe; antes fumegará a ira e o zelo do Senhor contra esse homem, e cairão sobre ele todas as maldições escritas neste livro, e o Senhor apagará o seu nome de debaixo do céu."},
{v:20,t:"O Senhor o separará, para mal, de todas as tribos de Israel, segundo todas as maldições da aliança escritas neste livro da lei."},
{s:"Por que fez o Senhor assim a esta terra?"},
{v:21,t:"E a geração seguinte, os vossos filhos que se levantarem depois de vós, e o estrangeiro que vier de terra longínqua, quando virem as pragas daquela terra e as doenças com que o Senhor a afligiu, dirão:"},
{v:22,t:"Enxofre e sal, toda a sua terra queimada, sem semeadura, sem produção, sem erva que nela cresça, como a destruição de Sodoma e Gomorra, de Adamá e Seboim, que o Senhor destruiu na sua ira e no seu furor."},
{v:23,t:"E todas as nações perguntarão: Por que fez o Senhor assim a esta terra? Que ardor é este de tamanha ira?"},
{v:24,t:"E responderão: Porque abandonaram a aliança do Senhor, Deus de seus pais, que ele fizera com eles quando os tirou da terra do Egito;"},
{v:25,t:"e foram servir a outros deuses e se prostraram diante deles, deuses que não conheciam e que ele não lhes dera por sorte."},
{v:26,t:"Por isso se acendeu a ira do Senhor contra esta terra, fazendo vir sobre ela todas as maldições escritas neste livro."},
{v:27,t:"E o Senhor os arrancou da sua terra com ira, furor e grande indignação, e os lançou em outra terra, como hoje se vê."},
{v:28,t:"As coisas ocultas pertencem ao Senhor nosso Deus, mas as reveladas são para nós e para os nossos filhos, para sempre, a fim de cumprirmos todas as palavras desta lei.",n:"Depois de tantas ameaças, a última palavra é um limite posto à curiosidade: há o que Deus não disse, e sobre isso não se especula; o que disse basta para viver. No texto hebraico dois dos pontos deste versículo levam sinais extraordinários, que os copistas conservaram sem explicar."}
];

window.TEXTOS_SEED["deuteronomio"][30] = [
{s:"A volta e a restauração"},
{v:1,t:"Quando te sobrevierem todas estas palavras, a bênção e a maldição que pus diante de ti, e as trouxeres à memória entre todas as nações para onde o Senhor teu Deus te lançar,"},
{v:2,t:"e te converteres ao Senhor teu Deus e obedeceres à sua voz, conforme tudo o que hoje te ordeno, tu e teus filhos, de todo o teu coração e de toda a tua alma,"},
{v:3,t:"então o Senhor teu Deus mudará a tua sorte e se compadecerá de ti; e tornará a reunir-te de todos os povos entre os quais te espalhou."},
{v:4,t:"Ainda que os teus desterrados estejam na extremidade do céu, dali te ajuntará o Senhor teu Deus e dali te tomará,"},
{v:5,t:"e te introduzirá o Senhor teu Deus na terra que teus pais possuíram, e a possuirás; e ele te fará bem e te multiplicará mais do que a teus pais."},
{v:6,t:"O Senhor teu Deus circuncidará o teu coração e o coração da tua descendência, para amares o Senhor teu Deus de todo o teu coração e de toda a tua alma, a fim de que vivas.",n:"No capítulo 10 a ordem era: circuncidai o vosso coração. Aqui quem circuncida é Deus. É o ponto em que o livro reconhece que o mandado excede a força de quem o recebe, e Jeremias e Ezequiel hão de falar, na mesma linha, de um coração novo."},
{v:7,t:"E o Senhor teu Deus porá todas estas maldições sobre os teus inimigos e sobre os que te odeiam e te perseguem."},
{v:8,t:"Tu te converterás e ouvirás a voz do Senhor, e cumprirás todos os seus mandamentos, que hoje te ordeno."},
{v:9,t:"O Senhor teu Deus te fará prosperar em toda a obra das tuas mãos, no fruto do teu ventre, no fruto dos teus animais e no fruto do teu solo, para o teu bem; porque o Senhor tornará a alegrar-se em ti para te fazer bem, como se alegrou com teus pais,"},
{v:10,t:"se ouvires a voz do Senhor teu Deus, guardando os seus mandamentos e os seus estatutos escritos neste livro da lei, e se te converteres ao Senhor teu Deus de todo o teu coração e de toda a tua alma."},
{s:"A palavra está muito perto de ti"},
{v:11,t:"Este mandamento que hoje te ordeno não é alto demais para ti, nem está longe de ti."},
{v:12,t:"Não está no céu, para dizeres: Quem subirá por nós ao céu e no-lo trará, e no-lo fará ouvir, para que o cumpramos?"},
{v:13,t:"Nem está além do mar, para dizeres: Quem atravessará por nós o mar e no-lo trará, e no-lo fará ouvir, para que o cumpramos?"},
{v:14,t:"Pelo contrário, a palavra está muito perto de ti: está na tua boca e no teu coração, para que a cumpras.",n:"São Paulo, na Carta aos Romanos, toma estes três versos e aplica-os à justiça que vem da fé, lendo o subir ao céu como fazer descer Cristo e o atravessar o abismo como fazê-lo subir dos mortos. E os rabinos tiraram do não está no céu que a interpretação da Lei pertence aos homens, e não a vozes vindas de cima."},
{s:"A vida e a morte postas diante de ti"},
{v:15,t:"Vê que hoje ponho diante de ti a vida e o bem, a morte e o mal."},
{v:16,t:"Se obedeceres aos mandamentos do Senhor teu Deus, que hoje te ordeno, amando o Senhor teu Deus, andando nos seus caminhos e guardando os seus mandamentos, os seus estatutos e as suas normas de direito, então viverás e te multiplicarás, e o Senhor teu Deus te abençoará na terra a que vais para a possuíres."},
{v:17,t:"Mas se o teu coração se desviar e não quiseres ouvir, e te deixares arrastar a prostrar-te diante de outros deuses e a servi-los,"},
{v:18,t:"eu vos declaro hoje que certamente perecereis, e não prolongareis os vossos dias na terra a que vais, passando o Jordão, para a possuíres."},
{v:19,t:"Tomo hoje por testemunhas contra vós o céu e a terra: pus diante de ti a vida e a morte, a bênção e a maldição. Escolhe, pois, a vida, para que vivas, tu e a tua descendência,",n:"É o centro de todo o livro, e a única vez em que a Escritura manda explicitamente escolher. A liberdade não é aqui uma tese sobre a vontade: é a situação de quem tem as duas coisas postas à frente e há de ficar com uma."},
{v:20,t:"amando o Senhor teu Deus, obedecendo à sua voz e apegando-te a ele; porque ele é a tua vida e a extensão dos teus dias, para que habites na terra que o Senhor jurou dar a teus pais, Abraão, Isaac e Jacó."}
];

window.TEXTOS_SEED["deuteronomio"][31] = [
{s:"Josué sucede a Moisés"},
{v:1,t:"Moisés foi e falou estas palavras a todo o Israel,"},
{v:2,t:"e disse a eles: Hoje tenho cento e vinte anos; já não posso sair nem entrar, e o Senhor me disse: Não passarás este Jordão."},
{v:3,t:"O Senhor teu Deus é quem passará adiante de ti; ele destruirá estas nações diante de ti, e tu as desapossarás. Josué é quem passará adiante de ti, como o Senhor disse."},
{v:4,t:"O Senhor lhes fará como fez a Seon e a Og, reis dos amorreus, e à terra deles, quando os destruiu."},
{v:5,t:"O Senhor os entregará a vós, e lhes fareis conforme todo o mandamento que vos ordenei."},
{v:6,t:"Sede fortes e corajosos; não temais nem vos assusteis diante deles, porque o Senhor teu Deus é quem vai contigo: não te deixará nem te desamparará.",n:"A Carta aos Hebreus cita a promessa deste verso para tirar dela uma conclusão sobre o dinheiro: sede sem avareza, contentes com o que tendes, porque ele disse que não te deixarei nem te desampararei."},
{v:7,t:"Moisés chamou Josué e lhe disse, à vista de todo o Israel: Sê forte e corajoso, porque tu entrarás com este povo na terra que o Senhor jurou a seus pais dar-lhes, e tu lha farás herdar."},
{v:8,t:"O Senhor é quem vai adiante de ti; ele será contigo, não te deixará nem te desamparará; não temas nem te assustes."},
{s:"A leitura da lei de sete em sete anos"},
{v:9,t:"Moisés escreveu esta lei e a entregou aos sacerdotes, filhos de Levi, que levavam a arca da aliança do Senhor, e a todos os anciãos de Israel."},
{v:10,t:"E lhes ordenou: Ao fim de cada sete anos, no tempo determinado do ano da remissão, na festa das Tendas,"},
{v:11,t:"quando todo o Israel vier comparecer diante do Senhor teu Deus, no lugar que ele escolher, lerás esta lei diante de todo o Israel, aos seus ouvidos."},
{v:12,t:"Reúne o povo, homens, mulheres e crianças, e o estrangeiro que está dentro das tuas portas, para que ouçam e aprendam a temer o Senhor vosso Deus, e cuidem de cumprir todas as palavras desta lei;"},
{v:13,t:"e para que os filhos deles, que ainda não a conhecem, ouçam e aprendam a temer o Senhor vosso Deus todos os dias que viverdes na terra a que ides, passando o Jordão, para a possuirdes.",n:"Esdras havia de fazer esta leitura diante do povo reunido em Jerusalém, e o livro de Neemias conta o dia inteiro. É a raiz do costume de ler a Escritura em voz alta na assembleia, que passou à sinagoga e daí à liturgia cristã."},
{s:"O Senhor anuncia a infidelidade"},
{v:14,t:"O Senhor disse a Moisés: Eis que se aproximam os dias da tua morte; chama Josué, e apresentai-vos na tenda do encontro, para que eu lhe dê as minhas ordens. Foram, pois, Moisés e Josué e se apresentaram na tenda do encontro;"},
{v:15,t:"e o Senhor apareceu na tenda, numa coluna de nuvem, e a coluna de nuvem parou à entrada da tenda."},
{v:16,t:"E o Senhor disse a Moisés: Eis que vais dormir com teus pais; e este povo se levantará e se prostituirá após os deuses estranhos da terra em que vai entrar; há de abandonar-me e quebrar a aliança que fiz com ele."},
{v:17,t:"Naquele dia a minha ira se acenderá contra ele; eu os abandonarei e lhes esconderei o meu rosto, e serão devorados; virão sobre eles muitos males e angústias, e dirão naquele dia: Não será porque o meu Deus não está no meio de mim que me vieram estes males?"},
{v:18,t:"E eu, naquele dia, esconderei de todo o meu rosto, por causa de todo o mal que fizeram, voltando-se para outros deuses.",n:"Esconder o rosto é a imagem que o saltério usa para a ausência de Deus. Aqui ela é anunciada de antemão, e explicada: o que parece silêncio é resposta."},
{v:19,t:"Agora, pois, escrevei para vós este cântico e ensina-o aos filhos de Israel; põe-no na boca deles, para que este cântico me sirva de testemunho contra os filhos de Israel.",n:"A lei fica com os sacerdotes, guardada junto da arca; o cântico fica na boca do povo. Contra o esquecimento, o livro confia menos ao arquivo do que à memória cantada."},
{v:20,t:"Porque eu o introduzirei na terra que prometi com juramento a seus pais, terra que mana leite e mel; e ele comerá, se fartará e engordará; então se voltará para outros deuses e os servirá, e me desprezará e quebrará a minha aliança."},
{v:21,t:"E quando lhe sobrevierem muitos males e angústias, este cântico responderá diante dele como testemunha, porque não cairá no esquecimento da boca da sua descendência; pois conheço a inclinação que ele tem, ainda hoje, antes de o introduzir na terra que lhe prometi com juramento."},
{v:22,t:"Naquele mesmo dia Moisés escreveu este cântico e o ensinou aos filhos de Israel."},
{v:23,t:"E o Senhor deu as suas ordens a Josué, filho de Nun, dizendo: Sê forte e corajoso, porque tu introduzirás os filhos de Israel na terra que lhes prometi com juramento; e eu serei contigo."},
{s:"O livro ao lado da arca"},
{v:24,t:"Quando Moisés acabou de escrever num livro as palavras desta lei, até ao fim,"},
{v:25,t:"ordenou aos levitas que levavam a arca da aliança do Senhor:"},
{v:26,t:"Tomai este livro da lei e ponde-o ao lado da arca da aliança do Senhor vosso Deus, para que ali esteja como testemunha contra ti.",n:"Ao lado da arca, não dentro: dentro estão as tábuas do decálogo. Foi um livro assim, achado no templo, que desencadeou a reforma de Josias, e é essa a razão por que tantos identificam o rolo encontrado com alguma forma deste."},
{v:27,t:"Porque conheço a tua rebeldia e a tua dura cerviz: se, vivendo eu ainda hoje convosco, fostes rebeldes contra o Senhor, quanto mais depois da minha morte!"},
{v:28,t:"Reuni diante de mim todos os anciãos das vossas tribos e os vossos oficiais, para que eu fale estas palavras aos seus ouvidos e tome por testemunhas contra eles o céu e a terra."},
{v:29,t:"Porque sei que depois da minha morte vos corrompereis de todo e vos desviareis do caminho que vos ordenei; e nos últimos dias vos sobrevirá o mal, por terdes feito o que é mau aos olhos do Senhor, provocando-o à ira com a obra das vossas mãos."},
{v:30,t:"Então Moisés falou, aos ouvidos de toda a assembleia de Israel, as palavras deste cântico, até ao fim:"}
];

window.TEXTOS_SEED["deuteronomio"][32] = [
{s:"Ouvi, ó céus"},
{v:1,l:["Ouvi, ó céus, e eu falarei;","ouça a terra as palavras da minha boca."],n:"O céu e a terra são chamados como testemunhas do processo, conforme o capítulo 31 anunciou. Isaías há de começar do mesmo modo, e daqui vem a forma do pleito profético contra Israel."},
{v:2,l:["Caia como chuva o meu ensino,","destile como orvalho a minha palavra,","como chuvisco sobre a relva,","como aguaceiro sobre a erva."]},
{v:3,l:["Porque vou proclamar o nome do Senhor:","dai glória ao nosso Deus!"]},
{v:4,l:["Ele é a Rocha, e a sua obra é perfeita,","porque todos os seus caminhos são justiça;","Deus fiel e sem iniquidade,","justo e reto é ele."],n:"A Rocha é o título que este cântico usa seis vezes para Deus, e é a primeira vez que a Escritura o emprega assim. Todo o argumento do poema se arma sobre ele: a rocha não se move, e o que mudou foi o povo."},
{v:5,l:["Corromperam-se diante dele;","já não são seus filhos: é a sua mancha;","geração torta e perversa."]},
{v:6,l:["É assim que retribuís ao Senhor,","povo louco e sem sabedoria?","Não é ele o teu pai, que te adquiriu,","que te fez e te estabeleceu?"]},
{v:7,l:["Lembra-te dos dias antigos,","considera os anos de geração em geração;","pergunta a teu pai, e ele te contará;","aos teus anciãos, e eles te dirão."]},
{s:"O que o Senhor fez por Jacó"},
{v:8,l:["Quando o Altíssimo repartia as nações,","quando separava os filhos de Adão,","fixou os limites dos povos","segundo o número dos filhos de Israel."],n:"Os manuscritos hebraicos de Qumran e a versão grega leem aqui segundo o número dos filhos de Deus, isto é, dos anjos postos sobre cada nação. A Nova Vulgata segue o texto massorético, e é o que se traduz; mas a outra lição é provavelmente mais antiga, e explica melhor o verso seguinte."},
{v:9,l:["Porque a porção do Senhor é o seu povo;","Jacó é o quinhão da sua herança."]},
{v:10,l:["Achou-o numa terra deserta,","num ermo de uivos e solidão;","rodeou-o, cuidou dele,","guardou-o como a menina dos seus olhos."]},
{v:11,l:["Como a águia que desperta a sua ninhada","e voeja sobre os seus filhotes,","estendeu as suas asas, tomou-o","e o levou sobre as suas penas."],n:"A águia que empurra os filhotes do ninho e voa por baixo para os aparar é a imagem que o Êxodo já usara no Sinai. Deus ensina a voar tirando o chão, e amparando."},
{v:12,l:["Só o Senhor o conduziu,","e não havia com ele deus estranho."]},
{v:13,l:["Fê-lo cavalgar sobre as alturas da terra,","e comeu os frutos do campo;","fez que sugasse mel da rocha","e azeite da pedra dura,"]},
{v:14,l:["manteiga de vacas e leite de ovelhas,","com a gordura dos cordeiros,","dos carneiros de Basã e dos bodes,","com a flor do trigo;","e bebeste o sangue espumante da uva."]},
{s:"Jesurun engordou e deu coices"},
{v:15,l:["Jesurun engordou e deu coices —","engordaste, engrossaste, ficaste pesado —;","abandonou o Deus que o fez","e desprezou a Rocha da sua salvação."],n:"Jesurun é nome carinhoso de Israel, formado da raiz que significa reto; soa como o justozinho. Aparece quatro vezes na Escritura, três delas neste livro, e sempre que o poema o usa é para dizer o contrário do que o nome promete."},
{v:16,l:["Provocaram-lhe ciúmes com deuses estranhos,","irritaram-no com abominações."]},
{v:17,l:["Sacrificaram a demônios, que não são Deus,","a deuses que não conheciam,","novos, vindos de perto,","que os vossos pais não temeram."],n:"São Paulo cita o verso aos coríntios ao tratar das carnes sacrificadas: o que os gentios imolam, imolam-no aos demônios e não a Deus."},
{v:18,l:["Esqueceste a Rocha que te gerou,","não te lembraste do Deus que te deu à luz."],n:"O segundo verbo é o da mulher que dá à luz. Num livro tão avesso a imagens de Deus, o cântico usa sem hesitar a de mãe, ao lado da de pai do verso 6."},
{s:"A sentença do Senhor"},
{v:19,l:["O Senhor viu e os rejeitou,","irritado com os seus filhos e as suas filhas."]},
{v:20,l:["E disse: Esconderei deles o meu rosto,","verei qual será o seu fim;","porque são geração perversa,","filhos em que não há fidelidade."]},
{v:21,l:["Provocaram-me com o que não é Deus,","irritaram-me com os seus ídolos vãos;","também eu os provocarei com o que não é povo,","com uma nação louca os irritarei."],n:"São Paulo toma este verso na Carta aos Romanos para explicar a entrada dos gentios: o povo que não era povo é chamado, e por ciúme dele se há de salvar Israel."},
{v:22,l:["Porque um fogo se acendeu na minha ira","e arderá até ao mais fundo do abismo;","devorará a terra e o seu produto","e abrasará os fundamentos dos montes."]},
{v:23,l:["Amontoarei males sobre eles,","esgotarei contra eles as minhas flechas."]},
{v:24,l:["Consumidos pela fome, devorados pela febre","e por peste amarga;","enviarei contra eles dentes de feras","e o veneno dos que rastejam no pó."]},
{v:25,l:["Por fora desfilhará a espada,","e por dentro o pavor:","o jovem e a virgem,","a criança de peito e o homem de cabelos brancos."]},
{s:"Mas temi a provocação do inimigo"},
{v:26,l:["Eu teria dito: Vou reduzi-los a nada,","apagarei dentre os homens a sua memória;"]},
{v:27,l:["mas temi a provocação do inimigo,","que os seus adversários se iludissem","e dissessem: A nossa mão triunfou,","não foi o Senhor quem fez tudo isto."],n:"O que trava o castigo não é a inocência do povo, nem sequer a compaixão: é que o vencedor tiraria da ruína a conclusão errada. Deus poupa Israel por causa do que os outros diriam dele."},
{v:28,l:["Porque são nação sem conselho,","e não há neles entendimento."]},
{v:29,l:["Quem dera fossem sábios e entendessem isto,","e considerassem o seu fim!"]},
{v:30,l:["Como poderia um só perseguir mil,","e dois pôr em fuga dez mil,","se a sua Rocha não os tivesse vendido","e o Senhor não os tivesse entregado?"]},
{v:31,l:["Porque a rocha deles não é como a nossa Rocha;","disso são juízes os nossos próprios inimigos."]},
{v:32,l:["A sua videira é da cepa de Sodoma","e dos campos de Gomorra;","as suas uvas são uvas de fel,","e os seus cachos, amargos."]},
{v:33,l:["O seu vinho é veneno de serpentes","e peçonha cruel de víboras."]},
{s:"Minha é a vingança"},
{v:34,l:["Não está isto guardado comigo,","selado nos meus tesouros?"]},
{v:35,l:["Minha é a vingança e a retribuição,","no tempo em que resvalar o seu pé;","porque o dia da sua ruína está próximo,","e o que lhes está preparado se apressa."],n:"São Paulo cita o verso aos romanos para proibir que alguém se vingue por si: não vos vingueis, deixai lugar à ira, porque está escrito que a vingança é minha. A frase que ameaça é a mesma que desarma."},
{v:36,l:["Porque o Senhor julgará o seu povo","e se compadecerá dos seus servos,","quando vir que se lhes foi a força","e não resta nem escravo nem livre."],n:"Julgar é aqui fazer justiça a alguém, não condená-lo. A Carta aos Hebreus cita este verso ao lado do anterior, e o julgamento do povo soa lá como advertência, aqui como socorro."},
{v:37,l:["Então dirá: Onde estão os seus deuses,","a rocha em que se refugiavam,"]},
{v:38,l:["que comiam a gordura dos seus sacrifícios","e bebiam o vinho das suas libações?","Levantem-se e vos ajudem,","sejam eles a vossa proteção!"]},
{v:39,l:["Vede agora que eu, eu o sou,","e não há Deus além de mim.","Eu faço morrer e faço viver,","eu firo e eu curo,","e não há quem livre da minha mão."],n:"O monoteísmo do cântico não é uma tese: é a recusa de repartir com alguém a responsabilidade pelo que acontece. Ana, no primeiro livro de Samuel, havia de cantar a mesma frase sobre o fazer morrer e o fazer viver."},
{v:40,l:["Levanto ao céu a minha mão","e digo: Vivo eu para sempre!"]},
{v:41,l:["Quando eu afiar a minha espada faiscante","e a minha mão empunhar o julgamento,","tomarei vingança dos meus adversários","e darei o pago aos que me odeiam."]},
{v:42,l:["Embriagarei de sangue as minhas flechas,","e a minha espada devorará carne:","o sangue dos mortos e dos cativos,","as cabeças dos chefes inimigos."]},
{v:43,l:["Aclamai, ó nações, o seu povo,","porque ele vingará o sangue dos seus servos,","tomará vingança dos seus adversários","e fará expiação pela sua terra e pelo seu povo."],n:"Este verso tem, nos manuscritos de Qumran e na versão grega, uma forma mais longa, que começa por alegrai-vos, ó céus, com ele, e adorem-no todos os anjos de Deus. É por esse texto que a Carta aos Hebreus o cita, aplicando-o ao Filho. A Nova Vulgata segue a forma breve do hebraico recebido."},
{s:"Moisés entrega o cântico"},
{v:44,t:"Moisés veio e falou todas as palavras deste cântico aos ouvidos do povo, ele e Josué, filho de Nun.",n:"O texto hebraico traz aqui Oseias, filho de Nun, que era o nome de Josué antes de Moisés lho mudar, segundo Números. No último capítulo do Pentateuco o velho nome reaparece, como quem se despede."},
{v:45,t:"E, quando Moisés acabou de falar todas estas palavras a todo o Israel,"},
{v:46,t:"disse a eles: Ponde o coração em todas as palavras com que hoje vos advirto, para que as ordeneis a vossos filhos, a fim de que cuidem de cumprir todas as palavras desta lei."},
{v:47,t:"Porque não é palavra vã para vós: ela é a vossa vida, e por ela prolongareis os vossos dias na terra a que, passando o Jordão, ides para a possuirdes."},
{s:"A ordem de subir ao Nebo"},
{v:48,t:"Naquele mesmo dia o Senhor falou a Moisés, dizendo:"},
{v:49,t:"Sobe a esta montanha de Abarim, ao monte Nebo, que está na terra de Moab, defronte de Jericó, e olha a terra de Canaã, que dou em possessão aos filhos de Israel."},
{v:50,t:"Morrerás na montanha a que subires e serás reunido ao teu povo, como Aarão, teu irmão, morreu no monte Hor e foi reunido ao seu povo;"},
{v:51,t:"porque fostes infiéis para comigo no meio dos filhos de Israel, nas águas de Meribá de Cades, no deserto de Sin, e porque não me santificastes no meio dos filhos de Israel.",n:"Aqui, ao contrário do que diz três vezes na primeira parte do livro, a exclusão de Moisés é atribuída à sua própria falta, como em Números. As duas versões ficam no mesmo livro, sem que ninguém as tenha harmonizado."},
{v:52,t:"Verás a terra diante de ti, mas não entrarás nela, na terra que dou aos filhos de Israel."}
];

window.TEXTOS_SEED["deuteronomio"][33] = [
{s:"O Senhor veio do Sinai"},
{v:1,t:"Esta é a bênção com que Moisés, homem de Deus, abençoou os filhos de Israel antes da sua morte."},
{v:2,l:["Ele disse:","O Senhor veio do Sinai","e alvoreceu para eles desde Seir;","resplandeceu desde o monte Farã","e chegou de Meribá de Cades,","à sua direita um fogo de lei para eles."],n:"Deus vem do sul, dos montes de Edom e de Madiã, e não do céu: é a lembrança mais antiga que Israel guardou de onde veio o seu Deus. Os cânticos de Débora e de Habacuc repetem o mesmo itinerário."},
{v:3,l:["Sim, ele ama os povos;","todos os seus santos estão na tua mão.","Eles se prostraram a teus pés","e receberam das tuas palavras."]},
{v:4,l:["Uma lei nos prescreveu Moisés,","herança da assembleia de Jacó."],n:"Verso que a criança judia aprende de cor antes de qualquer outro, e que na sinagoga se diz ao tirar o rolo da arca."},
{v:5,l:["E houve um rei em Jesurun,","quando se reuniram os chefes do povo","com as tribos de Israel."]},
{s:"Rúben, Judá e Levi"},
{v:6,l:["Viva Rúben e não morra,","ainda que os seus homens sejam poucos."]},
{v:7,l:["E para Judá disse:","Ouve, Senhor, a voz de Judá","e traze-o para o seu povo.","As suas mãos lutem por ele,","e sê tu o seu socorro contra os adversários."],n:"Simeão não recebe bênção nenhuma: é a única tribo que falta na lista. O livro de Josué explica por quê — a sua herança ficou dentro da de Judá, e a tribo acabou absorvida por ela."},
{v:8,l:["E para Levi disse:","Os teus tumim e os teus urim são para o teu homem fiel,","que provaste em Massá,","com quem contendeste nas águas de Meribá;"],n:"Urim e Tumim eram as sortes sagradas que o sacerdote trazia no peitoral, e com que se consultava o Senhor em questões de sim e não. A Escritura nunca descreve como eram nem como funcionavam."},
{v:9,l:["que disse de seu pai e de sua mãe: Não os vi;","que não reconheceu os seus irmãos","nem conheceu os seus filhos.","Porque guardaram a tua palavra","e observaram a tua aliança."],n:"Alude ao dia do bezerro de ouro, em que os levitas passaram a espada contra os seus, e por isso receberam o sacerdócio. O Senhor Jesus havia de dizer coisa parecida, e mais dura, a quem quisesse segui-lo."},
{v:10,l:["Eles ensinarão os teus juízos a Jacó","e a tua lei a Israel;","porão o incenso diante de ti","e o holocausto sobre o teu altar."]},
{v:11,l:["Abençoa, Senhor, a sua força","e aceita a obra das suas mãos.","Fere os lombos dos que se levantam contra ele","e dos que o odeiam, para que não se levantem mais."]},
{s:"Benjamim e José"},
{v:12,l:["Para Benjamim disse:","O amado do Senhor habita seguro junto dele;","o Altíssimo o protege todo o dia","e entre os seus ombros repousa."],n:"Entre os ombros é o vale entre duas encostas; a tradição leu aqui o lugar do templo, que ficava na fronteira de Benjamim com Judá, e o amado a repousar no monte do Senhor."},
{v:13,l:["Para José disse:","Abençoada do Senhor seja a sua terra,","com os dons do céu, com o orvalho","e com o abismo que jaz embaixo;"]},
{v:14,l:["com os frutos que o sol amadurece","e com o que as luas fazem crescer;"]},
{v:15,l:["com o melhor dos montes antigos","e com os dons das colinas eternas;"]},
{v:16,l:["com os frutos da terra e a sua abundância.","O favor daquele que habitou na sarça","venha sobre a cabeça de José,","sobre a fronte do consagrado entre seus irmãos."],n:"A sarça ardente aparece uma só vez fora do Êxodo, e é aqui. O consagrado entre seus irmãos traduz a palavra que também significa príncipe e nazireu; é o mesmo epíteto que Jacó dera a José no seu testamento."},
{v:17,l:["A sua majestade é a do touro primogênito,","e os seus chifres, chifres de búfalo:","com eles há de escornar os povos","até aos confins da terra.","Tais são as miríades de Efraim","e tais os milhares de Manassés."]},
{s:"Zabulon, Issacar, Gad e Dã"},
{v:18,l:["Para Zabulon disse:","Alegra-te, Zabulon, nas tuas saídas,","e tu, Issacar, nas tuas tendas."]},
{v:19,l:["Chamarão os povos ao monte,","e ali oferecerão sacrifícios de justiça;","porque sugarão a abundância dos mares","e os tesouros escondidos da areia."]},
{v:20,l:["Para Gad disse:","Bendito o que fez espaçoso a Gad!","Deita-se como leoa","e despedaça o braço e o crânio."]},
{v:21,l:["Escolheu para si as primícias,","porque ali lhe estava reservada a parte do chefe;","veio à frente do povo,","cumpriu a justiça do Senhor","e os seus juízos com Israel."]},
{v:22,l:["Para Dã disse:","Dã é leãozinho","que salta de Basã."]},
{s:"Neftali e Aser"},
{v:23,l:["Para Neftali disse:","Neftali, farto de favores","e cheio da bênção do Senhor,","possui o mar e o sul."]},
{v:24,l:["Para Aser disse:","Bendito entre os filhos seja Aser!","Seja o favorito de seus irmãos","e mergulhe no azeite o seu pé."]},
{v:25,l:["Ferro e bronze sejam os teus ferrolhos,","e a tua força dure quanto os teus dias."]},
{s:"Não há como o Deus de Jesurun"},
{v:26,l:["Não há como o Deus de Jesurun,","que cavalga os céus em teu socorro","e as nuvens, na sua majestade."]},
{v:27,l:["Refúgio é o Deus dos tempos antigos,","e embaixo estão os braços eternos.","Ele expulsou de diante de ti o inimigo","e disse: Destrói!"],n:"Os braços eternos que sustentam por baixo são a imagem com que o livro fecha, e respondem à do primeiro capítulo, do pai que carrega o filho pelo deserto."},
{v:28,l:["Israel habita em segurança,","à parte, a fonte de Jacó,","numa terra de trigo e de vinho,","e os seus céus destilam orvalho."]},
{v:29,l:["Bem-aventurado és tu, Israel!","Quem é como tu, povo salvo pelo Senhor?","Ele é o escudo do teu socorro","e a espada da tua glória.","Os teus inimigos te adularão,","e tu pisarás sobre as suas alturas."]}
];

window.TEXTOS_SEED["deuteronomio"][34] = [
{s:"Moisés vê a terra"},
{v:1,t:"Moisés subiu das planícies de Moab ao monte Nebo, ao cume do Fasga, que está defronte de Jericó; e o Senhor lhe mostrou toda a terra: Galaad até Dã,"},
{v:2,t:"todo Neftali, a terra de Efraim e de Manassés, toda a terra de Judá até ao mar ocidental,"},
{v:3,t:"o Negueb e a planície, o vale de Jericó, cidade das palmeiras, até Segor."},
{v:4,t:"E o Senhor lhe disse: Esta é a terra que jurei a Abraão, a Isaac e a Jacó, dizendo: À tua descendência a darei. Fiz que a visses com os teus olhos, mas não passarás para lá.",n:"Do alto do Nebo vê-se de fato quase tudo o que o texto enumera, num dia claro. A Escritura não dá a Moisés outra posse da terra senão a do olhar."},
{s:"A morte de Moisés"},
{v:5,t:"E ali morreu Moisés, servo do Senhor, na terra de Moab, conforme a palavra do Senhor.",n:"Servo do Senhor: é o título que Moisés só recebe ao morrer, e que depois ficará sendo o seu nome próprio na Escritura. Conforme a palavra do Senhor diz-se, à letra, pela boca do Senhor; daí a bela expressão dos antigos, que Moisés morreu de um beijo de Deus."},
{v:6,t:"E o sepultou no vale, na terra de Moab, defronte de Bet-Fogor; e ninguém, até ao dia de hoje, soube da sua sepultura.",n:"Quem o sepultou não se diz; o sujeito da frase é o próprio Senhor, e a tradição judaica assim o entendeu. A Carta de São Judas alude a uma disputa entre o arcanjo Miguel e o demônio sobre o corpo de Moisés. O túmulo desconhecido impediu que se lhe fizesse culto."},
{v:7,t:"Moisés tinha cento e vinte anos quando morreu; não se lhe escureceram os olhos, nem se lhe perdeu o vigor."},
{v:8,t:"Os filhos de Israel choraram Moisés nas planícies de Moab por trinta dias, e cumpriram-se os dias do pranto pela morte de Moisés."},
{s:"Josué, e o louvor de Moisés"},
{v:9,t:"Josué, filho de Nun, estava cheio do espírito de sabedoria, porque Moisés lhe tinha imposto as mãos; e os filhos de Israel lhe obedeceram e fizeram como o Senhor ordenara a Moisés."},
{v:10,t:"E nunca mais se levantou em Israel profeta como Moisés, a quem o Senhor conhecesse face a face,",n:"O capítulo 18 prometia um profeta como Moisés; este verso declara que ainda não houve. A Lei acaba com a promessa em aberto, e é dessa distância que vive toda a esperança que se segue."},
{v:11,t:"quanto a todos os sinais e prodígios que o Senhor o enviou a fazer na terra do Egito, ao faraó, a todos os seus servos e a toda a sua terra,"},
{v:12,t:"e quanto a toda a mão forte e a todos os grandes e terríveis feitos que Moisés realizou aos olhos de todo o Israel.",n:"Assim acaba a Torá: não na terra, mas à vista dela; não com a promessa cumprida, mas com um túmulo que ninguém acha e um povo do lado de fora, pronto para passar."}
];
